document.getElementById("pedidos").addEventListener("click",e=>{
  const b = e.target.closest("button[data-p]"); if(!b) return;
  if(EMITIENDO){ toast("Esperá un segundo: se está guardando el comprobante."); return; }
  if(trabadaPorDuda()) return;
  if(S.editando){ toast("Estás cambiando un presupuesto: guardalo o tocá Dejar de editar antes de pasar un pedido."); return; }
  const p = PEDIDOS[+b.dataset.p];
  for(const [c,n] of p.lin){ const l = S.linea.find(x=>x.cod===c); if(l) l.cant+=n; else S.linea.push({cod:c,cant:n}); }
  pintarTicket();
  irA("mostrador");
  toast("El pedido "+p.q+" está cargado en la venta.");
});

/* ======================================================= TECLADO
   Dos listados se manejan igual: el de la venta y el del pedido. En los
   dos, las flechas mueven un renglón marcado y Enter lo suma con la
   cantidad que diga al lado. */
const LISTADOS = [
  {caja:"res",    campo:"q",    sumar:(cod,n)=>sumar(cod,n)},
  {caja:"resPed", campo:"qPed", sumar:(cod,n)=>agregarPed(cod,n)}
];
function listadoActivo(){
  for(const L of LISTADOS){
    const c = document.getElementById(L.caja);
    if(c && c.offsetParent !== null && c.querySelector("tr[data-cod]")) return L;
  }
  return null;
}
function filas(L){ return [...document.getElementById(L.caja).querySelectorAll("tr[data-cod]")]; }
function marcado(L){ return document.getElementById(L.caja).querySelector("tr.marcado"); }

function mover(L, paso){
  const fs = filas(L); if(!fs.length) return;
  const act = marcado(L);
  let i = act ? fs.indexOf(act) + paso : (paso > 0 ? 0 : fs.length - 1);
  if(i < 0) i = fs.length - 1;
  if(i >= fs.length) i = 0;
  for(const t of fs) t.classList.remove("marcado");
  fs[i].classList.add("marcado");
  fs[i].scrollIntoView({block:"nearest"});
}
function sumarMarcado(L){
  const t = marcado(L) || filas(L)[0];
  if(!t) return;
  const cod = t.dataset.cod;
  const campo = document.querySelector("#"+L.caja+' input[data-q="'+cod+'"]');
  L.sumar(cod, campo ? +campo.value : 1);
}

/** La pantalla que se está viendo. */
function vistaActual(){
  for(const v of vistas) if(!document.getElementById("v-"+v).hidden) return v;
  return "mostrador";
}
/** El buscador de la pantalla que se está viendo. */
function buscadorActual(){
  const v = vistaActual();
  if(v === "mostrador") return document.getElementById("q");
  if(v === "pedidos")   return document.getElementById("qPed");
  if(v === "asistente") return document.getElementById("preg");
  if(v === "listas")    return document.getElementById("sUno");
  if(v === "comprobantes") return document.getElementById("cpBusca");
  return null;
}
const escribiendo = e => {
  const t = e.target;
  return t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.tagName === "SELECT" || t.isContentEditable);
};

document.addEventListener("keydown",e=>{
  // Escape cierra lo que esté abierto, en orden de encima hacia abajo.
  if(e.key === "Escape"){
    for(const id of ["aMano","cliNuevo","prvForm","clsForm","envio"]){
      const m = document.getElementById(id);
      if(m && !m.hidden){ m.hidden = true; e.preventDefault(); return; }
    }
    const L = listadoActivo();
    const t = L && marcado(L);
    if(t){ t.classList.remove("marcado"); e.preventDefault(); return; }
    const b = buscadorActual();
    if(b && b.value){ b.value = ""; b.dispatchEvent(new Event("input",{bubbles:true})); e.preventDefault(); }
    return;
  }

  // Los atajos con Alt andan aunque se esté escribiendo.
  if(e.altKey && !e.ctrlKey && !e.metaKey){
    const k = e.key.toLowerCase();
    const enVenta = vistaActual() === "mostrador";
    if(k === "f" && enVenta){ e.preventDefault(); document.getElementById("btnFactura").click(); return; }
    if(k === "p" && enVenta){ e.preventDefault(); document.getElementById("btnPresu").click(); return; }
    if(k === "b" && enVenta){ e.preventDefault(); document.getElementById("btnBorrador").click(); return; }
    if(k === "n" && enVenta){ e.preventDefault(); abrirCliente(); return; }
    if(k === "w" && enVenta){ e.preventDefault(); document.getElementById("btnWhatsVta").click(); return; }
  }

  const L = listadoActivo();

  // Las flechas mueven el listado aunque el foco esté en el buscador:
  // es justo lo que uno hace, escribir y bajar sin soltar el teclado.
  if(L && (e.key === "ArrowDown" || e.key === "ArrowUp")){
    const t = e.target;
    const enNumero = t && t.tagName === "INPUT" && t.type === "number";
    if(!enNumero){ e.preventDefault(); mover(L, e.key === "ArrowDown" ? 1 : -1); return; }
  }
  // Enter suma el marcado. Si no hay ninguno marcado, el primero.
  if(L && e.key === "Enter" && !e.altKey){
    const t = e.target;
    const el = (t && t.nodeType === 1) ? t : null;
    if(el && el.id === L.campo) return;             // eso ya lo maneja el buscador
    if(el && el.closest("#"+L.caja)) return;        // la cantidad del renglón también
    if(escribiendo(e)) return;
    e.preventDefault(); sumarMarcado(L); return;
  }

  if(escribiendo(e)) return;

  // Barra: ir a buscar. Signo de pregunta: la ayuda.
  if(e.key === "/"){
    const b = buscadorActual();
    if(b){ e.preventDefault(); b.focus(); b.select(); }
    return;
  }
  if(e.key === "?"){
    const t = document.getElementById("teclas");
    if(t.hidden){ t.hidden = false; t.classList.add("abierta"); }
    else t.classList.toggle("abierta");
    return;
  }
});

document.getElementById("teclasX").addEventListener("click",()=>{
  document.getElementById("teclas").hidden = true;
  toast("Los atajos vuelven con la tecla ?");
});

/* ============================================== ALTA DE ARTÍCULO
   Todo junto: lo que se escribe, lo que cuesta y a cuánto se vende. El
   código lo propone el sistema y controla que no esté usado, que es el
   error que después cuesta una semana de desorden. */
const ALTA = { seis:CADENA_BASE.slice(), recs:[], editando:null, combo:null };

/* ============================================================ COMBOS
   V.0.99.95. Un combo es un artículo más armado con artículos que ya están:
   su costo es la suma de los costos de las piezas, la Lista 1 es el % que
   se le pone encima y la Lista 2 sobre la 1. Su stock es el que alcanza
   para armarlo, y al venderlo el servidor descuenta cada pieza. */
const esComboArt = p => !!(p && (p.combo || /\\bCOMBOS?\\b/i.test((p.tit || "") + " " + (p.rub || ""))));
/** Lo que falta para vender n de ese combo en el depósito de la venta, o "". */
function faltaParaCombo(c, n){
  if(!c || !c.combo) return "";
  const dep = depAct();
  for(const x of c.combo.piezas){
    const p = prod(x.cod);
    if(!p) return "la pieza " + x.cod + " ya no está en Artículos";
    const hace = n * (Math.max(1, +x.cant || 1)), hay = +((p.dep || {})[dep]) || 0;
    if(hay < hace) return "falta stock de " + p.cod + " " + p.tit.slice(0, 34) + " (hay " + hay + ", hacen falta " + hace + ")";
  }
  return "";
}
/** V.0.11.220: lo que impide VENDER lo que hay en la venta (el presupuesto
    sale igual): un combo sin stock para armarlo en el depósito de la venta,
    o algo que se vende solo en combo cargado suelto. "" si se puede. */
function faltaParaVender(){
  for(const l of S.linea){
    const p = prod(l.cod); if(!p) continue;
    if(p.combo){
      const f = faltaParaCombo(p, l.cant);
      if(f) return "no alcanza para armar " + p.tit.slice(0, 40) + ": " + f;
    } else if(p.vendeSuelto === false) return p.tit.slice(0, 40) + " se vende solo en combo";
  }
  return "";
}
/** Arma el precio y el stock de los combos con lo de hoy de sus piezas. */
function combosDePunto(){
  let n = 0;
  for(const c of PRODUCTOS){
    if(!c || !c.combo || !Array.isArray(c.combo.piezas) || !c.combo.piezas.length) continue;
    const piezas = c.combo.piezas.map(x => ({ p: prod(x.cod), cant: Math.max(1, Math.floor(+x.cant || 1)) }));
    c.comboFalta = piezas.some(x => !x.p || x.p === c || x.p.combo);
    if(c.comboFalta) continue;
    const costo = cent(piezas.reduce((a, x) => a + (+x.p.costo || 0) * x.cant, 0));
    const l1 = +c.combo.l1 || 0, l2 = +c.combo.l2 || 0;
    const pr = preciosDeLista(costo, l1, l2);
    Object.assign(c, { costo, costoBase: costo, costoProducto: costo, flete: 0, fleteFijo: 0, fletePct: 0, otroCosto: 0,
      lista: cent(costo / facIva(+c.iva || 21)), seis: CADENA_BASE.slice(), recs: [], l1, l2,
      contado: pr.contado, unPago: pr.lista2, markup: costo > 0 ? Math.round((pr.contado / costo - 1) * 1000) / 10 : 0, real: true });
    c.dep = { BA: Math.min(...piezas.map(x => Math.floor((+x.p.dep.BA || 0) / x.cant))),
              TS: Math.min(...piezas.map(x => Math.floor((+x.p.dep.TS || 0) / x.cant))) };
    n++;
  }
  return n;
}
/** La ficha cuando es combo: las piezas, y el costo y el stock salen de ellas. */
function pintarCombo(){
  const on = document.getElementById("aEsCombo").checked;
  // V.0.11.221: en un combo, la lista es la suma de los productos sin IVA.
  { const et = document.getElementById("aListaEt"), nc = document.getElementById("aListaCombo");
    if(et) et.textContent = on ? "Suma de los productos, sin IVA" : "Lista del proveedor, sin IVA";
    if(nc) nc.hidden = !on; }
  // El combo se vende como combo: lo de suelto o en combo es de las piezas (V.0.11.217).
  { const vc = document.getElementById("aVendeCaja"); if(vc) vc.hidden = on; }
  document.getElementById("aComboPiezas").hidden = !on;
  for(const id of ["aLista","aMoneda","aDolar","aCont","aFlete","aOtro","aStockBA","aStockTS","aMinBA","aMinTS"]){
    const e = document.getElementById(id); if(e) e.disabled = on;
  }
  if(!on){
    // Sin combo, el código armado de las piezas se va (el escrito a mano queda).
    const cf = document.getElementById("aCodProv");
    if(cf && ALTA.codComboAuto && cf.value.trim() === ALTA.codComboAuto) cf.value = "";
    ALTA.codComboAuto = "";
    altaCuenta(); return;
  }
  const piezas = ALTA.combo || [];
  // V.0.11.219 (Damián: "el código de fabricante, cuando estoy armando un
  // combo, debería sumarse los artículos que elijo y ponerse automáticamente
  // como 3764+4387+5212"): los de las piezas, unidos con "+". Si el que está
  // lo escribieron a mano, queda.
  {
    const cf = document.getElementById("aCodProv");
    const auto = piezas.map(x => { const p = prod(x.cod); return String((p && p.codProv) || x.cod).trim().toUpperCase(); })
      .filter(Boolean).join("+").slice(0, 40);
    const actual = cf ? cf.value.trim().toUpperCase() : "";
    if(cf && (!actual || actual === (ALTA.codComboAuto || ""))) cf.value = auto;
    ALTA.codComboAuto = auto;
  }
  document.getElementById("aComboLista").innerHTML = piezas.length ? piezas.map((x, i) => {
    const p = prod(x.cod);
    return '<div style="display:flex;gap:8px;align-items:center;font-size:12.5px;padding:4px 0;border-bottom:1px solid #eee">'+
      '<b>'+x.cant+' ×</b><span class="num">'+sinEtiquetas(x.cod)+'</span>'+
      '<span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+(p ? p.tit : '<span class="aviso-falta">no está en Artículos</span>')+'</span>'+
      '<span class="num">'+(p ? fmt(cent((+p.costo || 0) * x.cant)) : '')+'</span>'+
      '<button type="button" class="b2" data-combo-quitar="'+i+'" title="Sacar esta pieza" style="padding:2px 8px">✕</button></div>';
  }).join("") : '<span class="por">Todavía no tiene piezas: buscá cada artículo (por nombre, código o código de fabricante) y sumalo.</span>';
  // El costo de las piezas va como lista sin descuentos ni flete: así la
  // cuenta de siempre da ese costo y la Lista 1 es el % del combo.
  const suma = cent(piezas.reduce((a, x) => { const p = prod(x.cod); return a + (p ? (+p.costo || 0) * x.cant : 0); }, 0));
  const iva = +document.getElementById("aIva").value || 21;
  V("aMoneda", "ARS"); V("aLista", plata2(cent(suma / facIva(iva))));
  V("aCont", 0); V("aFlete", "0,00"); V("aOtro", "0,00");
  ALTA.seis = CADENA_BASE.slice(); ALTA.recs = []; ALTA.fletePct = 0;
  const dep = k => piezas.length ? Math.min(...piezas.map(x => { const p = prod(x.cod); return p ? Math.floor((+p.dep[k] || 0) / x.cant) : 0; })) : 0;
  V("aStockBA", dep("BA")); V("aStockTS", dep("TS"));
  pintarMoneda(); pintarAltaSeis(); altaCuenta();
  document.getElementById("aComboAviso").innerHTML = piezas.length
    ? "Los productos suman <b>"+fmt2(cent(suma / facIva(iva)))+"</b> sin IVA ("+fmt(suma)+" con IVA). Alcanza para armar "+dep("BA")+" en Buenos Aires y "+dep("TS")+" en Traslasierra. Al venderlo se descuenta cada pieza."
    : "El costo es la suma de las piezas; la Lista 1 es tu % sobre ese costo. Al venderlo se descuenta cada pieza.";
}
function sumarPiezaCombo(){
  const cod = document.getElementById("aComboCod").value.trim();
  const cant = Math.max(1, Math.min(1000, Math.floor(+document.getElementById("aComboCant").value || 1)));
  if(!cod) return;
  const p = prod(cod);
  if(!p){ toast("No encuentro el artículo " + cod + " en Artículos."); return; }
  if(p.cod === ALTA.editando){ toast("Un combo no puede llevarse a sí mismo."); return; }
  if(p.combo){ toast(p.cod + " ya es un combo: sumá sus piezas sueltas."); return; }
  if(p.vendeCombo === false){ toast(p.cod + " está marcado para venderse solo suelto: no va en combos."); return; }
  ALTA.combo = ALTA.combo || [];
  const ya = ALTA.combo.find(x => x.cod === p.cod);
  if(ya) ya.cant = Math.min(1000, ya.cant + cant);
  else { if(ALTA.combo.length >= 20){ toast("Hasta 20 piezas por combo."); return; } ALTA.combo.push({ cod: p.cod, cant }); }
  V("aComboCod", ""); V("aComboCant", 1);
  { const rc = document.getElementById("aComboRes"); if(rc) rc.hidden = true; }
  pintarCombo();
  document.getElementById("aComboCod").focus();
}

/** El código que sigue, en la numeración que ya usa el catálogo. */
function skuSugerido(){
  const nums = PRODUCTOS.map(p=>+p.cod.split("+")[0]).filter(n=>!isNaN(n) && n < 90000);
  let n = Math.max(0, ...nums) + 1;
  while(PRODUCTOS.some(p=>p.cod.split("+")[0] === String(n))) n++;
  return String(n);
}
/** Uno alternativo, legible, por si prefieren hablar en letras. */
function skuLegible(){
  const m = (document.getElementById("aMarca").value || "GEN").toUpperCase().replace(/[^A-Z]/g,"").slice(0,3) || "GEN";
  const r = (document.getElementById("aRubro").value || "GEN").toUpperCase().replace(/[^A-Z]/g,"").slice(0,3) || "GEN";
  let i = 1, c;
  do { c = m+"-"+r+"-"+String(i).padStart(3,"0"); i++; } while(PRODUCTOS.some(p=>p.cod===c));
  return c;
}
function revisarSku(){
  const v = document.getElementById("aSku").value.trim();
  const av = document.getElementById("aSkuAviso");
  if(!v){ av.innerHTML = "Hace falta un código."; return false; }
  const usado = PRODUCTOS.find(p=>(p.cod === v || p.cod.split("+")[0] === v) && p.cod !== ALTA.editando);
  if(usado){
    av.innerHTML = '<b style="color:var(--bad)">Ese código ya es de otro artículo:</b> '+usado.tit.slice(0,54)+
      '. Cambialo, o vas a tener dos cosas distintas con el mismo número.';
    return false;
  }
  av.innerHTML = '<b style="color:var(--ok)">Libre.</b> No lo tiene ningún otro artículo.';
  return true;
}

/** Los dos escalones del sistema: costo -> Lista 1 -> Lista 2.
    El precio de contado es la Lista 2 menos el recargo de 1 pago. */
function preciosDeLista(costo, l1, l2){
  // Al peso, no a los $100: estas dos listas son la cuenta del sistema y
  // tienen que dar el mismo numero que da el sistema. 72.600 + 25% es
  // 90.750, no 90.800.
  const lista1 = cent(costo * (1 + (+l1||0)/100));
  const lista2 = cent(lista1 * (1 + (+l2||0)/100));
  return { lista1, lista2, contado: cent(lista2 / RECARGO_1PAGO) };
}
/* ===================================================== LA MONEDA
   Hay proveedores que listan en dólares. El costo y las dos listas
   siempre quedan en pesos: lo único que cambia es en qué moneda viene
   el número del proveedor. La cotización queda guardada en esta
   computadora, así no hay que volver a escribirla en cada artículo. */
const DOLAR_GUARDA = "punto.dolar.v1";
let DOLAR = 0;
/** El dólar con que vinieron las listas de GBP de los artículos en dólares
    que se importaron el 23/11/2026, antes de cargar el dólar del formador
    (BNA venta de ese día). Los que se importen después traen el suyo. */
const DOLAR_REF_INICIAL = 1600;
// Solo el del servidor (V.0.99.91): la copia vieja de esta compu se borra.
try{ localStorage.removeItem(DOLAR_GUARDA); }catch(e){}
// El que vale es el del servidor (lo ven todas las compus).
(async () => {
  try{
    const r = await fetch("/sistema/dolar?formador=1", { cache:"no-store", credentials:"same-origin" });
    const d = await r.json();
    if(d && d.formador && +d.formador.valor > 0){
      const antes = DOLAR;
      DOLAR = +d.formador.valor;
      if(DOLAR !== antes) rearmarGbpEnDolares();
    }
  }catch(e){ /* sin conexión: el último que se usó en esta compu */ }
})();
/** Los artículos de GBP con el costo en dólares, con el dólar de ahora. */
function rearmarGbpEnDolares(){
  try{
    const usd = Object.values(GBP_CRUDO).filter(a => a && a.mon === "USD");
    if(!usd.length) return;
    aplicarGbp(usd); repintarTodo();
  }catch(e){ /* todavía no llegaron los de GBP: los arma traerDeGbp */ }
}
function guardarDolarFormador(v){
  fetch("/sistema/dolar", { method:"POST", credentials:"same-origin", cache:"no-store",
    headers:{ "Content-Type":"application/json" }, body: JSON.stringify({ formador:v }) }).catch(() => {});
}

const enDolares = () => document.getElementById("aMoneda").value === "USD";
const dolarAlta = () => aNum(document.getElementById("aDolar").value);
/** Lo que escribió el que carga, pasado a pesos. */
function listaEnPesos(){
  const n = aNum(document.getElementById("aLista").value);
  return enDolares() ? cent(n * dolarAlta()) : cent(n);
}
function pintarMay(){
  document.getElementById("cajaMay").hidden = !document.getElementById("aMay").checked;
}
function pintarMoneda(){
  const usd = enDolares();
  document.getElementById("aSigno").textContent = usd ? "U$S" : "$";
  document.getElementById("cajaLista").classList.toggle("usd", usd);
  document.getElementById("cajaDolar").hidden = !usd;
  if(usd && !dolarAlta() && DOLAR) V("aDolar", plata2(DOLAR));
}

document.addEventListener("input", e => { if(e.target && /^(aFlete|aOtro|aOtroNom)$/.test(e.target.id)) altaCuenta(); });
function altaCuenta(){
  const usd = enDolares();
  const dol = dolarAlta();
  const puesto = aNum(document.getElementById("aLista").value);
  const lista = listaEnPesos();
  const l1 = +document.getElementById("aL1").value || 0;
  const l2 = +document.getElementById("aL2").value || 0;
  const iva = +document.getElementById("aIva").value || 21;
  const cont = limD(document.getElementById("aCont").value);
  const ds = ALTA.seis;
  const fac = factorDe(ds);
  const netoD = cent(lista * fac);                      // después de los descuentos
  // Los recargos de GBP (V.0.99.85): van después de los descuentos.
  const facR = factorRecs(ALTA.recs);
  const neto = facR !== 1 ? cent(netoD * facR) : netoD;
  const conCont = cont > 0 ? cent(neto * (1 - cont/100)) : neto;
  const costoProd = cent(conCont * facIva(iva));
  // El flete fijo del artículo se suma al costo: las listas salen de ahí.
  const fleteFijoA = cent(aNum(document.getElementById("aFlete").value));
  // Sin flete fijo, el % de su proveedor (como lo arma productoDeGbp): si
  // no, abrir un artículo de GBP para tocarle otra cosa le sacaba el flete
  // al precio.
  const flete = fleteFijoA > 0 ? fleteFijoA : (ALTA.fletePct > 0 ? cent(costoProd * ALTA.fletePct / 100) : 0);
  const otro = cent(aNum(document.getElementById("aOtro").value));
  const otroNom = document.getElementById("aOtroNom").value.replace(/[<>]/g, "").trim().slice(0, 40);
  const costo = cent(costoProd + flete + otro);
  const pr = preciosDeLista(costo, l1, l2);
  const contado = pr.contado;
  const mk = costo > 0 ? Math.round((contado/costo - 1) * 1000)/10 : 0;
  const may = document.getElementById("aMay").checked;
  const mayPct = +document.getElementById("aMayPct").value || 0;
  const mayDesde = Math.max(1, +document.getElementById("aMayDesde").value || 1);
  const mayPrecio = cent(costo * (1 + mayPct/100));
  const mayL2 = cent(mayPrecio * (1 + l2/100));
  document.getElementById("aSeisAviso").innerHTML = lista > 0
    ? "<b>"+cadenaTxt(ds)+" = "+pTxt(Math.round(descEquiv(ds)*10)/10)+"%</b>"+
      ", uno sobre otro · te saca "+fmt2(lista-netoD)+" de la lista"+
      (facR !== 1 ? " · y GBP le suma "+recsTxt(ALTA.recs)+" de recargo" : "")
    : "El costo sale solo.";

  // La Lista 1 la pone el que carga: sin ella el artículo sale a precio
  // de costo y el que vende no se entera.
  document.getElementById("aL1").closest("div").classList.toggle("falta", !(l1 > 0));
  document.getElementById("aListasAviso").innerHTML = l1 > 0
    ? "La 1 sobre el costo, la 2 sobre la 1."
    : (l1 < 0 ? '<span class="aviso-falta">La Lista 1 queda por debajo del costo.</span>' : '<span class="aviso-falta">Falta la Lista 1.</span>');

  const r = (k,v,cls,x) => '<div class="r2'+(cls?" "+cls:"")+'"><span class="k">'+k+'</span>'+
    (x ? '<span class="x">'+x+'</span>' : '')+'<span class="v">'+v+'</span></div>';
  document.getElementById("aCuenta").innerHTML = '<div class="cadena" style="padding:0">'+
    (usd ? r("Lista del proveedor", "U$S "+plata2(puesto))+
           r(dol > 0 ? "El dólar, a "+fmt2(dol) : "<b>Falta a cuánto tomás el dólar</b>",
             dol > 0 ? fmt2(lista) : "—", "sub") : "")+
    // V.0.11.221: en un combo, la suma de los productos (ya con sus descuentos).
    (document.getElementById("aEsCombo").checked
      ? r("Suma de los productos, sin IVA", fmt2(lista), null, "cada uno con sus descuentos")
      : r("Lista sin IVA", fmt2(lista))+
        r("Menos los descuentos", "−"+fmt2(lista-netoD),
          null, ds.some(d=>limD(d)>0) ? cadenaTxt(ds) : null))+
    (facR !== 1 ? r("Más los recargos de GBP", "+"+fmt2(neto-netoD), null, recsTxt(ALTA.recs)) : "")+
    (cont > 0
      ? r("Te queda, sin IVA", fmt2(neto))+
        r("Menos el pago contado", "−"+fmt2(neto-conCont), null, pTxt(cont)+"% sobre eso")
      : "")+
    r("<b>Costo sin IVA</b>", "<b>"+fmt2(conCont)+"</b>")+
    (document.getElementById("aEsCombo").checked
      ? r("Más el IVA de los productos", "+"+fmt2(costo-conCont), null, ivaTxt(iva)+", una sola vez")
      : r("Más IVA "+ivaTxt(iva), "+"+fmt2(costo-conCont)))+
    (flete > 0 || otro > 0
      ? r("El producto te cuesta", fmt2(costoProd), null, "el costo más el IVA")+
        (flete > 0 ? r("Más el flete", "+"+fmt2(flete), null, fleteFijoA > 0 ? "fijo por unidad" : pTxt(ALTA.fletePct)+"% del proveedor (con un flete fijo, manda el fijo)") : "")+
        (otro > 0 ? r("Más "+txt(otroNom || "otro costo"), "+"+fmt2(otro), null, "fijo por unidad") : "")+
        r("<b>Te cuesta puesto acá</b>", fmt2(costo), "total", "con lo que se le suma")
      : r("<b>Te cuesta</b>", fmt2(costo), "total", "el costo más el IVA"))+
    // V.0.11.212 ("Lista 1 mayorista y Lista 2 mayorista, y después Lista 1
    // y Lista 2 normal"): primero las dos por mayor, después las de siempre.
    (may ? r("<b>Lista 1 mayorista</b>, "+pTxt(mayPct)+"% sobre el costo", fmt2(mayPrecio), null,
             "+"+fmt2(mayPrecio-costo)+" · desde "+mayDesde+(mayDesde===1?" unidad":" unidades")) +
           r("<b>Lista 2 mayorista</b>, "+pTxt(l2)+"% sobre la Lista 1 mayorista", fmt2(mayL2), "total",
             "+"+fmt2(mayL2-mayPrecio)+" · desde "+mayDesde+(mayDesde===1?" unidad":" unidades")) : "")+
    r("<b>Lista 1</b>, "+pTxt(l1)+"% sobre el costo", fmt2(pr.lista1), null, "+"+fmt2(pr.lista1-costo))+
    r("<b>Lista 2</b>, "+pTxt(l2)+"% sobre la Lista 1", fmt2(pr.lista2), "total", "+"+fmt2(pr.lista2-pr.lista1))+
    (may && mayL2 > pr.lista2
      ? '<p class="nota" style="padding:8px 0 0;color:var(--bad)">El precio por mayor te está quedando más caro que la Lista 2. Bajale el porcentaje.</p>'
      : "")+
    (costo>0 && l1 < 10
      ? '<p class="nota" style="padding:8px 0 0;color:var(--bad)"><b>Así no alcanza.</b> Con '+pTxt(l1)+'% sobre el costo no cubrís los cargos de venta ni el costo de tener la plata parada.</p>'
      : '<p class="nota" style="padding:8px 0 0">Lo que termina pagando el cliente depende de cómo pague. Eso se decide en la venta, no acá.</p>')+
    enGbpTxt()+
  '</div>';
}
/** Lo que dice GBP del artículo que se está editando: sus dos listas (para
    comparar con la cuenta de arriba), el mínimo y el óptimo de stock. */
function enGbpTxt(){
  const a = ALTA.editando ? GBP_CRUDO[ALTA.editando] : null;
  if(!a) return "";
  const p = PRODUCTOS.find(x => x.cod === ALTA.editando);
  const partes = ["Lista 1 <b>"+fmt2(+a.lista1)+"</b>", "Lista 2 <b>"+fmt2(+a.lista2)+"</b>"];
  if(p && p.minGbp > 0) partes.push("stock mínimo "+p.minGbp);
  if(p && p.optGbp > 0) partes.push("óptimo "+p.optGbp);
  return '<p class="nota" style="padding:8px 0 0">En GBP: '+partes.join(" · ")+"."+
    (p && p.dtoInfo === "no cierra" && p.cadenaGbp
      ? ' <b style="color:var(--warn)">Los descuentos de GBP ('+cadenaTxt(p.cadenaGbp.cadena)+(p.cadenaGbp.recs.length ? " y "+recsTxt(p.cadenaGbp.recs)+" de recargo" : "")+
        ') dan un costo más alto que su Lista 1: revisalos en GBP.</b> Así como está, se vende por debajo del costo.'
      : p && p.dtoInfo === "sin dólar" && p.cadenaGbp
      ? ' El costo de GBP está en dólares (U$S '+plata2(p.listaMon || 0)+') y falta el dólar del formador: el costo sale de la Lista 1 ÷ 1,25. Descuentos de GBP: '+cadenaTxt(p.cadenaGbp.cadena)+'.'
      : p && !p.dtoGbp ? " Sin los descuentos de GBP todavía: el costo sale de la Lista 1 ÷ 1,25." : "")+'</p>';
}

const V = (id,v) => { document.getElementById(id).value = v; if(id === "aContDias") marcarDias(id); };
/** V.0.11.270: el plazo del pago escrito: "60" o "30-60-90" (cheques).
    {dias: el último, cheques: [30, 60, 90] o null si es uno solo}. */
function leerPlazo(t){
  const ns = String(t == null ? "" : t).split(/[^0-9]+/).filter(Boolean).map(n => Math.max(0, Math.min(365, Math.floor(+n))));
  const u = [...new Set(ns)].sort((a, b) => a - b).slice(0, 6);
  if(!u.length) return { dias: 60, cheques: null };
  return { dias: u[u.length - 1], cheques: u.length > 1 ? u : null };
}
/** Para el casillero: "60" o "30-60-90". */
const plazoTxt = p => Array.isArray(p.contCheques) && p.contCheques.length > 1 ? p.contCheques.join("-") : String(p.contDias || 60);
/** Para leer: "a 60 días" o "con 3 cheques a 30-60-90 días". */
const plazoLargo = p => Array.isArray(p.contCheques) && p.contCheques.length > 1
  ? "con " + p.contCheques.length + " cheques a " + p.contCheques.join("-") + " días" : "a " + (p.contDias || 60) + " días";
/** El botón (30, 60, 90 o 3 cheques) que coincide con lo escrito. */
function marcarDias(id){
  const inp = document.getElementById(id), box = document.querySelector('.dias-ya[data-para="' + id + '"]');
  if(!inp || !box) return;
  const ahora = plazoTxt({ contDias: leerPlazo(inp.value).dias, contCheques: leerPlazo(inp.value).cheques });
  for(const b of box.querySelectorAll("button[data-dias]")) b.classList.toggle("on", b.dataset.dias === ahora);
}
document.addEventListener("click", e => {
  const b = e.target.closest(".dias-ya button[data-dias]"); if(!b) return;
  const id = b.closest(".dias-ya").dataset.para, inp = document.getElementById(id); if(!inp) return;
  inp.value = b.dataset.dias;
  // Como si lo hubiera escrito: así se guarda el borrador de Crear uno.
  inp.dispatchEvent(new Event("input", { bubbles: true }));
  inp.dispatchEvent(new Event("change", { bubbles: true }));
  marcarDias(id);
});
for(const id of ["aContDias", "xContDias"]){
  const inp = document.getElementById(id);
  if(inp){ inp.addEventListener("input", () => marcarDias(id)); marcarDias(id); }
}
function abrirAlta(p){
  document.getElementById("altaCuerpo").hidden = false;
  document.getElementById("aGuardarArriba").hidden = false;
  document.getElementById("btnAbrirAlta").textContent = "Cerrar";
  document.getElementById("aMarcas").innerHTML =
    [...new Set(PRODUCTOS.map(x=>x.prov))].sort().map(x=>'<option value="'+x+'">').join("");
  document.getElementById("aRubro").innerHTML =
    // COMBO al final: un artículo nuevo no arranca como combo.
    [...new Set(PRODUCTOS.map(x=>x.rub))].filter(r => r && r !== "COMBO").sort().concat(["COMBO"]).map(r=>'<option>'+r+'</option>').join("");

  for(const id of G_T) document.getElementById(id).value = "";
  document.getElementById("armaTit").hidden = true;
  document.getElementById("btnArmarTit").textContent = "Armarlo";
  ALTA.editando = p ? p.cod : null;
  ALTA.fletePct = p && !(+p.fleteFijo > 0) ? (+p.fletePct || 0) : 0;
  document.getElementById("altaTit").textContent = p ? "Editar el artículo" : "Uno por uno";
  document.getElementById("altaSub").textContent = p
    ? p.cod.split("+")[0]+" · "+p.tit.slice(0,40)
    : "el precio se arma solo";
  document.getElementById("aGuardar").textContent = p ? "Guardar los cambios" : "Guardar el artículo";

  if(p){
    // Los descuentos guardados del artículo; si no tiene, los del proveedor.
    ALTA.seis = (p.seis || cadenaDe(p.prov)).slice(0,N_DTOS);
    ALTA.recs = Array.isArray(p.recs) ? p.recs.slice() : [];
    V("aMarca", p.prov); V("aRubro", p.rub); V("aTit", p.tit); V("aDesc", p.desc || "");
    V("aSku", p.cod); V("aIva", ivaDe(p));
    V("aMoneda", p.mon === "USD" ? "USD" : "ARS");
    V("aDolar", p.mon === "USD" && p.dolar ? plata2(p.dolar) : (DOLAR ? plata2(DOLAR) : ""));
    document.getElementById("aDolarPropio").checked = !!p.dolarPropio;
    V("aLista", plata2(p.mon === "USD" ? (p.listaMon || 0) : (p.lista || 0)));
    V("aCont", p.dctoCont || 0); V("aContDias", plazoTxt(p));
    V("aFlete", plata2(p.fleteFijo || 0)); V("aOtro", plata2(p.otroCosto || 0)); V("aOtroNom", p.otroNombre || "");
    V("aBulto", +p.bulto > 1 ? Math.floor(+p.bulto) : 1);
    document.getElementById("aPromo").checked = !!p.promo;
    document.getElementById("aMay").checked = !!p.may;
    V("aMayPct", p.mayPct != null ? p.mayPct : 15);
    V("aMayDesde", p.mayDesde || 10);
    V("aCodProv", p.codProv || "");
    V("aStockBA", p.dep.BA); V("aStockTS", p.dep.TS);
    V("aMinBA", +p.minBA || 0); V("aMinTS", +p.minTS || 0);
    document.getElementById("aVendeSuelto").checked = p.vendeSuelto !== false;
    document.getElementById("aVendeCombo").checked = p.vendeCombo !== false;
    // Si nunca se le pusieron las dos listas, se deducen del precio que tiene
    // hoy: así abre mostrando lo que de verdad vale, no un precio inventado.
    const l1 = p.l1 != null ? p.l1 : 25;
    const base = redondear(p.costo * (1 + l1/100));
    V("aL1", l1);
    V("aL2", p.l2 != null ? p.l2 : Math.round((p.unPago/base - 1) * 1000)/10);
  } else {
    // Un artículo nuevo arranca sin descuentos: los pone el que carga.
    ALTA.seis = CADENA_BASE.slice(); ALTA.recs = [];
    V("aMarca",""); V("aTit",""); V("aDesc","");
    V("aStockBA",0); V("aStockTS",0); V("aMinBA",0); V("aMinTS",0); document.getElementById("aVendeSuelto").checked = true; document.getElementById("aVendeCombo").checked = true; V("aL1",25); V("aL2",25); V("aIva",21); V("aCont",0); V("aContDias",60); V("aFlete","0,00"); V("aOtro","0,00"); V("aOtroNom",""); V("aBulto","1");
    V("aLista","0,00"); V("aMoneda","ARS");
    V("aDolar", DOLAR ? plata2(DOLAR) : "");
    document.getElementById("aDolarPropio").checked = false;
    document.getElementById("aPromo").checked = false;
    document.getElementById("aMay").checked = false;
    V("aMayPct", 15); V("aMayDesde", 10);
    V("aCodProv","");
    V("aSku", skuSugerido());
  }
  while(ALTA.seis.length < N_DTOS) ALTA.seis.push(0);
  ALTA.combo = p && p.combo ? p.combo.piezas.map(x => ({ cod: x.cod, cant: x.cant })) : null;
  ALTA.codComboAuto = "";
  document.getElementById("aEsCombo").checked = !!(p && p.combo);
  V("aComboCod", ""); V("aComboCant", 1);
  pintarCombo();
  pintarMoneda();
  pintarMay();
  pintarAltaSeis();
  revisarSku(); altaCuenta();
  pintarProvSel(p ? String(p.cat || "").trim() : "");
  pintarMarcaSel();
  pintarSubSel(p ? p.subrubro || "" : "");
  try{ pintarAvisoBorrador(null); }catch(e){}
  FORMA.alta = null; { const fa = document.getElementById("aFormaAviso"); if(fa){ fa.hidden = true; fa.innerHTML = ""; } }
  // Los de la pantalla Proveedores, si todavía no se trajeron (V.0.11.203).
  if(!PRV.lista.length) cargarPrvSiFalta().then(() => { pintarProvSel(provElegido()); pintarMarcaSel(); }).catch(() => {});
  document.getElementById("aTit").dispatchEvent(new Event("input"));
  document.getElementById("altaCuerpo").scrollIntoView({block:"nearest", behavior:"smooth"});
  document.getElementById(p ? "aTit" : "aProvSel").focus();
}
/** V.0.11.202 (Damián: "en marca me debería dar a elegir las marcas que
    tengo disponibles, si no crear una nueva"). La lista de marcas, con
    cuántos artículos tiene cada una, y al final "+ Crear una marca nueva…".
    Lo que se guarda sigue saliendo de #aMarca. */
/** V.0.11.202 (Damián: "haceme proveedor y después marca"). Los
    proveedores: los cargados en Proveedores y los que ya tienen los
    artículos (el dato que trae GBP), sin repetir, con cuántos artículos. */
function pintarProvSel(actual, selId, inpId){
  const sel = document.getElementById(selId || "aProvSel"), inp = document.getElementById(inpId || "aProvNuevo");
  if(!sel || !inp) return;
  const cuenta = new Map(), nombre = new Map();
  const poner = n => { n = String(n || "").replace(/\\s+/g, " ").trim(); if(!n) return null; const k = plano(n); if(!nombre.has(k)) nombre.set(k, n); return k; };
  for(const x of PRODUCTOS){ const k = poner(x.cat); if(k) cuenta.set(k, (cuenta.get(k) || 0) + 1); }
  try{ for(const pv of (PRV.lista || [])) if(pv && !pv.inactivo) poner(pv.razonSocial); }catch(e){}
  const ks = [...nombre.keys()].sort((a, b) => COLL_ES.compare(nombre.get(a), nombre.get(b)));
  sel.innerHTML = '<option value="">Elegí el proveedor…</option>' +
    ks.map(k => '<option value="' + atrib(nombre.get(k)) + '">' + txt(nombre.get(k)) + (cuenta.get(k) ? ' (' + cuenta.get(k) + ')' : '') + '</option>').join("") +
    '<option value="__nuevo">+ Proveedor nuevo…</option>';
  const v = String(actual || "").trim();
  const igual = v ? nombre.get(plano(v)) : null;
  if(!v){ sel.value = ""; inp.value = ""; inp.hidden = true; }
  else if(igual){ sel.value = igual; inp.value = ""; inp.hidden = true; }
  else { sel.value = "__nuevo"; inp.value = v; inp.hidden = false; }
}
/** V.0.11.207: los subrubros (Damián: "son categorías LAVATORIO, DUCHA,
    BIDET, etc."): los de siempre y los que ya tienen los artículos. */
const SUBRUBROS_BASE = ["LAVATORIO","INODORO","BIDET","DEPÓSITO","ASIENTO","MINGITORIO","BACHA","DUCHA","BAÑERA",
  "COCINA","LAVADERO","MONOCOMANDO","MAMPARA","RECEPTÁCULO","VANITORY","BOTIQUÍN","ESPEJO","ACCESORIO DE BAÑO",
  "TERMOTANQUE","CALEFÓN","TANQUE DE AGUA","BOMBA","CAÑO","CONEXIÓN","VÁLVULA","REJILLA","REPUESTO"];
function pintarSubSel(actual, selId, inpId){
  const sel = document.getElementById(selId || "aSubSel"), inp = document.getElementById(inpId || "aSubNuevo");
  if(!sel || !inp) return;
  const cuenta = new Map(), nombre = new Map();
  const poner = n => { n = String(n || "").replace(/\\s+/g, " ").trim().toUpperCase(); if(!n) return null; const k = plano(n); if(!nombre.has(k)) nombre.set(k, n); return k; };
  for(const n of SUBRUBROS_BASE) poner(n);
  for(const x of PRODUCTOS){ const k = poner(x.subrubro); if(k) cuenta.set(k, (cuenta.get(k) || 0) + 1); }
  const ks = [...nombre.keys()].sort((a, b) => COLL_ES.compare(nombre.get(a), nombre.get(b)));
  sel.innerHTML = '<option value="">Sin subrubro</option>' +
    ks.map(k => '<option value="' + atrib(nombre.get(k)) + '">' + txt(nombre.get(k)) + (cuenta.get(k) ? ' (' + cuenta.get(k) + ')' : '') + '</option>').join("") +
    '<option value="__nuevo">+ Crear un subrubro nuevo…</option>';
  const v = String(actual || "").trim();
  const igual = v ? nombre.get(plano(v.toUpperCase())) : null;
  if(!v){ sel.value = ""; inp.value = ""; inp.hidden = true; }
  else if(igual){ sel.value = igual; inp.value = ""; inp.hidden = true; }
  else { sel.value = "__nuevo"; inp.value = v.toUpperCase(); inp.hidden = false; }
}
function subElegido(selId, inpId){
  const sel = document.getElementById(selId || "aSubSel"); if(!sel) return "";
  return sel.value === "__nuevo" ? document.getElementById(inpId || "aSubNuevo").value.replace(/\\s+/g, " ").trim().toUpperCase() : sel.value;
}
document.getElementById("aSubSel").addEventListener("change", e => {
  const inp = document.getElementById("aSubNuevo");
  if(e.target.value === "__nuevo"){ inp.value = ""; inp.hidden = false; inp.focus(); }
  else inp.hidden = true;
});
// El nuevo que se escribe: si ya existe, se elige ese de la lista.
document.getElementById("aSubNuevo").addEventListener("change", e => {
  const sel = document.getElementById("aSubSel");
  const v = plano(e.target.value.trim().toUpperCase()); if(!v) return;
  const opc = [...sel.options].find(o => o.value && o.value !== "__nuevo" && plano(o.value) === v);
  if(opc){ sel.value = opc.value; e.target.hidden = true; toast(opc.value + " ya existe: quedó elegido de la lista."); }
});
/** El proveedor elegido (o el nuevo escrito). */
function provElegido(selId, inpId){
  const sel = document.getElementById(selId || "aProvSel"); if(!sel) return "";
  return sel.value === "__nuevo" ? document.getElementById(inpId || "aProvNuevo").value.replace(/\\s+/g, " ").trim().toUpperCase() : sel.value;
}
document.getElementById("aProvSel").addEventListener("change", e => {
  const inp = document.getElementById("aProvNuevo");
  if(e.target.value === "__nuevo"){ inp.value = ""; inp.hidden = false; inp.focus(); }
  else inp.hidden = true;
  // Su flete %, si el artículo no tiene un flete fijo en pesos.
  if(!(aNum(document.getElementById("aFlete").value) > 0)){ ALTA.fletePct = fletePctDe(provElegido()); altaCuenta(); }
  // Si tiene una sola marca y todavía no se eligió ninguna, queda esa.
  const marca = document.getElementById("aMarca");
  const suyas = marcasDeProv(provElegido());
  if(!marca.value.trim() && suyas.length === 1){ marca.value = suyas[0]; marca.dispatchEvent(new Event("input", { bubbles:true })); }
  pintarMarcaSel();
});
document.getElementById("aProvNuevo").addEventListener("change", () => {
  if(!(aNum(document.getElementById("aFlete").value) > 0)){ ALTA.fletePct = fletePctDe(provElegido()); altaCuenta(); }
  pintarMarcaSel();
});
/** Las marcas que tiene un proveedor en los artículos. */
function marcasDeProv(cat){
  const k = plano(String(cat || "").replace(/\\s+/g, " ").trim()); if(!k) return [];
  const m = new Set();
  for(const x of PRODUCTOS) if(plano(String(x.cat || "").replace(/\\s+/g, " ").trim()) === k && x.prov) m.add(String(x.prov).trim());
  return [...m].sort((a, b) => COLL_ES.compare(a, b));
}
function pintarMarcaSel(selId, inpId, pvDe){
  const sel = document.getElementById(selId || "aMarcaSel"), inp = document.getElementById(inpId || "aMarca");
  if(!sel || !inp) return;
  const cuenta = new Map();
  for(const x of PRODUCTOS){ const m = String(x.prov || "").trim(); if(m) cuenta.set(m, (cuenta.get(m) || 0) + 1); }
  const marcas = [...cuenta.keys()].sort((a, b) => COLL_ES.compare(a, b));
  const opc = m => '<option value="' + atrib(m) + '">' + txt(m) + ' (' + cuenta.get(m) + ')</option>';
  const pv = pvDe != null ? pvDe : provElegido(), suyas = marcasDeProv(pv);
  sel.innerHTML = '<option value="">Elegí la marca…</option>' +
    (suyas.length
      ? '<optgroup label="De ' + atrib(pv) + '">' + suyas.map(opc).join("") + '</optgroup>' +
        '<optgroup label="Todas las marcas">' + marcas.filter(m => suyas.indexOf(m) < 0).map(opc).join("") + '</optgroup>'
      : marcas.map(opc).join("")) +
    '<option value="__nueva">+ Crear una marca nueva…</option>';
  const v = inp.value.trim().toUpperCase();
  const igual = v ? marcas.find(m => m.toUpperCase() === v) : null;
  if(!v){ sel.value = ""; inp.hidden = true; }
  else if(igual){ sel.value = igual; inp.value = igual; inp.hidden = true; }
  else { sel.value = "__nueva"; inp.hidden = false; }
}
/* V.0.11.215 (Damián: "que los artículos de una marca, por ejemplo PIAZZA,
   como cargué uno me guarde la forma de guardado del artículo, así ya
   tengo"). La forma sale del último artículo de esa marca creado en Punto
   (el de creadoClave más alto); los combos no cuentan. Se copia solo lo que
   todavía está como viene, y "No usarla" deja todo como estaba. */
const FORMA = { alta:null, adj:null };
function formaDeMarca(marca, salvo){
  const m = String(marca || "").trim().toUpperCase(); if(!m) return null;
  let mejor = null, k = 0;
  for(const p of PRODUCTOS){
    if(String(p.prov || "").trim().toUpperCase() !== m || p.cod === salvo || esComboArt(p)) continue;
    const c = creadoClave(p); if(c > k){ k = c; mejor = p; }
  }
  return mejor;
}
function textoForma(p){
  const partes = [];
  if((p.seis || []).some(d => limD(d) > 0)) partes.push("descuentos " + cadenaTxt(p.seis));
  if(limD(p.dctoCont) > 0) partes.push("contado " + pTxt(limD(p.dctoCont)) + "% " + plazoLargo(p));
  partes.push("Lista 1 " + pTxt(Math.round((+p.l1 || 0) * 100) / 100) + "%", "Lista 2 " + pTxt(Math.round((+p.l2 || 0) * 100) / 100) + "%");
  if(p.may) partes.push("por mayor " + pTxt(+p.mayPct || 0) + "% desde " + Math.max(1, +p.mayDesde || 1));
  if(p.mon === "USD") partes.push("en dólares");
  if(p.rub) partes.push("rubro " + p.rub);
  return partes.join(", ");
}
function fotoFormaAlta(){
  const g = id => document.getElementById(id);
  return { seis: ALTA.seis.slice(), recs: (ALTA.recs || []).slice(), cont: g("aCont").value, dias: g("aContDias").value,
    l1: g("aL1").value, l2: g("aL2").value, iva: g("aIva").value, mon: g("aMoneda").value, dolar: g("aDolar").value,
    may: g("aMay").checked, mayPct: g("aMayPct").value, mayDesde: g("aMayDesde").value, rub: g("aRubro").value,
    cat: provElegido(), fletePct: ALTA.fletePct };
}
function volverFormaAlta(f){
  if(!f) return;
  ALTA.seis = f.seis.slice(); ALTA.recs = f.recs.slice();
  V("aCont", f.cont); V("aContDias", f.dias); V("aL1", f.l1); V("aL2", f.l2); V("aIva", f.iva); V("aMoneda", f.mon); V("aDolar", f.dolar);
  document.getElementById("aMay").checked = f.may; V("aMayPct", f.mayPct); V("aMayDesde", f.mayDesde); V("aRubro", f.rub);
  if(provElegido() !== f.cat) pintarProvSel(f.cat);
  ALTA.fletePct = f.fletePct;
  pintarAltaSeis(); pintarMoneda(); pintarMay(); altaCuenta();
}
function ofrecerFormaAlta(){
  if(ALTA.editando) return;
  const g = id => document.getElementById(id), av = g("aFormaAviso");
  const marca = g("aMarca").value.trim().toUpperCase();
  if(FORMA.alta && FORMA.alta.de === marca) return;
  // Cambió la marca: lo que se había copiado de la otra, vuelve como estaba.
  if(FORMA.alta && FORMA.alta.antes) volverFormaAlta(FORMA.alta.antes);
  FORMA.alta = null;
  if(av){ av.hidden = true; av.innerHTML = ""; }
  const p = formaDeMarca(marca, null); if(!p) return;
  const antes = fotoFormaAlta();
  if(ALTA.seis.every(d => !(limD(d) > 0)) && Array.isArray(p.seis)){
    ALTA.seis = p.seis.slice(0, N_DTOS); while(ALTA.seis.length < N_DTOS) ALTA.seis.push(0);
    ALTA.recs = (p.recs || []).slice();
  }
  if(!(limD(g("aCont").value) > 0) && limD(p.dctoCont) > 0){ V("aCont", limD(p.dctoCont)); V("aContDias", plazoTxt(p)); }
  if(+g("aL1").value === 25 && +g("aL2").value === 25){
    if(+p.l1 > 0) V("aL1", Math.round(+p.l1 * 100) / 100);
    if(+p.l2 > 0) V("aL2", Math.round(+p.l2 * 100) / 100);
  }
  if(g("aIva").value === "21" && p.iva && String(p.iva) !== "21" && [...g("aIva").options].some(o => o.value === String(p.iva))) V("aIva", String(p.iva));
  if(g("aMoneda").value === "ARS" && p.mon === "USD"){ V("aMoneda", "USD"); if(+p.dolar > 0 && !dolarAlta()) V("aDolar", plata2(+p.dolar)); }
  if(!g("aMay").checked && p.may){ g("aMay").checked = true; V("aMayPct", +p.mayPct || 0); V("aMayDesde", Math.max(1, +p.mayDesde || 1)); }
  if(p.rub && !g("aEsCombo").checked && [...g("aRubro").options].some(o => o.value === p.rub)) V("aRubro", p.rub);
  if(!provElegido() && p.cat){
    pintarProvSel(p.cat);
    if(!(aNum(g("aFlete").value) > 0)) ALTA.fletePct = fletePctDe(provElegido());
  }
  FORMA.alta = { de: marca, antes };
  pintarAltaSeis(); pintarMoneda(); pintarMay(); revisarSku(); altaCuenta();
  if(av){
    av.innerHTML = 'Copié la forma del último ' + txt(marca) + ' que cargaste (' + txt(p.cod) + '): ' + txt(textoForma(p)) + '.' +
      '<button type="button" class="b3" data-forma-no="alta">No usarla</button>';
    av.hidden = false;
  }
  try{ guardarBorradorAlta(); }catch(e){}
}
document.getElementById("aMarca").addEventListener("input", ofrecerFormaAlta);
document.getElementById("aFormaAviso").addEventListener("click", e => {
  if(!e.target.closest("[data-forma-no]") || !FORMA.alta) return;
  volverFormaAlta(FORMA.alta.antes);
  FORMA.alta = { de: FORMA.alta.de, antes: null };   // no se vuelve a ofrecer para esta marca
  const av = document.getElementById("aFormaAviso"); av.hidden = true; av.innerHTML = "";
  toast("Listo: quedó como estaba.");
  try{ guardarBorradorAlta(); }catch(x){}
});
