  const inp = document.getElementById("aMarca");
  if(e.target.value === "__nueva"){ inp.value = ""; inp.hidden = false; inp.focus(); }
  else { inp.value = e.target.value; inp.hidden = true; }
  inp.dispatchEvent(new Event("input", { bubbles:true }));
