adjG("adjZona").addEventListener("click",e=>{ if(e.target.closest("button")) return; adjG("adjFile").click(); });
adjG("adjFile").addEventListener("change",e=>{ if(e.target.files[0]) tomarAdjunto(e.target.files[0]); });
for(const ev of ["dragenter","dragover"]) adjG("adjZona").addEventListener(ev, e=>{
  e.preventDefault(); adjG("adjZona").classList.add("encima");
});
for(const ev of ["dragleave","drop"]) adjG("adjZona").addEventListener(ev, e=>{
  e.preventDefault(); adjG("adjZona").classList.remove("encima");
});
adjG("adjZona").addEventListener("drop", e=>{
  const f = e.dataTransfer && e.dataTransfer.files[0];
  if(f) tomarAdjunto(f);
});
adjG("adjTabla").addEventListener("change", e=>{
  const q = e.target.closest("select[data-quees]");
  if(q){
    const campo = q.dataset.quees;
    for(const k of Object.keys(ADJ.mapa)) if(ADJ.mapa[k] === campo) delete ADJ.mapa[k];
    // Esa columna no puede ser dos cosas a la vez: la pisa.
    if(q.value !== "") ADJ.mapa[+q.value] = campo;
    cambioDeColumna();
    return;
  }
  const s = e.target.closest("select[data-col]");
  if(s){
    const i = +s.dataset.col, v = s.value;
    if(v) for(const k of Object.keys(ADJ.mapa)) if(ADJ.mapa[k] === v && +k !== i) delete ADJ.mapa[k];
    if(v) ADJ.mapa[i] = v; else delete ADJ.mapa[i];
    cambioDeColumna();
    return;
  }
  const c = e.target.closest("input[data-fila]");
  if(c){
    if(c.checked) delete ADJ.fuera[+c.dataset.fila]; else ADJ.fuera[+c.dataset.fila] = true;
    pintarAdjTabla();
    return;
  }
  const pc = e.target.closest("input[data-adj-precio]");
  if(pc){ if(pc.checked) ADJ.precio[+pc.dataset.adjPrecio] = true; else delete ADJ.precio[+pc.dataset.adjPrecio]; pintarAdjTabla(); }
});
// Corregir una celda a mano. Lo que se escribe va derecho al renglon:
// lo que se ve en la tabla es exactamente lo que se va a cargar.
adjG("adjTabla").addEventListener("input", e=>{
  const c = e.target.closest("input.adj-cel");
  if(!c) return;
  const n = +c.dataset.f, i = +c.dataset.c, fila = ADJ.filas[n];
  if(!fila) return;
  while(fila.length <= i) fila.push("");   // renglon corto: lo relleno
  fila[i] = c.value;
  refrescarAdjCuenta();
});
// Al salir de la celda: si recien apareció (o se fue) el primer artículo,
// la tabla cambia de forma y ahí sí se repinta entera.
adjG("adjTabla").addEventListener("change", e=>{
  const c = e.target.closest("input.adj-cel");
  if(!c) return;
  const ok = refrescarAdjCuenta();
  if((ok === 0) === (ADJ.vacia === true)) return;
  // Repintar destruye las celdas. Si lo hago ahora, el foco todavia no
  // termino de moverse y la celda a la que iba el usuario desaparece: lo
  // que escriba despues se pierde. Asi que espero a que el foco se pose, y
  // le devuelvo la misma celda ya repintada.
  setTimeout(()=>{
    const a = document.activeElement;
    const ir = a && a.classList && a.classList.contains("adj-cel")
      ? [a.dataset.f, a.dataset.c, a.selectionStart, a.selectionEnd] : null;
    pintarAdjTabla();
    if(!ir) return;
    const nuevo = document.querySelector('.adj-cel[data-f="'+ir[0]+'"][data-c="'+ir[1]+'"]');
    if(!nuevo) return;
    nuevo.focus();
    try { nuevo.setSelectionRange(ir[2], ir[3]); } catch(e2){}
  }, 0);
});
adjG("xSeis").addEventListener("input", e=>{
  const i = e.target.closest("input[data-x]"); if(!i) return;
  ADJ.seis[+i.dataset.x] = limD(i.value);
  i.parentElement.classList.toggle("puesto", limD(i.value) > 0);
  avisoAdjSeis();
});
for(const id of ["xL1","xL2"]) adjG(id).addEventListener("input", avisoAdjSeis);
adjG("xMoneda").addEventListener("change", pintarAdjMoneda);
adjG("xDolar").addEventListener("blur", e=>{
  const v = aNum(e.target.value);
  if(v > 0){ const cambio = v !== DOLAR; if(cambio) guardarDolarFormador(v); DOLAR = v; if(cambio) rearmarGbpEnDolares(); }
  e.target.value = v ? plata2(v) : "";
});
adjG("adjCargar").addEventListener("click", () => { cargarAdjuntos().catch(e => { ADJ.cargando = false; toast("No se pudo cargar: " + (e && e.message || e)); }); });
adjG("adjOtro").addEventListener("click",()=>adjG("adjFile").click());
// V.0.11.272: "Tildar todos los precios" (lo que cambió y ya está).
adjG("adjTabla").addEventListener("click", e => {
  const b = e.target.closest("[data-adj-precios]"); if(!b) return;
  const si = b.dataset.adjPrecios === "1";
  for(const r of filasUtiles()) if((infoYa(r) || {}).d){ if(si) ADJ.precio[r.n] = true; else delete ADJ.precio[r.n]; }
  pintarAdjTabla();
});
// Cancelar: se cierra sin cargar nada (lo leído se descarta).
adjG("adjCancelar").addEventListener("click", ()=>{
  const card = adjG("adjCuerpo").closest(".card");
  cerrarAdj();
  toast("Listo: no se cargó nada.");
  if(card) card.scrollIntoView({block:"nearest", behavior:"smooth"});
});


/* =================================================== PRODUCTOS */
/** Para ordenar texto en castellano, armado una vez. */
const COLL_ES = new Intl.Collator("es");
/** Las marcas con más artículos, para los botones de Artículos. */
let FCHIPS = [];
/** Cuántos artículos hay de cada valor de un campo, en una pasada. */
function contarPor(k){
  const m = new Map();
  for(const p of PRODUCTOS){ const v = String(p[k] || "").trim(); if(v) m.set(v, (m.get(v) || 0) + 1); }
  return m;
}
/** Una lista de filtro con "Todas", cada valor con cuántos tiene, y lo que
    estaba elegido sigue elegido (antes se perdía al importar o repintar). */
function llenarFiltro(id, cuenta, todos){
  const sel = document.getElementById(id); if(!sel) return;
  const antes = sel.value;
  const vals = [...cuenta.keys()].sort((a, b) => COLL_ES.compare(a, b));
  sel.innerHTML = '<option value="">'+todos+'</option>' +
    vals.map(v => '<option value="'+atrib(v)+'">'+txt(v)+' · '+cuenta.get(v)+'</option>').join("");
  sel.value = vals.indexOf(antes) >= 0 ? antes : "";
}
function llenarSelects(){
  const cProv = contarPor("prov"), cRub = contarPor("rub"), cCat = contarPor("cat");
  llenarFiltro("fProv", cProv, "Todas las marcas");
  llenarFiltro("fCat", cCat, "Todos los proveedores");
  llenarFiltro("fRub", cRub, "Todos los rubros");
  // Las marcas con más artículos, a un toque (Piazza, Pringles, FV...).
  // Las 30 con más artículos (sin VARIOS), en orden alfabético para encontrarlas.
  // V.0.11.200: de proveedores, no de marcas (Damián: "las marcas en
  // artículos no las muestres, solo proveedores").
  FCHIPS = [...cCat.entries()].filter(([m]) => m && m !== "VARIOS").sort((a, b) => b[1] - a[1]).slice(0, 30)
    .sort((a, b) => COLL_ES.compare(a[0], b[0]));
  const provs = [...cProv.keys()].sort();
  const porProv = [...cProv.entries()].sort((a,b)=>b[1]-a[1]);
  document.getElementById("sProv").innerHTML = porProv.map(([p,n])=>'<option'+(p==="HEINEKEN"?" selected":"")+'>'+p+'</option>').join("");
}
llenarSelects();

function estadoPill(m){
  if(m < 0) return '<span class="pill p-bad">pierde plata</span>';
  if(m < 10) return '<span class="pill p-bad">muy flojo</span>';
  if(m < S.objetivo) return '<span class="pill p-warn">abajo del objetivo</span>';
  return '<span class="pill p-ok">bien</span>';
}


/* ===================================================== REVISAR (V.0.11.244)
   Damián, 24/11/2026: "agregame en artículos un verificador de renta, es
   decir si tengo algún artículo con algo mal que te llame la atención
   hacémelo saber en el panel de artículos". Se calcula acá, con lo mismo que
   muestra la lista (costo, Lista 1, Lista 2, margen), cada vez que se pinta.
   Tocar un problema deja en la lista de abajo solo esos artículos, con el
   motivo en rojo, para corregirlos ahí mismo. */
const REV_TIPOS = [
  { k:"pierde", t:"Pierde plata", f:"La Lista 1 o el contado quedan por debajo del costo." },
  { k:"bajo", t:"Margen bajo", f:"Deja menos del 10% sobre el costo." },
  { k:"reves", t:"Listas al revés", f:"La Lista 2 es menor que la Lista 1, o el precio por mayor es más caro que la Lista 1." },
  { k:"falta", t:"Le falta algo", f:"Sin costo o sin precio." },
  { k:"raro", t:"Precio raro", f:"Más de 30 veces arriba o abajo de lo común en su marca y rubro." },
  { k:"nocierra", t:"No cierra con GBP", f:"Con los descuentos de GBP el costo da más que la Lista 1, o falta el dólar." },
  { k:"combo", t:"Combos", f:"Combo sin piezas cargadas, o con una pieza que ya no está." },
  { k:"stock", t:"Stock negativo", f:"Se vendió más de lo que había cargado: la lista lo muestra en 0." }
];
/** Menos que esto sobre el costo es "margen bajo". */
const MARGEN_MIN_REV = 10;
/** Cuántas veces lejos de lo común de su marca y rubro es "precio raro". */
const VECES_RARO = 30;
const REV = { sel:"", res:null };

function calcularRevisar(){
  const res = {};
  for(const x of REV_TIPOS) res[x.k] = new Map();
  // Lo común de cada marca y rubro: la mediana de la Lista 2 (con 5 o más).
  const grupo = p => plano((p.prov || "") + "|" + (p.rub || ""));
  const grupos = new Map();
  for(const p of PRODUCTOS){
    if(!(+p.unPago > 0)) continue;
    const g = grupo(p);
    if(!grupos.has(g)) grupos.set(g, []);
    grupos.get(g).push(+p.unPago);
  }
  const mediana = new Map();
  for(const [g, l] of grupos) if(l.length >= 5){ l.sort((a, b) => a - b); mediana.set(g, l[Math.floor(l.length / 2)]); }
  for(const p of PRODUCTOS){
    const pon = (k, m) => res[k].set(p.cod, m);
    const costo = +p.costo || 0, l1 = lista1De(p), l2 = +p.unPago || 0;
    const m = costo > 0 ? margen(p) : NaN;
    if(costo > 0 && l2 > 0 && (l1 < costo || +p.contado < costo))
      pon("pierde", "Costo " + fmt2(costo) + " · Lista 1 " + fmt2(l1) + " · contado " + fmt2(+p.contado || 0));
    else if(isFinite(m) && l2 > 0 && m < MARGEN_MIN_REV)
      pon("bajo", "Deja " + pct(m) + " sobre el costo (" + fmt2(costo) + ")");
    if(isFinite(+p.l2) && +p.l2 < 0)
      pon("reves", "Lista 2 " + fmt2(l2) + " menor que la Lista 1 " + fmt2(l1));
    else if(p.may){
      const ml = listasMayor(p).lista1;
      if(ml > l1 + 0.01) pon("reves", "Por mayor " + fmt2(ml) + " más caro que la Lista 1 " + fmt2(l1));
    }
    const falta = [];
    if(!(costo > 0)) falta.push("sin costo");
    if(!(l2 > 0)) falta.push("sin precio");
    if(falta.length) pon("falta", falta.join(" · "));
    const med = mediana.get(grupo(p));
    if(med && l2 > 0 && (l2 > med * VECES_RARO || l2 < med / VECES_RARO))
      pon("raro", fmt2(l2) + (p.mon === "USD" ? " (en dólares)" : "") + " · lo común en " + (p.prov || "—") + " · " + (p.rub || "—") + " es " + fmt2(med));
    if(p.dtoInfo === "no cierra") pon("nocierra", "Con los descuentos de GBP el costo da más que la Lista 1: revisalo en GBP");
    else if(p.dtoInfo === "sin dólar") pon("nocierra", "Falta el dólar del formador");
    if(esComboArt(p)){
      const pz = p.combo && Array.isArray(p.combo.piezas) ? p.combo.piezas : [];
      if(!pz.length) pon("combo", "Combo sin piezas cargadas");
      else {
        const faltan = pz.filter(x => !prod(x.cod)).map(x => x.cod);
        if(faltan.length) pon("combo", "Pieza que ya no está: " + faltan.join(", "));
      }
    }
    if(p.stockNeg) pon("stock", "Stock negativo en " + [p.stockNeg.BA ? "Buenos Aires (" + p.stockNeg.BA + ")" : "", p.stockNeg.TS ? "Córdoba (" + p.stockNeg.TS + ")" : ""].filter(Boolean).join(" y "));
  }
  return res;
}
function pintarRevisar(){
  const caja = document.getElementById("revChips"); if(!caja) return;
  REV.res = calcularRevisar();
  const todos = new Set();
  for(const k in REV.res) for(const c of REV.res[k].keys()) todos.add(c);
  const n = x => x.toLocaleString("es-AR");
  document.getElementById("revSub").textContent = !PRODUCTOS.length ? "todavía no hay artículos"
    : todos.size ? n(todos.size) + (todos.size === 1 ? " artículo para mirar" : " artículos para mirar") + " de " + n(PRODUCTOS.length)
    : "todo en orden";
  if(REV.sel && !REV.res[REV.sel].size) REV.sel = "";
  caja.innerHTML = REV_TIPOS.map(x => {
    const c = REV.res[x.k].size;
    return '<button type="button" class="rev-chip' + (c ? "" : " cero") + '" data-rev="' + x.k + '" aria-pressed="' + (REV.sel === x.k) + '"' +
      (c ? "" : " disabled") + '><b>' + n(c) + '</b><span>' + txt(x.t) + '</span><small>' + txt(x.f) + '</small></button>';
  }).join("");
  const f = document.getElementById("revFiltro");
  if(REV.sel){
    const x = REV_TIPOS.find(y => y.k === REV.sel);
    f.hidden = false;
    f.innerHTML = 'Mostrando solo <b>' + txt(x.t) + '</b> (' + n(REV.res[REV.sel].size) + '): el motivo va en rojo debajo de cada uno. ' +
      '<button class="link-chico" type="button" data-rev-fuera>Ver todos los artículos</button>';
  } else { f.hidden = true; f.innerHTML = ""; }
}
document.getElementById("revChips").addEventListener("click", e => {
  const b = e.target.closest("[data-rev]"); if(!b || b.disabled) return;
  REV.sel = REV.sel === b.dataset.rev ? "" : b.dataset.rev;
  pintarProd();
  if(REV.sel){
    const card = document.getElementById("tbProd").closest(".card");
    if(card) card.scrollIntoView({ behavior:"smooth", block:"start" });
  }
});
document.getElementById("revFiltro").addEventListener("click", e => {
  if(!e.target.closest("[data-rev-fuera]")) return;
  REV.sel = ""; pintarProd();
});

function pintarProd(){
  pintarRevisar();
  S.objetivo = +document.getElementById("fObj").value || 35;
  const fp = document.getElementById("fProv").value;
  const fr = document.getElementById("fRub").value;
  const fc = document.getElementById("fCat").value;
  const toks = plano(document.getElementById("fBusca").value).split(/\\s+/).filter(Boolean);
  const fco = document.getElementById("fCombos").checked;
  const saca = ORD_PROD[S.ordProd.col] || ORD_PROD.margen;
  const todos = PRODUCTOS
    .filter(p=>(!fp||p.prov===fp) && (!fr||p.rub===fr) && (!fc||String(p.cat||"").trim()===fc) && (!fco||esComboArt(p))
             && (!REV.sel || REV.res[REV.sel].has(p.cod))
             && (!toks.length || (b => toks.every(t=>b.includes(t)))(textoBuscaArt(p))))
    .sort((a,b)=>{
      const x = saca(a), y = saca(b);
      const c = (typeof x === "string") ? COLL_ES.compare(x, y) : x - y;
      return S.ordProd.asc ? c : -c;
    });
  // Con todo GBP son 7.000 filas: pintarlas todas trababa la pantalla en
  // cada tecla. Se ven de a 300; "Mostrar más" suma otras 300. Cambiar el
  // filtro o el orden vuelve a las primeras 300.
  const firma = fp+"|"+fr+"|"+fc+"|"+toks.join(" ")+"|"+fco+"|"+S.ordProd.col+"|"+S.ordProd.asc+"|"+REV.sel;
  pintarFiltrosArt(fp, fr, fc, toks, todos.length);
  pintarSugeridos(toks);
  if(firma !== PROD_VER.firma){ PROD_VER.firma = firma; PROD_VER.max = PROD_DE_A; }
  const lista = todos.slice(0, PROD_VER.max);
  PROD_VER.todos = todos;       // lo que se exporta: todo lo filtrado, no solo las 300 filas
  pintarOrden();
  for(const th of document.querySelectorAll("#v-productos th[data-ord]")){
    th.classList.toggle("ord", th.dataset.ord === S.ordProd.col);
    th.classList.toggle("asc", th.dataset.ord === S.ordProd.col && S.ordProd.asc);
  }

  document.getElementById("tbProd").innerHTML = lista.map(p=>{
    const m = margen(p);
    return '<tr><td class="num" style="font-size:12.5px">'+p.cod.split("+")[0]+
      (p.codProv?'<small style="display:block;color:var(--ink-3);font-weight:500">'+p.codProv+'</small>':'')+'</td>'+
      '<td class="nom">'+p.tit+
        (p.promo?' <span class="pill p-ok">promo</span>':'')+
        (esNuevoArt(p)?' <span class="pill p-warn" title="creado hace menos de 7 días">nuevo</span>':'')+
        (!p.combo && p.vendeSuelto === false ? ' <span class="pill p-warn">solo en combo</span>' : '')+
        (!p.combo && p.vendeCombo === false ? ' <span class="pill p-n">solo suelto</span>' : '')+
        '<small>'+p.rub+'</small>'+
        (REV.sel && REV.res[REV.sel].has(p.cod) ? '<span class="rev-motivo">'+txt(REV.res[REV.sel].get(p.cod))+'</span>' : '')+'</td>'+
      '<td>'+p.prov+(p.cat && p.gbp ? '<small style="display:block;color:var(--ink-3);font-size:11.5px">'+txt(String(p.cat).trim())+'</small>' : '')+'</td>'+
      '<td class="r"><input class="ed" type="text" inputmode="decimal" data-cod="'+p.cod+'" value="'+plata2(netoProdDe(p))+'" aria-label="costo sin IVA">'+
        (p.dtoGbp && (p.seis.some(d=>limD(d)>0) || (p.recs && p.recs.length))
          ? '<small style="display:block;color:var(--ink-3)" title="los descuentos de GBP sobre la lista del proveedor">'+
              cadenaTxt(p.seis)+(p.recs && p.recs.length ? " · rec. "+recsTxt(p.recs) : "")+
              (p.dtoInfo === "no cierra" ? ' <b style="color:var(--warn)" title="Con estos descuentos el costo da más que la Lista 1 de GBP: revisalo en GBP">· no cierra</b>' : "")+'</small>'
          : p.dtoInfo && p.cadenaGbp
          ? '<small style="display:block;color:var(--warn)" title="'+(p.dtoInfo === "no cierra" ? "Con estos descuentos el costo da más que la Lista 1 de GBP: revisalos en GBP. El costo sale de la Lista 1 ÷ 1,25." : "Falta el dólar del formador: el costo sale de la Lista 1 ÷ 1,25.")+'">'+
              cadenaTxt(p.cadenaGbp.cadena)+' · '+(p.dtoInfo === "no cierra" ? "no cierra" : "falta el dólar")+'</small>' : '')+'</td>'+
      '<td class="r"><select class="ed" data-iva="'+p.cod+'" aria-label="IVA del artículo">'+
        ALICUOTAS.map(a=>'<option value="'+a+'"'+(a===ivaDe(p)?" selected":"")+'>'+ivaTxt(a)+'</option>').join("")+
      '</select><small style="display:block;color:var(--ink-3)">+'+fmt2(costoProdDe(p)-netoProdDe(p))+'</small>'+
      (extraDe(p) > 0 ? '<small style="display:block;color:var(--ink-3)" title="flete y otros costos, por unidad">+'+fmt2(extraDe(p))+' flete</small>' : '')+
      '<small style="display:block;color:var(--ink-2);font-weight:600">= '+fmt2(p.costo)+'</small></td>'+
      '<td class="r">'+(esComboArt(p) ? '<span style="color:var(--ink-3)" title="El flete va en cada pieza del combo">—</span>'
        : '<input class="ed" type="text" inputmode="decimal" data-flete-art="'+p.cod+'" value="'+(+p.fleteFijo > 0 ? plata2(p.fleteFijo) : "")+'"'+
          ' placeholder="'+(+p.fleteFijo > 0 ? "0" : +p.fletePct > 0 ? pTxt(+p.fletePct)+"% prov." : "0")+'"'+
          (puede("productos") ? '' : ' disabled')+' aria-label="flete por unidad, en pesos con IVA"'+
          ' title="Flete por unidad, en pesos con IVA. Vacío: va el flete % del proveedor, si tiene.">')+'</td>'+
      '<td class="r" style="white-space:nowrap;color:var(--ink-2)">'+fmt2(lista1De(p))+'</td>'+
      '<td class="r" style="font-weight:700;white-space:nowrap">'+fmt2(p.unPago)+'</td>'+
      '<td class="r" style="font-weight:600;color:'+(m<0?"var(--bad)":(m<S.objetivo?"var(--warn)":"var(--ok)"))+'">'+pct(m)+'</td>'+
      '<td>'+estadoPill(m)+'</td><td class="r">'+p.stock+
        ((+p["min"+depAct()] || 0) > 0 ? '<small style="display:block;font-weight:600;color:'+(p.stock < +p["min"+depAct()] ? 'var(--bad)' : 'var(--ink-3)')+'" title="stock mínimo en esta sucursal">mín '+(+p["min"+depAct()])+'</small>' : '')+'</td>'+
      '<td class="r"><button class="lapiz" data-ed="'+p.cod+'" title="Editar este artículo" aria-label="editar '+p.cod+'">'+
        '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" aria-hidden="true">'+
        '<path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 013 3L7 19l-4 1 1-4z"/></svg></button></td></tr>';
  }).join("") || '<tr><td colspan="12" class="vacio">Nada con esos filtros.</td></tr>';

  const bajo = PRODUCTOS.filter(p=>margen(p)<0);
  const flojos = PRODUCTOS.filter(p=>{const m=margen(p); return m>=0 && m<S.objetivo;});
  document.getElementById("prodPie").innerHTML =
    (todos.length > lista.length
      ? "Se ven los primeros <b>"+lista.length+"</b> de <b>"+todos.length+"</b> que coinciden ("+PRODUCTOS.length+" artículos en total). "+
        '<button class="b2" id="btnProdMas" style="padding:3px 11px;font-size:12px">Mostrar '+Math.min(PROD_DE_A, todos.length - lista.length)+' más</button> '+
        "Para encontrar uno, escribilo en Buscar. "
      : "Se ven <b>"+lista.length+"</b> de "+PRODUCTOS.length+" artículos. ")+
    "En todo el catálogo: <b>"+bajo.length+
    "</b> se venden por debajo del costo y <b>"+flojos.length+"</b> no llegan al "+S.objetivo+
    "%. El costo se puede corregir acá mismo y se guarda en el sistema.";
}
for(const id of ["fProv","fRub"]) document.getElementById(id).addEventListener("input",pintarProd);
// El objetivo ahora vive en Rentabilidad, que es la pantalla que lo usa.
document.getElementById("fObj").addEventListener("input",()=>{ if(vistaActual() === "productos") pintarProd(); pintarRenta(); });
/** De dónde sale el número (o el texto) de cada columna. */
/** La Lista 1 de un artículo: la Lista 2 sin su porcentaje (con el flete, como la 2). */
const lista1De = p => cent((+p.unPago || 0) / (1 + (isFinite(+p.l2) ? +p.l2 : 25) / 100));
const ORD_PROD = {
  cod:  p=>p.cod,      tit:  p=>p.tit,     prov: p=>p.prov,
  neto: p=>netoProdDe(p),  costo:p=>p.costo,   contado:p=>p.contado,
  unPago:p=>p.unPago,  lista1:p=>lista1De(p), margen:p=>margen(p), stock:p=>p.stock,
  flete:p=>+p.fleteFijo || 0,
  creado:p=>creadoClave(p)
};
/** V.0.11.213 (Damián: "cuando busco me tendría que aparecer últimos
    creados"). La fecha que puso el servidor; los creados en Punto antes de
    que hubiera fecha, por código (el más alto, el más nuevo); los de GBP,
    al final. */
function creadoClave(p){
  const t = Date.parse(p.creado || ""); if(isFinite(t)) return t;
  // GBP_CRUDO se define más abajo: si la tabla se pinta antes, no falla.
  let c = null; try{ c = GBP_CRUDO[p.cod]; }catch(e){}
  if(p.cargado || (c && !c.gbpId)) return 1000 + (parseInt(String(p.cod).split("+")[0], 10) || 0);
  return 0;
}
/** Creado hace menos de 7 días (o todavía sin guardar). */
const esNuevoArt = p => !!p.cargado || (Date.now() - (Date.parse(p.creado || "") || 0)) < 7 * 864e5;
/** V.0.11.218 (Damián: "que se pueda elegir por más viejos, últimos
    creados, mayor precio, menor precio, etc."). El precio es la Lista 2. */
// var (no const): pintarProd puede correr antes de esta línea al abrir.
var ORDENES = [
  ["creado", false, "Últimos creados"], ["creado", true, "Más viejos"],
  ["unPago", false, "Mayor precio"],    ["unPago", true, "Menor precio"],
  ["margen", true, "Menor margen"],     ["margen", false, "Mayor margen"],
  ["stock", false, "Más stock"],        ["stock", true, "Menos stock"],
  ["tit", true, "Nombre, de la A a la Z"], ["prov", true, "Marca, de la A a la Z"]
];
function pintarOrden(){
  const sel = document.getElementById("fOrden"); if(!sel || !ORDENES) return;
  const v = S.ordProd.col + "|" + (S.ordProd.asc ? "a" : "d");
  const hay = ORDENES.some(([c, a]) => c + "|" + (a ? "a" : "d") === v);
  sel.innerHTML = ORDENES.map(([c, a, t]) => '<option value="' + c + '|' + (a ? "a" : "d") + '">' + t + '</option>').join("") +
    (hay ? "" : '<option value="' + v + '">Por la columna que tocaste</option>');
  sel.value = v;
  sel.classList.toggle("puesto", !(S.ordProd.col === "creado" && !S.ordProd.asc));
}
document.getElementById("fOrden").addEventListener("change", e => {
  const [col, dir] = String(e.target.value || "").split("|");
  if(!ORD_PROD[col]) return;
  S.ordProd = { col, asc: dir === "a" };
  pintarProd();
});
document.querySelector("#v-productos thead").addEventListener("click",e=>{
  const th = e.target.closest("th[data-ord]"); if(!th) return;
  const col = th.dataset.ord;
  // La misma otra vez da vuelta el orden; una nueva arranca de menor a mayor.
  S.ordProd = (S.ordProd.col === col) ? {col, asc: !S.ordProd.asc} : {col, asc: true};
  pintarProd();
});
// Con 7.000 artículos, repintar en cada tecla se sentía: espera a que termines.
let fBuscaEspera = 0;
document.getElementById("fBusca").addEventListener("input", () => {
  clearTimeout(fBuscaEspera);
  fBuscaEspera = setTimeout(pintarProd, 180);
});
/** Lo que mira el buscador de Artículos: código, código del fabricante,
    nombre, rubro, marca y proveedor. Se arma una vez por artículo. */
function textoBuscaArt(p){
  const base = p.propio || "";
  const llave = base + "|" + (p.subrubro || "");
  if(p._fa === undefined || p._faDe !== llave){ p._faDe = llave; p._fa = plano(base + " " + (p.cat || "") + " " + (p.subrubro || "")); }
  return p._fa;
}
/** Las marcas a un toque, cuántos coinciden y lo que está puesto resaltado. */
function pintarFiltrosArt(fp, fr, fc, toks, n){
  for(const [id, v] of [["fProv", fp], ["fRub", fr], ["fCat", fc]]){ const e = document.getElementById(id); if(e) e.classList.toggle("puesto", !!v); }
  const hay = !!(fp || fr || fc || toks.length);
  document.getElementById("fLimpiar").hidden = !hay;
  document.getElementById("fCuenta").textContent = hay
    ? n.toLocaleString("es-AR") + " de " + PRODUCTOS.length.toLocaleString("es-AR") + " artículos con estos filtros"
    : PRODUCTOS.length.toLocaleString("es-AR") + " artículos";
  const chips = FCHIPS.slice();
  if(fc && !chips.some(([m]) => m === fc)) chips.push([fc, PRODUCTOS.filter(p => String(p.cat || "").trim() === fc).length]);
  document.getElementById("fChips").innerHTML = '<span class="et">Proveedores</span>' +
    '<button type="button" data-cat="" aria-pressed="'+(!fc)+'">Todos</button>' +
    chips.map(([m, k]) => '<button type="button" data-cat="'+atrib(m)+'" aria-pressed="'+(m === fc)+'">'+txt(m)+'<small>'+k+'</small></button>').join("") +
    '<span class="por" style="margin-left:4px">los demás, en Proveedor</span>';
}
document.getElementById("fChips").addEventListener("click", e => {
  const b = e.target.closest("button[data-cat]"); if(!b) return;
  const sel = document.getElementById("fCat");
  // Tocar el que ya está puesto lo saca.
  sel.value = (b.dataset.cat && sel.value !== b.dataset.cat) ? b.dataset.cat : "";
  pintarProd();
});
document.getElementById("fCat").addEventListener("input", pintarProd);
document.getElementById("fCombos").addEventListener("change", pintarProd);

/* Al escribir el nombre de un proveedor o de una marca en la búsqueda, se
   ofrece elegirlo como filtro, y queda elegido (Damián: "cuando busco
   proveedor debería dejarme seleccionar y quedar seleccionado"). */
function pintarSugeridos(toks){
  const caja = document.getElementById("fSugeridos"); if(!caja) return;
  const q = toks.join(" ");
  if(q.length < 2){ caja.hidden = true; caja.innerHTML = ""; return; }
  const cuenta = (k) => { const m = new Map(); for(const p of PRODUCTOS){ const n = String(p[k] || "").trim(); if(n) m.set(n, (m.get(n) || 0) + 1); } return m; };
  const prov = [...cuenta("cat")].filter(([n]) => plano(n).indexOf(q) >= 0 && n !== document.getElementById("fCat").value).slice(0, 4);
  const marca = [...cuenta("prov")].filter(([n]) => plano(n).indexOf(q) >= 0 && n !== document.getElementById("fProv").value).slice(0, 4);
  caja.innerHTML = prov.map(([n, c]) => '<button type="button" data-sug-cat="'+atrib(n)+'">Proveedor: '+txt(n)+' ('+c+')</button>').join("") +
    marca.map(([n, c]) => '<button type="button" data-sug-prov="'+atrib(n)+'">Marca: '+txt(n)+' ('+c+')</button>').join("");
  caja.hidden = !(prov.length || marca.length);
}
document.getElementById("fSugeridos").addEventListener("click", e => {
  const b = e.target.closest("button"); if(!b) return;
  if(b.dataset.sugCat != null) document.getElementById("fCat").value = b.dataset.sugCat;
  if(b.dataset.sugProv != null) document.getElementById("fProv").value = b.dataset.sugProv;
  document.getElementById("fBusca").value = "";
  pintarProd();
});

document.getElementById("fLimpiar").addEventListener("click", () => {
  for(const id of ["fProv", "fRub", "fCat"]) document.getElementById(id).value = "";
  document.getElementById("fBusca").value = "";
  document.getElementById("fCombos").checked = false;
  pintarProd();
  document.getElementById("fBusca").focus();
});
/** Cuántas filas de Artículos se ven (de a 300). */
const PROD_DE_A = 300;
const PROD_VER = { firma:"", max:PROD_DE_A };
document.getElementById("prodPie").addEventListener("click",e=>{
  if(!e.target.closest("#btnProdMas")) return;
  PROD_VER.max += PROD_DE_A;
  pintarProd();
});
document.getElementById("prodPie").addEventListener("click",e=>{
  if(!e.target.closest("#btnOlvidar")) return;
  if(!confirm("¿Borro los artículos que cargaste y los cambios que hiciste, y vuelvo al catálogo original?")) return;
  try{ localStorage.removeItem(GUARDA); }catch(e2){}
  location.reload();
});
document.getElementById("tbProd").addEventListener("click",e=>{
  const b = e.target.closest("button[data-ed]"); if(!b) return;
  const p = PRODUCTOS.find(x=>x.cod === b.dataset.ed);
  if(p) abrirAlta(p);
});
document.getElementById("tbProd").addEventListener("change",e=>{
  const sv = e.target.closest("select[data-iva]");
  if(sv){
    const p = prod(sv.dataset.iva); if(!p) return;
    const neto = netoProdDe(p);             // el neto del producto no cambia: cambia el IVA
    p.iva = +sv.value;
    ponerCostoProducto(p, neto * facIva(p.iva));
    p.tocado = true; guardarCatalogo();
    pintarProd(); pintarTicket();
    toast(p.cod.split("+")[0]+" pasa a IVA "+ivaTxt(p.iva)+". Cuesta "+fmt(p.costo)+" con IVA.");
    return;
  }
  const fi = e.target.closest("input[data-flete-art]");
  if(fi){ ponerFleteArt(fi); return; }
  const i = e.target.closest("input[data-cod]"); if(!i) return;
  const p = prod(i.dataset.cod); if(!p) return;
  const neto = Math.max(0, aNum(i.value));
  ponerCostoProducto(p, cent(neto * facIva(ivaDe(p))));
  p.tocado = true; guardarCatalogo();
  pintarProd();
  toast("Costo de "+p.cod.split("+")[0]+": "+fmt2(neto)+" sin IVA, "+fmt2(costoProdDe(p))+" con IVA"+(extraDe(p) > 0 ? ", "+fmt2(p.costo)+" con el flete" : "")+". El margen ya está recalculado.");
});

/** V.0.11.194 (Damián: el flete "por monto, no por porcentaje", en cada
    artículo: el caso de PRECONS). Pesos por unidad, con IVA, como en la
    ficha del artículo: se suma al costo y las listas suben en la misma
    proporción (el margen queda). Vacío o 0: vuelve el % del proveedor. */
async function ponerFleteArt(fi){
  const p = prod(fi.dataset.fleteArt); if(!p) return;
  if(!puede("productos")){ toast("Tu usuario no puede cambiar artículos."); pintarProd(); return; }
  const escrito = String(fi.value || "").trim();
  const fl = escrito ? cent(aNum(escrito)) : 0;
  if(!isFinite(fl) || fl < 0 || fl > 100000000){ toast("El flete es un monto en pesos por unidad, por ejemplo 1.500,00."); pintarProd(); return; }
  if(Math.abs((+p.fleteFijo || 0) - fl) < 0.005){ pintarProd(); return; }
  const antes = +p.unPago || 0;
  if(p.gbp && GBP_CRUDO[p.cod] && !p.tocado){
    // Como la ficha: se vuelve a armar el artículo con el flete nuevo.
    GBP_CRUDO[p.cod] = Object.assign({}, GBP_CRUDO[p.cod], { flete: fl });
    const np = productoDeGbp(GBP_CRUDO[p.cod]);
    for(const k of CAMPOS_GBP_PUNTO) p[k] = np[k];
    guardarFleteServidor(p.cod, { flete: fl });
  } else {
    p.fleteFijo = fl; rearmarCostoGbp(p);
    // Primero el flete (si se sacó, el artículo entero no lo borra) y
    // después el artículo con lo que se había cambiado acá.
    if(p.gbp) await guardarFleteServidor(p.cod, { flete: fl });
    p.tocado = true; guardarCatalogo();
  }
  pintarProd(); buscar(); pintarTicket();
  toast(p.cod.split("+")[0] + (fl > 0 ? ": flete " + fmt2(fl) + " por unidad" :
      ": sin flete fijo" + (+p.fletePct > 0 ? " (va el " + pTxt(+p.fletePct) + "% del proveedor)" : "")) +
    ". La Lista 2 " + (Math.abs(antes - (+p.unPago || 0)) < 0.5 ? "quedó igual." : "pasa a " + fmt(p.unPago) + "."));
}

/* ===================================================== LISTAS */
/* El formador de precios. Tres preguntas: a quiénes, qué les cambio, y
   qué pasa si lo hago. Nada se toca hasta el último botón. */
const PF = { quien:"prov", modo:"sube", uno:null, seis:CADENA_BASE.slice() };

/* --------------------------------------------------- paso 1: a quiénes */
document.getElementById("sQuien").addEventListener("click",e=>{
  const b = e.target.closest("button[data-q]"); if(!b) return;
  for(const x of document.querySelectorAll("#sQuien button")) x.setAttribute("aria-pressed", String(x===b));
  PF.quien = b.dataset.q;
  document.getElementById("qProv").hidden = PF.quien !== "prov";
  document.getElementById("qSku").hidden  = PF.quien !== "sku";
  document.getElementById("qUno").hidden  = PF.quien !== "uno";
  cargarSeis(); pintarCadena();
});

/** Los artículos a los que se les va a cambiar algo. */
function alcance(){
  if(PF.quien === "prov")
    return PRODUCTOS.filter(p => p.prov === document.getElementById("sProv").value);
  if(PF.quien === "uno")
    return PF.uno ? [PF.uno] : [];
  const cods = document.getElementById("sSku").value
    .split(/[\\s,;]+/).map(x=>x.trim()).filter(Boolean);
  const out = [], faltan = [];
  for(const c of cods){
    const p = PRODUCTOS.find(x => x.cod === c || x.cod.split("+")[0] === c);
    if(p){ if(!out.includes(p)) out.push(p); } else faltan.push(c);
  }
  document.getElementById("skuAviso").innerHTML = !cods.length
    ? "Pegá los códigos y te digo cuáles reconozco."
    : '<b style="color:'+(faltan.length?"var(--warn)":"var(--ok)")+'">'+out.length+' de '+cods.length+' reconocidos.</b>'+
      (faltan.length ? " No encontré: "+faltan.slice(0,8).join(", ")+(faltan.length>8?"…":"") : "");
  return out;
}
document.getElementById("sSku").addEventListener("input", ()=>{ alcance(); pintarCadena(); });
document.getElementById("sProv").addEventListener("change", ()=>{ cargarSeis(); pintarCadena(); });

/* buscar un artículo solo */
document.getElementById("sUno").addEventListener("input",e=>{
  const q = plano(e.target.value.trim());
  const caja = document.getElementById("sUnoRes");
  if(!q){ caja.innerHTML = ""; return; }
  const hits = encontrar(q.split(/\\s+/).filter(Boolean)).hits.slice(0,6);
  caja.innerHTML = hits.map(({p})=>
    '<button class="item" data-u="'+p.cod+'">'+
      '<span class="cod">'+p.cod.split("+")[0]+'</span>'+
      '<span><span class="tit"><span>'+p.tit+'</span></span>'+
      '<span class="meta"><span>'+p.prov+'</span><span>lista '+fmt(p.lista)+'</span></span></span>'+
      '<span class="pre"><b>'+fmt(p.contado)+'</b></span></button>').join("")
    || '<div class="vacio" style="padding:14px">Nada con eso.</div>';
});
document.getElementById("sUnoRes").addEventListener("click",e=>{
  const b = e.target.closest("button[data-u]"); if(!b) return;
  PF.uno = prod(b.dataset.u);
  document.getElementById("sUnoRes").innerHTML = "";
  document.getElementById("sUno").value = PF.uno.tit;
  document.getElementById("unoElegido").innerHTML =
    '<b>'+PF.uno.cod.split("+")[0]+' · '+PF.uno.tit+'</b>';
  cargarSeis(); pintarCadena();
});

/* ---------------------------------------------- paso 2: qué les cambio */
document.getElementById("sModo").addEventListener("click",e=>{
  const b = e.target.closest("button[data-m]"); if(!b) return;
  for(const x of document.querySelectorAll("#sModo button")) x.setAttribute("aria-pressed", String(x===b));
  PF.modo = b.dataset.m;
  document.getElementById("cSube").hidden = PF.modo !== "sube";
  document.getElementById("cDesc").hidden = PF.modo !== "desc";
  document.getElementById("cMk").hidden   = PF.modo !== "mk";
  if(PF.modo === "desc") cargarSeis();
  if(PF.modo === "mk"){
    const a = alcance();
    if(a.length) document.getElementById("sMk").value = Math.round(markupDe(a[0])*10)/10;
    avisoMarkup();
  }
});

/** Trae a los seis casilleros la cadena que rige para lo que está elegido. */
function cargarSeis(){
  const a = alcance();
  const prov = PF.quien === "prov" ? document.getElementById("sProv").value
             : (a.length ? a[0].prov : null);
  const delProv = prov && (S.cadenas[prov] || DESC_PROV[prov]);
  PF.seis = (delProv ? cadenaDe(prov) : (a.length ? cadenaArt(a[0]) : CADENA_BASE)).slice(0,N_DTOS);
  while(PF.seis.length < N_DTOS) PF.seis.push(0);
  pintarSeis();
}
const ET_D = ["Descuento 1","Descuento 2","Descuento 3","Descuento 4","Descuento 5","Descuento 6","Descuento 7","Descuento 8"];
function pintarSeis(){
  document.getElementById("seisD").innerHTML = PF.seis.map((d,i)=>
    '<div class="d'+(limD(d)>0?" puesto":"")+'">'+
      '<span class="et">'+ET_D[i]+'</span>'+
      '<input type="number" min="0" max="99.99" step="0.01" value="'+limD(d)+'" data-i="'+i+'" aria-label="descuento '+(i+1)+'">'+
      '<span class="pc">%</span></div>').join("");
  pintarComparar();
}
document.getElementById("seisD").addEventListener("input",e=>{
  const i = e.target.closest("input[data-i]"); if(!i) return;
  PF.seis[+i.dataset.i] = limD(i.value);
  i.parentElement.classList.toggle("puesto", limD(i.value) > 0);
  pintarComparar();
});
/** Qué dan esos seis descuentos, en un número y en pesos. */
function pintarComparar(){
  const ds = PF.seis;
  const a = alcance();
  const ej = a.length ? a[0] : null;
  const ccP = ej ? costoDe(ej.lista * factorRecs(ej.recs), ds, null, ivaDe(ej), ej.dctoCont) : null;
  // Con el flete y el otro costo del artículo, como el simulador.
  const cc = ccP == null ? null
    : cent(ccP + (+ej.fleteFijo > 0 ? +ej.fleteFijo : ccP * (+ej.fletePct || 0) / 100) + (+ej.otroCosto || 0));

  document.getElementById("compararDesc").innerHTML =
    '<div class="c elegido">'+
      '<div class="k">'+cadenaTxt(ds)+'</div>'+
      '<div class="v">'+pTxt(Math.round(descEquiv(ds)*10)/10)+'% de descuento</div>'+
      '<div class="n">uno sobre otro, como los hace el proveedor'+
        (cc!=null ? ' · costo '+(cc !== ccP ? 'puesto ' : '')+fmt2(cc) : '')+'</div></div>';
}

function avisoMarkup(){
  const a = alcance();
  if(!a.length){ document.getElementById("mkAviso").textContent =
    "Del costo al precio de contado."; return; }
  const mk = +document.getElementById("sMk").value || 0;
  const p = a[0];
  document.getElementById("mkAviso").innerHTML =
    'Con '+mk+'% sobre el costo, <b>'+p.tit.slice(0,38)+'</b> pasaría de '+fmt(p.contado)+
    ' a <b>'+fmt(precioDe(p.costo, mk))+'</b> de contado, y a '+
    fmt(redondear(precioDe(p.costo, mk)*RECARGO_1PAGO))+' en 1 pago. '+
    'El margen sobre el costo es justamente ese '+mk+'%.';
}
document.getElementById("sMk").addEventListener("input", avisoMarkup);

/* ------------------------------------ la cadena, escrita como una cuenta */
function pintarCadena(){
  const a = alcance();
  const p = a.length ? a[0] : null;
  const de = document.getElementById("cadenaDe");
  if(!p){
    de.textContent = "elegí algo arriba";
    document.getElementById("cadenaCuerpo").innerHTML =
      '<div class="vacio" style="padding:18px">Elegí un proveedor, pegá unos códigos o buscá un artículo y te muestro de dónde sale cada peso de su precio.</div>';
    return;
  }
  const ds = cadenaArt(p);
  const fac = factorDe(ds);
  const neto = Math.round(p.lista * fac);
  const costoP = Math.round(neto * facIva(ivaDe(p)));
  // V.0.99.82: el flete (fijo, o el % del proveedor) y el otro costo van
  // encima del producto: el markup se aplica sobre todo eso.
  const fl = +p.fleteFijo > 0 ? +p.fleteFijo : Math.round(costoP * (+p.fletePct || 0) / 100);
  const otroC = +p.otroCosto > 0 ? +p.otroCosto : 0;
  const costo = costoP + fl + otroC;
  const mk = markupDe(p);
  const r = (k,v,cls) => '<div class="r2'+(cls?" "+cls:"")+'"><span class="k">'+k+'</span><span class="v">'+v+'</span></div>';

  de.innerHTML = a.length>1 ? "ejemplo: "+p.cod.split("+")[0] : p.cod.split("+")[0];
  document.getElementById("cadenaCuerpo").innerHTML =
    r("<b>"+p.tit+"</b>", p.prov, "sub")+
    r("Lista del proveedor, sin IVA", fmt2(p.lista))+
    r("Descuentos: "+cadenaTxt(ds)+", uno sobre otro", "−"+fmt(p.lista-neto))+
    r("Queda neto", fmt(neto), "sub")+
    r("IVA "+ivaTxt(ivaDe(p)), "+"+fmt(costoP-neto))+
    (fl > 0 || otroC > 0
      ? r("El producto, con IVA", fmt(costoP), "sub")+
        (fl > 0 ? r(+p.fleteFijo > 0 ? "Más el flete, fijo" : "Más el flete, "+pTxt(+p.fletePct)+"% del proveedor", "+"+fmt(fl)) : "")+
        (otroC > 0 ? r("Más "+txt(p.otroNombre || "otro costo"), "+"+fmt(otroC)) : "")+
        r("<b>Lo que te cuesta puesto acá</b>", fmt(costo), "total")
      : r("<b>Lo que te cuesta, con IVA</b>", fmt(costo), "total"))+
    r("Markup "+pTxt(mk)+"% sobre el costo", "+"+fmt(precioDe(costo,mk)-costo))+
    r("<b>Precio de contado</b>", fmt(precioDe(costo,mk)), "total")+
    r("Recargo 13,64% si paga en 1 pago", "+"+fmt(redondear(precioDe(costo,mk)*RECARGO_1PAGO)-precioDe(costo,mk)), "sub")+
    r("Precio de 1 pago", fmt(redondear(precioDe(costo,mk)*RECARGO_1PAGO)), "sub")+
    (Math.abs(costo - p.costo) > 2
      ? '<p class="nota" style="padding:10px 0 0">El costo cargado hoy es '+fmt(p.costo)+
        '. La cuenta de arriba da '+fmt(costo)+', porque el modo de descuento elegido no es el mismo con el que se cargó. Aplicá el cambio para emparejarlos.</p>'
      : '');
}

/* ------------------------------------------- paso 3: qué pasa si lo hago */
document.getElementById("btnSim").addEventListener("click",()=>{
  const a = alcance();
  if(!a.length){ toast("Primero elegí a quiénes les cambiás el precio."); return; }
  const obj = S.objetivo = +document.getElementById("fObj").value || 35;

  // Sin lista del proveedor no hay de dónde sacar el costo: esos quedan afuera.
  const sinLista = a.filter(p => !(p.lista > 0)).length;
  const filas = a.filter(p => p.lista > 0).map(p=>{
    let lista = p.lista, ds = cadenaArt(p).slice(), mk = markupDe(p);
    if(PF.modo === "sube") lista = Math.round(lista * (1 + (+document.getElementById("sPct").value||0)/100));
    if(PF.modo === "desc") ds = PF.seis.slice();
    if(PF.modo === "mk")   mk = +document.getElementById("sMk").value || 0;
    // Con los recargos de GBP del artículo (sin ellos, ACQUA SYSTEM con +300% salía a la cuarta parte).
    const nuevoProd = costoDe(lista * factorRecs(p.recs), ds, null, ivaDe(p), p.dctoCont);
    const nuevo = cent(nuevoProd + (p.fleteFijo > 0 ? p.fleteFijo : nuevoProd * (p.fletePct || 0) / 100) + (p.otroCosto || 0));
    const sugerido = precioDe(nuevo, mk);
    return {
      p, lista, ds, mk, nuevo, sugerido,
      mQueda: (p.contado - nuevo)/nuevo*100,
      sube: (sugerido - p.contado)/p.contado*100
    };
  }).sort((x,y)=>x.mQueda - y.mQueda);

  S.sim = {filas, quien: textoAlcance(a)};
  if(sinLista) toast(sinLista+(sinLista === 1 ? " artículo no tiene" : " artículos no tienen")+" lista del proveedor y "+(sinLista === 1 ? "quedó" : "quedaron")+" afuera.");

  const bajoCosto = filas.filter(f=>f.mQueda<0).length;
  const flojos = filas.filter(f=>f.mQueda>=0 && f.mQueda<obj).length;
  const enStock = filas.filter(f=>f.mQueda<0).reduce((acc,f)=>acc+(f.p.contado-f.nuevo)*f.p.stock,0);

  document.getElementById("simResumen").hidden = false;
  document.getElementById("simResumen").innerHTML =
    '<div><b>'+filas.length+'</b>'+(filas.length===1?"artículo":"artículos")+' de '+S.sim.quien+'</div>'+
    '<div style="color:var(--bad)"><b>'+bajoCosto+'</b>'+(bajoCosto===1?"quedaría":"quedarían")+' abajo del costo</div>'+
    '<div style="color:var(--warn)"><b>'+flojos+'</b>no '+(flojos===1?"llegaría":"llegarían")+' al '+obj+'%</div>'+
    '<div><b>'+fmt(Math.abs(enStock))+'</b>'+(enStock<0?"se pierden":"quedan")+' con el stock que hay</div>';

  document.getElementById("tbSim").innerHTML = filas.map(f=>
    '<tr><td class="num" style="font-size:12.5px">'+f.p.cod.split("+")[0]+'</td>'+
    '<td class="nom">'+f.p.tit+'</td>'+
    '<td class="r">'+fmt(f.lista)+(f.lista!==f.p.lista?'<small style="display:block;color:var(--ink-3)">era '+fmt(f.p.lista)+'</small>':'')+'</td>'+
    '<td class="r" style="color:var(--ink-3)">'+fmt(f.p.costo)+'</td>'+
    '<td class="r" style="font-weight:700">'+fmt(f.nuevo)+'</td>'+
    '<td class="r">'+fmt(f.p.contado)+'</td>'+
    '<td class="r" style="color:var(--accent);font-weight:700">'+fmt(f.sugerido)+'</td>'+
    '<td class="r" style="font-weight:600;color:'+(f.mQueda<0?"var(--bad)":(f.mQueda<obj?"var(--warn)":"var(--ok)"))+'">'+pct(f.mQueda)+'</td>'+
    '<td class="r">'+pct(f.sube)+'</td></tr>').join("");

  document.getElementById("simAcc").hidden = false;
  pintarCadena();
  toast(filas.length+" "+(filas.length===1?"artículo revisado":"artículos revisados"));
});

function textoAlcance(a){
  if(PF.quien === "prov") return document.getElementById("sProv").value;
  if(PF.quien === "uno")  return "un artículo";
  return "la lista de códigos";
}

/* ------------------------------------------------------- aplicar ------- */
function aplicar(todo){
  if(!S.sim || !S.sim.filas.length) return;
  for(const f of S.sim.filas){
    if(!(f.nuevo > 0) || !(f.sugerido > 0)) continue;   // nunca un costo o un precio en 0
    f.p.lista  = f.lista;
    f.p.markup = f.mk;
    f.p.costo  = f.nuevo;
    if(todo){
      f.p.contado = f.sugerido;
      f.p.unPago  = redondear(f.sugerido * RECARGO_1PAGO);
    }
    f.p.tocado = true;
  }
  guardarCatalogo();
  // Si se tocó la cadena de un proveedor entero, queda guardada para él.
  if(PF.modo === "desc" && PF.quien === "prov")
    S.cadenas[document.getElementById("sProv").value] = PF.seis.slice();
  toast(todo
    ? "Costos y precios de "+S.sim.quien+" actualizados. El mostrador y la web ya venden con los nuevos."
    : "Costos nuevos de "+S.sim.quien+" aplicados. Los precios quedaron como estaban: mirá el margen en Gerencia.");
  document.getElementById("btnSim").click();
  pintarProd(); pintarTicket(); buscar();
}
document.getElementById("btnAplicarCosto").addEventListener("click",()=>aplicar(false));
document.getElementById("btnAplicarTodo").addEventListener("click",()=>aplicar(true));

/* ======================================================= CAJA */
function barra(et, v, max, f2){
  return '<div class="barra"><span class="et">'+et+'</span>'+
    '<span class="pista"><span class="fill'+(f2?" f2":"")+'" style="width:'+(max>0?Math.max(2,v/max*100):0).toFixed(1)+'%"></span></span>'+
    '<span class="vl">'+fmt(v)+'</span></div>';
}
function pintarCajaSucs(){
  document.getElementById("cajaSucs").innerHTML =
    [["","Todas"]].concat(SUCURSALES.map(x=>[x.id,x.n]))
      .map(([id,n])=>'<button data-cs="'+id+'" aria-pressed="'+(id===S.cajaSuc)+'">'+n+'</button>').join("");
}
document.getElementById("cajaSucs").addEventListener("click",e=>{
  const b = e.target.closest("button[data-cs]"); if(!b) return;
  S.cajaSuc = b.dataset.cs;
  pintarCaja();
  pintarPlataCaja(false);
});


/* ================================================ CAJA DE EFECTIVO (V.0.11.255)
   Damián, 24/11/2026: "caja en efectivo necesito todos los días cerrar la
   misma y abrir y saber cuánto hay, es decir cuando abro a la mañana con X
   plata que se contó el día anterior al cierre del día" y "necesitamos un
   panel donde se ingrese los billetes que hay en la caja de efectivo".
   El servidor (/sistema/cierres, src/lib/punto-cierres.ts) dice con cuánto
   abrió y cuánto tendría que haber, y guarda cada cierre con sus billetes. */
const CIE_URL = "/sistema/cierres";
const BILLETES_AR = [20000, 10000, 2000, 1000, 500, 200, 100, 50, 20, 10];
/** Desde esta hora (Argentina) el cuadro recuerda cerrar la caja. */
const HORA_CIERRE_CAJA = 19;
const EFE = { suc:null, en:0, d:null, error:"", pidiendo:0 };
/** Abrir y cerrar: el que cobra en esa caja, o gerencia. */
const puedeCerrarCaja = () => puede("cuentas") || (puede("caja") && puede("cobrar"));
const fechaHoraAR = iso => fechaAR(iso) + " " + horaAR(iso);
/** "faltan $1.350" / "sobran $200" / "justo". */
const difTxt = d => Math.abs(d) < 0.005 ? "justo" : d < 0 ? "faltan " + fmt2(-d) : "sobran " + fmt2(d);
const difColor = d => Math.abs(d) < 0.005 ? "var(--ok)" : d < 0 ? "var(--bad)" : "var(--warn)";
/** "12 de $20.000 · 31 de $10.000 · monedas $1.350". */
const billetesTxt = b => BILLETES_AR.filter(d => +b[d] > 0).map(d => b[d] + " de " + fmt2(d).replace(",00", "")).concat(+b.monedas > 0 ? ["monedas " + fmt2(+b.monedas)] : []).join(" · ") || "sin detalle";

/* V.0.11.264. Damián: "lo de la caja de ayer fue de prueba ... poneme que
   solo gerencia pueda eliminarla". Solo la última de cada caja (la de más
   arriba) y solo gerencia; el servidor lo vuelve a controlar. V.0.11.265: el
   botón está solo en Gerencia → Cierres de caja; en Caja se ve todo pero no
   se elimina ("acá en caja que no se pueda eliminar, solo en gerencia"). */
const puedeElimCierre = () => puede("gerencia") || puede("cuentas");
/** Las últimas (una por sucursal) de una lista ordenada de la más nueva. */
function ultimosCierres(cs){
  const vistas = new Set(), ids = new Set();
  for(const c of cs) if(!vistas.has(c.sucursal)){ vistas.add(c.sucursal); ids.add(c.id); }
  return ids;
}
async function eliminarCierreCaja(id){
  const todos = [].concat((EFE.d && EFE.d.cierres) || [], CIE_GER || []);
  const c = todos.find(x => x.id === id); if(!c) return;
  const que = (c.tipo === "apertura" ? "la apertura" : "el cierre") + " de " + sucDe(c.sucursal).n + " del " + fechaAR(c.hasta) + " " + horaAR(c.hasta) + " (" + fmt2(c.contado) + ", " + c.usuario + ")";
  if(!confirm("¿Elimino " + que + "?\\n\\nDeja de contar: la caja vuelve a como estaba antes" + (c.tipo === "apertura" ? " (si era la única, queda sin abrir y hay que abrirla contando los billetes)." : ".") + " Queda anotado en Actividad.")) return;
  const r = await pedirJson("POST", CIE_URL, { accion:"eliminar", id, yo: soyYo() });
  if(r.error){ toast("No se eliminó: " + r.error); return; }
  toast("Eliminado. " + (c.tipo === "apertura" ? "Abrí la caja de nuevo con el conteo real." : "La caja vuelve a como estaba antes de ese cierre."));
  EFE.en = 0;
  try{ pintarEfectivo(true); }catch(e){}
  try{ pintarCierresGer(); }catch(e){}
}
document.addEventListener("click", e => {
  const b = e.target.closest && e.target.closest("[data-cie-elim]"); if(b) eliminarCierreCaja(b.dataset.cieElim);
});
let CIE_GER = [];
function filaCierre(c, conSuc, borrable){
  return '<tr title="' + atrib(billetesTxt(c.billetes || {})) + '">' +
    '<td class="num" style="white-space:nowrap;font-size:12.5px">' + fechaAR(c.hasta) + '<small>' + horaAR(c.hasta) + '</small></td>' +
    (conSuc ? '<td style="font-size:12.5px">' + txt(sucDe(c.sucursal).n) + '</td>' : '') +
    '<td style="font-size:12.5px">' + txt(c.usuario) + (c.tipo === "apertura" ? ' <span class="pill p-n">apertura</span>' : '') + '</td>' +
    '<td class="r num">' + (c.tipo === "apertura" ? "—" : fmt2(c.esperado)) + '</td>' +
    '<td class="r num">' + fmt2(c.contado) + '</td>' +
    '<td class="r num" style="font-weight:700;color:' + (c.tipo === "apertura" ? "var(--ink-3)" : difColor(c.diferencia)) + '">' + (c.tipo === "apertura" ? "—" : difTxt(c.diferencia)) + '</td>' +
    '<td class="r num">' + (c.retiro > 0 ? fmt2(c.retiro) + (c.destino ? '<small>' + txt(c.destino) + '</small>' : '') : "—") + '</td>' +
    '<td class="r num">' + fmt2(c.queda) + '</td>' +
    '<td style="font-size:12px;color:var(--ink-2)">' + txt(c.nota || "") +
      (borrable ? ' <button class="b3" type="button" data-cie-elim="' + atrib(c.id) + '" style="padding:3px 10px;font-size:12px" title="Solo gerencia: si fue de prueba">Eliminar</button>' : '') + '</td></tr>';
}
const cabezaCierres = conSuc => '<tr><th>Cuándo</th>' + (conSuc ? '<th>Sucursal</th>' : '') +
  '<th>Quién</th><th class="r">Tendría que haber</th><th class="r">Contado</th><th class="r">Diferencia</th><th class="r">Se retiró</th><th class="r">Quedó</th><th>Nota</th></tr>';

async function pintarEfectivo(forzar){
  const card = document.getElementById("efeCard"); if(!card) return;
  const suc = S.cajaSuc || "";
  if(!forzar && EFE.suc === suc && EFE.d && Date.now() - EFE.en < 20000){ dibujarEfectivo(); return; }
  const este = ++EFE.pidiendo;
  const d = await pedirJson("GET", CIE_URL + (suc ? "?suc=" + encodeURIComponent(suc) : ""));
  if(este !== EFE.pidiendo) return;
  EFE.suc = suc; EFE.en = Date.now();
  if(d.error){ EFE.d = null; EFE.error = d.error; } else { EFE.d = d; EFE.error = ""; }
  dibujarEfectivo();
}
function dibujarEfectivo(){
  const card = document.getElementById("efeCard"), cuerpo = document.getElementById("efeCuerpo"), sub = document.getElementById("efeSub");
  const btn = document.getElementById("efeAccion");
  if(EFE.error){ cuerpo.innerHTML = '<p class="vacio" style="padding:14px 16px">' + txt(EFE.error) + '</p>'; btn.hidden = true; sub.textContent = ""; return; }
  const d = EFE.d; if(!d){ cuerpo.innerHTML = '<p class="vacio" style="padding:14px 16px">Leyendo la caja…</p>'; btn.hidden = true; return; }
  const cierres = d.cierres || [];
  const hist = cierres.length
    ? '<div class="tabla-wrap" style="max-height:32vh;overflow-y:auto"><table class="densa"><thead>' + cabezaCierres(!EFE.suc) + '</thead><tbody>' +
        cierres.map(c => filaCierre(c, !EFE.suc, false)).join("") + '</tbody></table></div>'
    : '';
  if(!EFE.suc){
    sub.textContent = "elegí una sucursal arriba para abrirla o cerrarla";
    btn.hidden = true;
    cuerpo.innerHTML = cierres.length ? '<p class="nota" style="padding:10px 16px 0">Los últimos cierres de las tres:</p>' + hist
      : '<p class="vacio" style="padding:14px 16px">Todavía no se cerró ninguna caja.</p>';
    return;
  }
  const e = d.estado, n = sucDe(EFE.suc).n;
  if(!e || !e.ultimo){
    sub.textContent = n + ": todavía no se abrió";
    btn.hidden = !puedeCerrarCaja(); btn.textContent = "Abrir caja"; btn.dataset.acc = "abrir";
    cuerpo.innerHTML = '<p class="nota" style="padding:12px 16px">La caja de efectivo de <b>' + txt(n) + '</b> arranca acá: contá los billetes que hay ahora y tocá <b>Abrir caja</b>. Desde ahí, cada cierre deja anotado con cuánto abre el día siguiente.</p>';
    return;
  }
  const u = e.ultimo;
  // V.0.11.256: cerrada → se abre a la mañana contando; abierta → se cierra a la noche.
  if(!e.abierta){
    sub.textContent = n + " · cerrada desde " + fechaHoraAR(u.hasta);
    btn.hidden = !puedeCerrarCaja(); btn.textContent = "Abrir caja"; btn.dataset.acc = "abrir";
    cuerpo.innerHTML = '<div class="efe-aviso">La caja está <b>cerrada</b>: para cobrar, primero abrila contando los billetes.</div>' +
      '<div class="tiles" style="padding:12px 16px 4px;margin:0">' +
        tile("Quedó al cerrar", fmt2(e.apertura), fechaHoraAR(u.hasta) + " · " + u.usuario) +
        (Math.abs(e.movimientos) > 0.004 ? tile("Movimientos desde el cierre", fmt2(e.movimientos), "lo anotado en Plata de la caja") : "") +
        tile("Tendría que haber al abrir", fmt2(e.esperado), "en la caja", "acc") +
      '</div>' + hist;
    return;
  }
  sub.textContent = n + " · abierta desde " + fechaHoraAR(e.desde);
  btn.hidden = !puedeCerrarCaja(); btn.textContent = "Cerrar caja"; btn.dataset.acc = "cerrar";
  const hAR = new Date(Date.now() - 3 * 3600e3), hora = hAR.getUTCHours();
  const aviso = e.vieja
    ? '<div class="efe-aviso mal">Quedó <b>abierta desde el ' + fechaAR(e.desde) + '</b>: cerrala y volvé a abrirla. Hasta entonces no se puede cobrar.</div>'
    : hora >= HORA_CIERRE_CAJA
    ? '<div class="efe-aviso">Ya son las ' + String(hora).padStart(2, "0") + ':' + String(hAR.getUTCMinutes()).padStart(2, "0") + ': cuando termines de cobrar, <b>cerrá la caja</b>.</div>'
    : '';
  cuerpo.innerHTML = aviso + '<div class="tiles" style="padding:12px 16px 4px;margin:0">' +
      tile("Abrió con", fmt2(e.apertura), "abierta el " + fechaHoraAR(u.hasta) + " · " + u.usuario) +
      tile("Cobrado en efectivo", fmt2(e.ventas), "desde que abrió · factura y Recibo X") +
      tile("Gastos y retiros", fmt2(e.movimientos), "lo anotado en Plata de la caja") +
      tile("Tendría que haber", fmt2(e.esperado), "ahora, en la caja", "acc") +
    '</div>' + hist;
}

/* ---- el panel de billetes */
function abrirConteo(acc){
  const d = EFE.d, e = d && d.estado, suc = EFE.suc;
  if(!suc){ toast("Elegí la sucursal arriba."); return; }
  const cerrar = acc === "cerrar";
  // Al abrir después de un cierre también se compara: con lo que quedó.
  const compara = cerrar || !!(e && e.ultimo);
  const esperado = compara && e ? +e.esperado || 0 : 0;
  const viejo = document.getElementById("efeConteo"); if(viejo) viejo.remove();
  const idLocal = "cie" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  const fondo = document.createElement("div");
  fondo.className = "envio"; fondo.id = "efeConteo";
  fondo.innerHTML = '<div class="envio-caja" style="width:min(560px,100%)" role="dialog" aria-label="Contar la caja">' +
    '<div class="envio-h"><h3>' + (cerrar ? "Cerrar la caja" : "Abrir la caja") + ' · ' + txt(sucDe(suc).n) + '</h3>' +
      '<button class="x" type="button" data-cnt-no aria-label="cerrar">×</button></div>' +
    '<p class="envio-n">' + (cerrar ? "Contá los billetes que hay en la caja y escribí cuántos hay de cada uno." :
      compara ? "Contá los billetes que hay ahora: se compara con lo que quedó al cerrar." :
      "Contá los billetes que hay ahora: con eso arranca la caja.") + '</p>' +
    '<div class="cnt-grilla">' + BILLETES_AR.map(v =>
      '<label class="cnt-fila"><span class="cnt-den">' + fmt2(v).replace(",00", "") + '</span><span class="cnt-x">×</span>' +
      '<input type="number" min="0" step="1" inputmode="numeric" data-den="' + v + '" placeholder="0">' +
      '<span class="cnt-sub" data-sub="' + v + '">—</span></label>').join("") +
      '<label class="cnt-fila"><span class="cnt-den">Monedas y otros $</span><span class="cnt-x"></span>' +
      '<input type="text" inputmode="decimal" data-den="monedas" placeholder="0"><span class="cnt-sub" data-sub="monedas">—</span></label>' +
    '</div>' +
    '<div class="cnt-cuenta" id="cntCuenta"></div>' +
    (cerrar ? '<div class="cnt-retiro">' +
      '<label>Se retira de la caja (al banco, al dueño) $ <input type="text" inputmode="decimal" id="cntRetiro" placeholder="0"></label>' +
      '<label>¿Adónde va? <input type="text" id="cntDestino" maxlength="120" placeholder="Depósito banco, retiro del dueño…"></label></div>' : '') +
    '<label class="cnt-nota">Nota <input type="text" id="cntNota" maxlength="300" placeholder="opcional"></label>' +
    '<div class="envio-acc"><button class="b3" type="button" data-cnt-no>Cancelar</button>' +
      '<button class="b1" type="button" id="cntOk">' + (cerrar ? "Cerrar caja" : "Abrir caja") + '</button></div>' +
  '</div>';
  document.body.appendChild(fondo);
  const leer = () => {
    const b = {}; let total = 0;
    for(const i of fondo.querySelectorAll("input[data-den]")){
      const den = i.dataset.den;
      if(den === "monedas"){ const m = aNum(i.value) || 0; if(m > 0){ b.monedas = m; total += m; } fondo.querySelector('[data-sub="monedas"]').textContent = m > 0 ? fmt2(m) : "—"; continue; }
      const c = Math.max(0, Math.floor(+i.value || 0));
      if(c > 0) b[den] = c;
      total += c * +den;
      fondo.querySelector('[data-sub="' + den + '"]').textContent = c > 0 ? fmt2(c * +den) : "—";
    }
    return { b, total: Math.round(total * 100) / 100 };
  };
  const cuenta = () => {
    const { b, total } = leer();
    const ret = cerrar ? Math.max(0, aNum(fondo.querySelector("#cntRetiro").value) || 0) : 0;
    const dif = Math.round((total - esperado) * 100) / 100;
    fondo.querySelector("#cntCuenta").innerHTML =
      '<div class="cnt-l"><span>Contado</span><b>' + fmt2(total) + '</b></div>' +
      (cerrar ? '<div class="cnt-l"><span>Tendría que haber</span><b>' + fmt2(esperado) + '</b></div>' +
        '<div class="cnt-l"><span>Diferencia</span><b style="color:' + difColor(dif) + '">' + difTxt(dif).toUpperCase() + '</b></div>' +
        (ret > 0 ? '<div class="cnt-l"><span>Se retira</span><b>' + fmt2(ret) + '</b></div>' : '') +
        '<div class="cnt-l grande"><span>Queda para mañana</span><b' + (ret > total ? ' style="color:var(--bad)"' : '') + '>' + fmt2(total - ret) + '</b></div>'
      : (compara ? '<div class="cnt-l"><span>Quedó al cerrar</span><b>' + fmt2(esperado) + '</b></div>' +
          '<div class="cnt-l"><span>Diferencia</span><b style="color:' + difColor(dif) + '">' + difTxt(dif).toUpperCase() + '</b></div>' : '') +
        '<div class="cnt-l grande"><span>La caja abre con</span><b>' + fmt2(total) + '</b></div>');
    return { b, total, ret };
  };
  const fin = () => fondo.remove();
  fondo.addEventListener("input", cuenta);
  fondo.addEventListener("keydown", e => { if(e.key === "Escape"){ e.preventDefault(); e.stopPropagation(); fin(); } });
  fondo.addEventListener("click", async ev => {
    if(ev.target.closest("[data-cnt-no]")){ fin(); return; }
    if(!ev.target.closest("#cntOk")) return;
    const { b, total, ret } = cuenta();
    if(ret > total){ toast("No se puede retirar más de lo que se contó."); return; }
    if(!(total > 0) && !confirm(cerrar ? "Contaste $0: ¿la caja queda vacía?" : "¿La caja arranca en $0?")) return;
    const ok = fondo.querySelector("#cntOk"); ok.disabled = true; ok.textContent = "Guardando…";
    const r = await pedirJson("POST", CIE_URL, { accion: acc, sucursal: suc, idLocal, billetes: b, retiro: ret,
      destino: cerrar ? fondo.querySelector("#cntDestino").value : "", nota: fondo.querySelector("#cntNota").value, yo: soyYo() });
    if(r.error){ ok.disabled = false; ok.textContent = cerrar ? "Cerrar caja" : "Abrir caja"; toast("No se guardó: " + r.error); return; }
    fin();
    const c = r.cierre;
    toast(cerrar ? "Caja cerrada: " + difTxt(c.diferencia) + ". Quedan " + fmt2(c.queda) + " para mañana." :
      "Caja abierta con " + fmt2(c.contado) + (compara ? " (" + difTxt(c.diferencia) + ")" : "") + ". Ya se puede cobrar.");
    pintarEfectivo(true);
  });
  cuenta();
  setTimeout(() => { const p = fondo.querySelector("input[data-den]"); if(p) p.focus(); }, 0);
}
document.getElementById("efeAccion").addEventListener("click", async e => {
  const acc = e.currentTarget.dataset.acc || "cerrar";
  // Lo que tendría que haber, de recién: pudo entrar una venta mientras tanto.
  await pintarEfectivo(true);
  if(EFE.d && !EFE.error) abrirConteo(acc);
});

/* ---- Reset de la caja (V.0.11.256, Damián: "poneme un reset también pero
   solo en gerencia se pueda hacer porque ahora vamos a completar a modo de
   ejemplo"). Los cierres no se borran: dejan de contar. */
document.getElementById("gerResetCaja").addEventListener("click", async e => {
  const suc = S_FIL.ger || "";
  if(!suc){ toast("Elegí arriba de qué sucursal es la caja que querés resetear."); return; }
  const n = sucDe(suc).n;
  if(!confirm("¿Resetear la caja de efectivo de " + n + "? Los cierres que tiene dejan de contar (no se borran: quedan anotados en Actividad) y la caja vuelve a «todavía no se abrió»: se abre de nuevo contando los billetes.")) return;
  const b = e.currentTarget; b.disabled = true;
  const r = await pedirJson("POST", CIE_URL, { accion:"resetear", sucursal: suc, yo: soyYo() });
  b.disabled = false;
  if(r.error){ toast("No se reseteó: " + r.error); return; }
  EFE.en = 0;
  toast("Caja de " + n + " reseteada: " + (r.reseteados || 0) + (r.reseteados === 1 ? " cierre dejó" : " cierres dejaron") + " de contar. Se abre de nuevo desde Caja.");
  pintarCierresGer();
});
/* ---- Gerencia: los cierres de la sucursal elegida (o de todas) */
async function pintarCierresGer(){
  const tb = document.getElementById("gerCierres"); if(!tb) return;
  const suc = S_FIL.ger || "";
  // V.0.11.256: el reset, solo gerencia.
  const rb = document.getElementById("gerResetCaja");
  if(rb) rb.hidden = !(puede("gerencia") || puede("cuentas"));
  const d = await pedirJson("GET", CIE_URL + (suc ? "?suc=" + encodeURIComponent(suc) : ""));
  const cab = document.getElementById("gerCierresCab");
  if(cab) cab.innerHTML = cabezaCierres(!suc);
  if(d.error){ tb.innerHTML = '<tr><td colspan="9" class="vacio">' + txt(d.error) + '</td></tr>'; return; }
  const cs = d.cierres || [];
  CIE_GER = cs;
  const ult = ultimosCierres(cs);
  tb.innerHTML = cs.length ? cs.map(c => filaCierre(c, !suc, puedeElimCierre() && ult.has(c.id))).join("") : '<tr><td colspan="9" class="vacio">Todavía no hay cierres de caja.</td></tr>';
}

function pintarCaja(){
  pintarCajaSucs();
  pintarEfectivo(false);
  pintarFiltroVend();
  pintarHoy();
  const vs = ventasCaja();
  const cobrado = vs.reduce((a,v)=>a+ventaCobrado(v),0);
  const base = vs.reduce((a,v)=>a+ventaBase(v),0);
  const marg = vs.reduce((a,v)=>a+ventaMargen(v),0);

  document.getElementById("cajaTiles").innerHTML =
    tile("Entró hoy", fmt(cobrado), vs.length+" ventas en "+(S.cajaSuc?sucDe(S.cajaSuc).n:"las tres")) +
    tile("Valor de contado", fmt(base), "sin el recargo de tarjeta") +
    tile("Ticket promedio", fmt(div0(cobrado, vs.length)), "por venta") +
    tile("Presupuestos abiertos", fmt0(S.presupuestos), "sin cobrar todavía, de las tres") +
    tile("Margen bruto", fmt(marg), pct(div0(marg, base-marg)*100)+" sobre el costo");

  document.getElementById("cajaCount").textContent =
    vs.length + " ventas" + (S.cajaSuc ? " de "+sucDe(S.cajaSuc).n : "");
  document.getElementById("tbCaja").innerHTML = vs.slice().reverse().map(v=>{
    const n = v.linea.reduce((a,l)=>a+l.cant,0);
    const q = v.linea.map(l=>pdl(l).tit).join(" + ");
    return '<tr><td class="num" style="font-size:12.5px">'+v.hora+'</td>'+
      '<td style="font-size:12.5px;color:var(--ink-2);white-space:nowrap">'+sucDe(v.suc).n+'</td>'+
      '<td style="font-weight:600;white-space:nowrap">'+(v.web?'<span class="pill p-n">web</span> ':'')+(v.vend||"—")+'</td>'+
      '<td class="nom" style="min-width:260px">'+n+' art. <small>'+q.slice(0,72)+(q.length>72?"…":"")+'</small></td>'+
      '<td style="font-size:12.5px;color:var(--ink-2)">'+formaCorta(v.forma)+'</td>'+
      '<td>'+(v.facturada?'<span class="pill p-ok">factura</span>':'<span class="pill p-n">sin factura</span>')+'</td>'+
      '<td class="r">'+fmt(ventaCobrado(v))+'</td></tr>';
  }).join("");

  const pagos = {};
  for(const v of vs) pagos[v.forma] = (pagos[v.forma]||0) + ventaCobrado(v);
  const mx1 = Math.max(...Object.values(pagos));
  document.getElementById("porPago").innerHTML = Object.entries(pagos)
    .sort((a,b)=>b[1]-a[1]).map(([k,v])=>barra(formaCorta(k), v, mx1)).join("");

  // Quien vendio cuanto. Sin el filtro de vendedor puesto, para poder
  // comparar: si no, se veria una sola barra.
  const sinV = S.cajaSuc ? S.ventas.filter(v=>v.suc===S.cajaSuc) : S.ventas;
  const pvd = {};
  for(const v of sinV) pvd[v.vend||"—"] = (pvd[v.vend||"—"]||0) + ventaCobrado(v);
  const mxVd = Math.max(1, ...Object.values(pvd));
  document.getElementById("cajaPorVend").innerHTML = Object.entries(pvd)
    .sort((a,b)=>b[1]-a[1]).map(([k,n])=>barra(k, n, mxVd)).join("");

  // Las tres razones sociales, una al lado de la otra.
  const ps = {};
  for(const v of S.ventas) ps[v.suc] = (ps[v.suc]||0) + ventaCobrado(v);
  const mx3 = Math.max(...Object.values(ps));
  document.getElementById("porSuc").innerHTML = SUCURSALES
    .map(su=>barra(su.n, ps[su.id]||0, mx3)).join("");
}
function tile(k,v,d,cls){
  return '<div class="tile'+(cls?" "+cls:"")+'"><div class="k">'+k+'</div><div class="v">'+v+'</div><div class="d">'+d+'</div></div>';
}

/* ============================== CUENTAS Y GASTOS (V.0.11.226)
   Gerencia, parte 1. Damián: "en gerencia necesito que tenga un lugar donde
   sea los gastos diarios y los gastos mensuales de cada sucursal"; "puede ser
   efectivo, la caja de mercado pago, la caja de los bancos". Todo vive en el
   servidor (/sistema/cuentas); acá solo se muestra y se manda. El cajero ve
   el efectivo de su sucursal y lo de hoy; gerencia ("cuentas"), todo. */
const CTA_URL = "/sistema/cuentas";
const PLATA = { d:null, error:"", en:0 };
const TIPO_MOV = { gasto:"Gasto", "pago-proveedor":"Pago a proveedor", retiro:"Retiro", cobranza:"Cobranza de cuenta corriente",
  sena:"Seña", transferencia:"Pasar a otra cuenta", ajuste:"Ajuste" };
const TIPO_CTA = { efectivo:"Efectivo", mercadopago:"Mercado Pago", banco:"Banco" };
const nomSuc = id => (SUCURSALES.find(x => x.id === id) || {}).n || id;
/** Plata con el signo adelante: −$1.500,00 (fmt2 pondría $-1.500,00). */
const plataTxt = n => (n < 0 ? "−" : "") + fmt2(Math.abs(n));
const cuentaPlata = id => ((PLATA.d && PLATA.d.cuentas) || []).concat((PLATA.d && PLATA.d.destinos) || []).find(c => c.id === id);
const nombreCuenta = c => c ? (c.nombre + (c.tipo === "banco" && c.banco ? " · " + c.banco + (c.clase === "cc" ? " CC" : c.clase === "ca" ? " CA" : "") : "")) : "—";
const idNuevo = () => (window.crypto && crypto.randomUUID) ? crypto.randomUUID()
  : Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 12);
/** Lee /sistema/cuentas (hoy, o ese período si es gerencia). */
async function traerPlata(desde, hasta){
  const q = desde && hasta ? "?desde=" + encodeURIComponent(desde) + "&hasta=" + encodeURIComponent(hasta) : "";
  const { d } = await pedirSrv(CTA_URL + q);
  if(d && !d.error && Array.isArray(d.cuentas)){ PLATA.d = d; PLATA.error = ""; PLATA.en = Date.now(); }
  else PLATA.error = (d && d.error) || "No pude leer las cuentas.";
  return PLATA;
}
/** ¿Puede anular ese movimiento? Gerencia, todo; el cajero, lo suyo de hoy. */
function puedeAnularMov(m){
  if(!PLATA.d || m.anulado) return false;
  if(PLATA.d.puedeTodo) return true;
  const dia = new Date(Date.parse(m.fecha) - 3*3600e3).toISOString().slice(0, 10);
  return m.usuario === soyYo() && dia === PLATA.d.hoy;
}
function filaMov(m){
  const c = cuentaPlata(m.cuentaId);
  const h = new Date(m.fecha);
  const hora = h.toLocaleDateString("es-AR", { day:"2-digit", month:"2-digit", timeZone:"America/Argentina/Buenos_Aires" }) + " " +
    h.toLocaleTimeString("es-AR", { hour:"2-digit", minute:"2-digit", timeZone:"America/Argentina/Buenos_Aires" });
  const rep = m.reparto ? " · repartido " + Object.keys(m.reparto).map(k => nomSuc(k) + " " + m.reparto[k] + "%").join(", ") : "";
  return '<tr' + (m.anulado ? ' class="mov-anulado" title="anulado"' : '') + '><td class="num">' + txt(hora) + '</td>' +
    '<td>' + txt(TIPO_MOV[m.tipo] || m.tipo) + '</td>' +
    '<td>' + txt([m.rubro, m.detalle].filter(Boolean).join(" · ")) + txt(rep) + '</td>' +
    '<td>' + txt(nombreCuenta(c)) + (c ? ' <small style="color:var(--ink-3)">' + txt(nomSuc(c.sucursal)) + '</small>' : '') + '</td>' +
    '<td>' + txt(m.usuario) + '</td>' +
    '<td class="r" style="font-weight:600;color:' + (m.monto < 0 ? 'var(--bad)' : 'var(--ok)') + '">' + (m.monto < 0 ? "−" : "+") + fmt2(Math.abs(m.monto)) + '</td>' +
    '<td><div class="mov-acc">' + (m.eliminado
      ? '<span class="pill p-n" title="' + atrib("Eliminado por " + (m.eliminadoPor || "")) + '">eliminado</span>' +
        (PLATA.d && PLATA.d.puedeTodo ? '<button class="b3" type="button" data-mostrar-mov="' + atrib(m.id) + '" style="padding:3px 10px;font-size:12px">Volver a mostrar</button>' : '')
      : (m.anulado ? '<span class="pill p-n">anulado</span>' : puedeAnularMov(m) ? '<button class="b3" type="button" data-anular="' + atrib(m.id) + '" style="padding:3px 10px;font-size:12px">Anular</button>' : '') +
        (puedeEliminarMov(m) ? '<button class="b3" type="button" data-eliminar-mov="' + atrib(m.id) + '" style="padding:3px 10px;font-size:12px" title="Sacarlo de la lista' + (m.anulado ? '' : ' (también se anula)') + '">Eliminar</button>' : '')) +
    '</div></td></tr>';
}
/* V.0.11.262. Damián: "además de anular dame la posibilidad de eliminar para
   que no aparezca pero también deja la posibilidad de ver los eliminados".
   Eliminar lo saca de la lista; si no estaba anulado, se anula también (lo
   que no se ve no puede seguir contando). Con «ver los eliminados» se ven, y
   gerencia los puede volver a mostrar. Las mismas reglas que anular. */
PLATA.verElim = false;
function puedeEliminarMov(m){
  if(!PLATA.d || m.eliminado) return false;
  if(PLATA.d.puedeTodo) return true;
  const dia = new Date(Date.parse(m.fecha) - 3*3600e3).toISOString().slice(0, 10);
  return m.usuario === soyYo() && dia === PLATA.d.hoy;
}
const movVisible = m => PLATA.verElim || !m.eliminado;
async function eliminarMov(id, luego){
  const m = PLATA.d && PLATA.d.movimientos.find(x => x.id === id); if(!m) return;
  let motivo = "";
  if(!m.anulado){
    motivo = (prompt("¿Por qué se elimina? Además de sacarlo de la lista se anula: deja de contar en los saldos.") || "").trim();
    if(!motivo) return;
  } else if(!confirm("Se saca de la lista. Lo ves tildando «ver los eliminados». ¿Lo elimino?")) return;
  const { d } = await pedirSrv(CTA_URL, { accion:"eliminar", id, motivo });
  if(!d || d.error){ toast("No se eliminó: " + ((d && d.error) || "probá de nuevo.")); return; }
  toast("Eliminado. Lo ves tildando «ver los eliminados».");
  if(luego) luego();
}
async function mostrarMov(id, luego){
  const { d } = await pedirSrv(CTA_URL, { accion:"mostrar", id });
  if(!d || d.error){ toast("No se pudo: " + ((d && d.error) || "probá de nuevo.")); return; }
  toast("Vuelve a verse en la lista (sigue anulado).");
  if(luego) luego();
}
function clicMov(e, luego){
  const a = e.target.closest("[data-anular]"); if(a){ anularMov(a.dataset.anular, luego); return; }
  const el = e.target.closest("[data-eliminar-mov]"); if(el){ eliminarMov(el.dataset.eliminarMov, luego); return; }
  const mo = e.target.closest("[data-mostrar-mov]"); if(mo) mostrarMov(mo.dataset.mostrarMov, luego);
}
document.addEventListener("change", e => {
  const c = e.target.closest && e.target.closest("[data-ver-elim]"); if(!c) return;
  PLATA.verElim = c.checked;
  for(const x of document.querySelectorAll("[data-ver-elim]")) x.checked = c.checked;
  // Se vuelve a dibujar lo que está en pantalla (mira PLATA.verElim al dibujar).
  try{ if(!document.getElementById("v-cuentas").hidden) pintarCuentas(); }catch(e2){}
  try{ if(!document.getElementById("cajaPlata").hidden) pintarPlataCaja(false); }catch(e2){}
});
/** Anula (con el motivo) y vuelve a pintar. */
async function anularMov(id, luego){
  const motivo = (prompt("¿Por qué se anula este movimiento?") || "").trim();
  if(!motivo) return;
  const { d } = await pedirSrv(CTA_URL, { accion:"anular", id, motivo });
  if(!d || d.error){ toast("No se anuló: " + ((d && d.error) || "probá de nuevo.")); return; }
  toast("Anulado. Queda a la vista, tachado.");
  if(luego) luego();
}
/** El formulario de un movimiento. op: { sucursal, soloEfectivo, luego } */
function abrirMovimiento(op){
  if(document.getElementById("movFondo") || !PLATA.d) return;
  const todo = !!PLATA.d.puedeTodo;
  const activas = PLATA.d.cuentas.filter(c => c.activa);
  const origenes = activas.filter(c => !op.soloEfectivo || c.tipo === "efectivo");
  if(!origenes.length){ toast(todo ? "Primero cargá una cuenta (Gerencia → Cuentas y gastos → Nueva cuenta)." : "Todavía no hay caja cargada: pedile a gerencia que la cargue."); return; }
  const pre = origenes.find(c => c.tipo === "efectivo" && c.sucursal === op.sucursal) || origenes[0];
  const idLocal = idNuevo();
  const opc = (l, sel) => l.map(c => '<option value="' + atrib(c.id) + '"' + (c.id === sel ? " selected" : "") + '>' + txt(nomSuc(c.sucursal) + " · " + nombreCuenta(c)) + '</option>').join("");
  const tipos = ["gasto","pago-proveedor","retiro","cobranza","sena","transferencia"].concat(todo ? ["ajuste"] : []);
  const hoy = PLATA.d.hoy;
  document.body.insertAdjacentHTML("beforeend",
    '<div id="movFondo" style="position:fixed;inset:0;background:rgba(20,20,20,.38);z-index:2000;display:flex;align-items:center;justify-content:center;padding:16px">' +
    '<div class="card" role="dialog" aria-modal="true" aria-labelledby="movTit" style="position:relative;max-width:560px;width:100%;padding:18px;max-height:92vh;overflow-y:auto">' +
    '<button type="button" id="movX" class="cerrar-pop" aria-label="Cerrar" title="Cerrar" style="top:10px;right:10px">&times;</button>' +
    '<h3 id="movTit" style="margin:0 40px 12px 0">Anotar movimiento de plata</h3>' +
    '<div class="mov-form">' +
      '<label>Qué es<select id="movTipo">' + tipos.map(t => '<option value="' + t + '">' + txt(t === "transferencia" ? (op.soloEfectivo ? "Depositar en el banco / pasar a otra cuenta" : "Pasar a otra cuenta") : TIPO_MOV[t]) + '</option>').join("") + '</select></label>' +
      '<label>Monto<input id="movMonto" type="text" inputmode="decimal" autocomplete="off" placeholder="0,00"></label>' +
      '<label class="ancho">De qué cuenta<select id="movCuenta"' + (origenes.length < 2 ? " disabled" : "") + '>' + opc(origenes, pre.id) + '</select></label>' +
      '<label class="ancho" id="movDestinoEt" hidden>A qué cuenta<select id="movDestino"></select></label>' +
      '<label id="movSentidoEt" hidden>La plata<select id="movSentido"><option value="sale">Sale</option><option value="entra">Entra</option></select></label>' +
      '<label id="movRubroEt">Rubro<select id="movRubro">' + PLATA.d.rubros.map(r => '<option>' + txt(r) + '</option>').join("") + '</select></label>' +
      (todo ? '<label id="movFechaEt">Día<input id="movFecha" type="date" value="' + hoy + '" max="' + hoy + '"></label>' : '') +
      '<label class="ancho">Detalle<input id="movDetalle" type="text" maxlength="200" autocomplete="off" placeholder="Ej.: nafta para la camioneta"></label>' +
      (todo ? '<label id="movIvaEt">IVA incluido (si hay factura A)<input id="movIva" type="text" inputmode="decimal" autocomplete="off" placeholder="0,00"></label>' +
        '<label class="ancho" id="movRepEt"><span style="display:flex;align-items:center;gap:8px;text-transform:none;letter-spacing:0;font-size:13.5px"><input type="checkbox" id="movRepartir" style="width:auto"> Repartir entre razones sociales</span>' +
        '<span class="mov-reparto" id="movReparto" hidden>' + SUCURSALES.map(x => '<span>' + txt(x.n) + ' <input type="number" min="0" max="100" step="1" data-rep="' + x.id + '" value="' + (x.id === "srl" || x.id === "cnc" ? 50 : 0) + '">%</span>').join("") + '</span></label>' : '') +
    '</div>' +
    '<p class="nota" id="movMsg" style="margin:10px 0 0;min-height:1.2em"></p>' +
    '<div style="display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap;margin-top:8px">' +
      '<button class="b3" type="button" id="movNo">Cancelar</button>' +
      '<button class="b1" type="button" id="movOk">Guardar</button></div>' +
    '</div></div>');
  const g = id => document.getElementById(id);
  const fondo = g("movFondo"), msg = g("movMsg"), ok = g("movOk");
  const pintar = () => {
    const t = g("movTipo").value, o = cuentaPlata(g("movCuenta").value);
    g("movRubroEt").hidden = t !== "gasto";
    g("movSentidoEt").hidden = t !== "ajuste";
    if(g("movIvaEt")) g("movIvaEt").hidden = t !== "gasto";
    if(g("movRepEt")) g("movRepEt").hidden = t !== "gasto";
    g("movDestinoEt").hidden = t !== "transferencia";
    if(t === "transferencia"){
      // El cajero no ve los bancos con su saldo: le llegan aparte, solo el nombre (destinos).
      const dest = activas.concat((PLATA.d.destinos || []).filter(c => c.activa)).filter(c => o && c.id !== o.id && (todo || c.sucursal === o.sucursal));
      const antes = g("movDestino").value;
      g("movDestino").innerHTML = opc(dest, antes || ((dest.find(c => c.tipo === "banco") || dest[0] || {}).id));
    }
  };
  pintar();
  g("movTipo").addEventListener("change", pintar);
  g("movCuenta").addEventListener("change", pintar);
  if(g("movRepartir")) g("movRepartir").addEventListener("change", e => { g("movReparto").hidden = !e.target.checked; });
  setTimeout(() => g("movMonto").focus(), 30);
  const cerrar = () => { fondo.remove(); document.removeEventListener("keydown", tecla, true); };
  const tecla = e => { if(e.key === "Escape"){ e.stopPropagation(); cerrar(); } };
  document.addEventListener("keydown", tecla, true);
  g("movNo").addEventListener("click", cerrar);
  g("movX").addEventListener("click", cerrar);
  ok.addEventListener("click", async () => {
    const t = g("movTipo").value;
    const monto = aNum(g("movMonto").value);
    if(!(monto > 0)){ msg.textContent = "Poné el monto."; g("movMonto").focus(); return; }
    const p = { accion:"movimiento", idLocal, tipo:t, cuentaId:g("movCuenta").value, monto, detalle:g("movDetalle").value };
    if(t === "gasto") p.rubro = g("movRubro").value;
    if(t === "transferencia"){ p.cuentaDestinoId = g("movDestino").value; if(!p.cuentaDestinoId){ msg.textContent = "No hay otra cuenta a dónde pasarla."; return; } }
    if(t === "ajuste") p.sentido = g("movSentido").value;
    if(t === "gasto" && g("movIva")){ const iva = aNum(g("movIva").value); if(iva > 0) p.iva = iva; }
    if(t === "gasto" && g("movRepartir") && g("movRepartir").checked){
      const r = {}; let suma = 0;
      for(const x of document.querySelectorAll("#movReparto [data-rep]")){ const v = Math.round(+x.value || 0); if(v > 0){ r[x.dataset.rep] = v; suma += v; } }
      if(suma !== 100){ msg.textContent = "El reparto tiene que sumar 100% (ahora suma " + suma + "%)."; return; }
      p.reparto = r;
    }
    const f = g("movFecha");
    if(f && f.value && f.value !== hoy) p.fecha = f.value + "T15:00:00.000Z";   // las 12 del mediodía de ese día
    ok.disabled = true; msg.textContent = "Guardando…";
    const { d, red } = await pedirSrv(CTA_URL, p);
    ok.disabled = false;
    // Sin respuesta pudo haber llegado igual: se vuelve a tocar Guardar en este
    // mismo formulario (mismo idLocal) y no se anota dos veces.
    if(!d || d.error){ msg.textContent = red
      ? "No sé si llegó (" + ((d && d.error) || "sin conexión") + "). Tocá Guardar de nuevo: si ya había llegado, no se anota dos veces."
      : "No se guardó: " + ((d && d.error) || "probá de nuevo."); return; }
    cerrar();
    toast(d.yaEstaba ? "Ya estaba anotado." : (TIPO_MOV[t] || "Movimiento") + " de " + fmt2(monto) + " anotado.");
    if(op.luego) op.luego();
  });
}

/* La plata de la caja: el efectivo de la sucursal elegida, lo de hoy. */
async function pintarPlataCaja(forzar){
  const card = document.getElementById("cajaPlata"); if(!card) return;
  if(forzar || !PLATA.d || Date.now() - PLATA.en > 5000) await traerPlata();
  if(PLATA.error || !PLATA.d){ card.hidden = true; return; }
  card.hidden = false;
  const suc = S.cajaSuc || "";
  const cajas = PLATA.d.cuentas.filter(c => c.tipo === "efectivo" && c.activa && (!suc || c.sucursal === suc));
  const ids = new Set(cajas.map(c => c.id));
  const hoy = PLATA.d.hoy;
  const diaDe = m => new Date(Date.parse(m.fecha) - 3*3600e3).toISOString().slice(0, 10);
  const movs = PLATA.d.movimientos.filter(m => ids.has(m.cuentaId) && diaDe(m) === hoy && movVisible(m));
  const gastos = movs.filter(m => m.tipo === "gasto" && !m.anulado).reduce((a, m) => a - m.monto, 0);
  const salio = movs.filter(m => !m.anulado && m.monto < 0).reduce((a, m) => a - m.monto, 0);
  document.getElementById("cajaPlataSub").textContent = suc ? "efectivo de " + nomSuc(suc) : "el efectivo de las tres";
  document.getElementById("cajaPlataTiles").innerHTML = cajas.length
    ? tile("Efectivo según lo anotado", plataTxt(cajas.reduce((a, c) => a + c.saldo, 0)), "lo del arranque más lo anotado; las ventas en efectivo todavía no suman") +
      tile("Gastos de hoy", fmt2(gastos), movs.filter(m => m.tipo === "gasto" && !m.anulado).length + " anotados") +
      tile("Salió de la caja hoy", fmt2(salio), "gastos, pagos, retiros y depósitos")
    : tile("Sin caja cargada", "—", PLATA.d.puedeTodo ? "Cargala en Gerencia → Cuentas y gastos" : "Pedile a gerencia que la cargue");
  document.getElementById("tbPlataCaja").innerHTML = movs.length ? movs.map(filaMov).join("")
    : '<tr><td colspan="7" style="text-align:center;color:var(--ink-3);padding:18px">Hoy no se anotó nada' + (cajas.length ? "" : " (todavía no hay caja cargada)") + '.</td></tr>';
}
document.getElementById("btnAnotarMov").addEventListener("click", async () => {
  await traerPlata();
  if(PLATA.error){ toast(PLATA.error); return; }
  abrirMovimiento({ sucursal: S.cajaSuc || PLATA.d.sucursal || S.suc, soloEfectivo: true, luego: () => pintarPlataCaja(true) });
});
document.getElementById("tbPlataCaja").addEventListener("click", e => clicMov(e, () => pintarPlataCaja(true)));

/* Gerencia → Cuentas y gastos (V.0.11.226). */
const CTA = { per:"mes", suc:"" };
const hoyLocal = () => new Date(Date.now() - 3*3600e3).toISOString().slice(0, 10);
function periodoCta(){
  const hoy = hoyLocal(), [a, m] = hoy.split("-").map(Number);
  if(CTA.per === "hoy") return [hoy, hoy, "hoy"];
  if(CTA.per === "ant"){
    const pa = m === 1 ? a - 1 : a, pm = m === 1 ? 12 : m - 1;
    const ult = new Date(Date.UTC(pa, pm, 0)).getUTCDate();
    const mm = String(pm).padStart(2, "0");
    return [pa + "-" + mm + "-01", pa + "-" + mm + "-" + String(ult).padStart(2, "0"), "el mes anterior"];
  }
  if(CTA.per === "entre"){
    const d = document.getElementById("ctaDesde").value || hoy, h = document.getElementById("ctaHasta").value || hoy;
    return d <= h ? [d, h, "del " + fechaCorta(d) + " al " + fechaCorta(h)] : [h, d, "del " + fechaCorta(h) + " al " + fechaCorta(d)];
  }
  return [hoy.slice(0, 8) + "01", hoy, "este mes"];
}
const fechaCorta = d => d.slice(8, 10) + "/" + d.slice(5, 7) + "/" + d.slice(0, 4);
const sumaPor = (obj, suc) => suc ? ((obj[suc] || {}).total || 0) : Object.values(obj).reduce((a, x) => a + (x.total || 0), 0);
async function pintarCuentas(){
  const [desde, hasta, nombre] = periodoCta();
  document.getElementById("ctaPeriodo").innerHTML = [["hoy","Hoy"],["mes","Este mes"],["ant","Mes anterior"],["entre","Entre fechas"]]
    .map(([k, t]) => '<button type="button" data-per="' + k + '" aria-pressed="' + (CTA.per === k) + '">' + t + '</button>').join("");
  document.getElementById("ctaFechas").hidden = CTA.per !== "entre";
  document.getElementById("ctaSucs").innerHTML = [["","Todas"]].concat(SUCURSALES.map(x => [x.id, x.n]))
    .map(([id, n]) => '<button type="button" data-cs="' + id + '" aria-pressed="' + (id === CTA.suc) + '">' + txt(n) + '</button>').join("");
  await traerPlata(desde, hasta);
  const err = document.getElementById("ctaError");
  if(PLATA.error || !PLATA.d){ err.hidden = false; err.textContent = PLATA.error || "No pude leer las cuentas."; return; }
  err.hidden = true;
  const d = PLATA.d, suc = CTA.suc, ps = d.resumen.porSucursal || {};
  const deSuc = m => !suc || m.sucursal === suc || (m.reparto && m.reparto[suc]);
  const todosMovs = d.movimientos.filter(deSuc);
  const nElim = todosMovs.filter(m => m.eliminado).length;
  const movs = todosMovs.filter(movVisible);
  const vivos = todosMovs.filter(m => !m.anulado);
  const hoyGasto = Object.entries(ps).filter(([k]) => !suc || k === suc).reduce((a, [, x]) => a + ((x.porDia || {})[d.hoy] || 0), 0);
  const cuentas = d.cuentas.filter(c => !suc || c.sucursal === suc);
  const sale = t => vivos.filter(m => m.tipo === t).reduce((a, m) => a - m.monto, 0);
  document.getElementById("ctaTiles").innerHTML =
    tile("Gastos de hoy", desde <= d.hoy && d.hoy <= hasta ? fmt2(hoyGasto) : "—", suc ? nomSuc(suc) : "las tres razones sociales") +
    tile(CTA.per === "mes" ? "Gastos del mes" : "Gastos del período", fmt2(sumaPor(ps, suc)), nombre) +
    tile("Plata en las cuentas", plataTxt(cuentas.filter(c => c.activa).reduce((a, c) => a + c.saldo, 0)), cuentas.filter(c => c.activa).length + " cuentas activas; las ventas todavía no suman") +
    tile("Pagos a proveedores", fmt2(sale("pago-proveedor")), nombre + "; no son gasto: la mercadería ya está en el costo") +
    tile("Retiros", fmt2(sale("retiro")), nombre);
  // Por día: las tres columnas siempre, para compararlas.
  const dias = [...new Set(Object.values(ps).flatMap(x => Object.keys(x.porDia || {})))].sort().reverse();
  const col = (k, dia) => ((ps[k] || {}).porDia || {})[dia] || 0;
  document.getElementById("ctaDiasSub").textContent = nombre;
  document.getElementById("tbCtaDias").innerHTML = dias.length ? dias.map(dia => {
    const t = SUCURSALES.reduce((a, x) => a + col(x.id, dia), 0);
    return '<tr' + (dia === d.hoy ? ' style="font-weight:700"' : '') + '><td>' + fechaCorta(dia) + (dia === d.hoy ? ' <span class="pill p-ok">hoy</span>' : '') + '</td>' +
      SUCURSALES.map(x => '<td class="r num">' + (col(x.id, dia) ? fmt2(col(x.id, dia)) : '—') + '</td>').join("") +
      '<td class="r num" style="font-weight:700">' + fmt2(t) + '</td></tr>';
  }).join("") + '<tr style="font-weight:700;border-top:2px solid var(--line-2)"><td>Total</td>' +
      SUCURSALES.map(x => '<td class="r num">' + fmt2((ps[x.id] || {}).total || 0) + '</td>').join("") +
      '<td class="r num">' + fmt2(sumaPor(ps, "")) + '</td></tr>'
    : '<tr><td colspan="5" style="text-align:center;color:var(--ink-3);padding:18px">No hay gastos anotados ' + nombre + '.</td></tr>';
  // Por rubro.
  const rub = {};
  for(const [k, x] of Object.entries(ps)) if(!suc || k === suc) for(const [r, v] of Object.entries(x.porRubro || {})) rub[r] = (rub[r] || 0) + v;
  const rs = Object.entries(rub).sort((a, b) => b[1] - a[1]), max = rs.length ? rs[0][1] : 0;
  document.getElementById("ctaRubSub").textContent = (suc ? nomSuc(suc) + ", " : "") + nombre;
  document.getElementById("ctaRubros").innerHTML = rs.length ? rs.map(([r, v]) => barra(txt(r), v, max)).join("")
    : '<p class="nota" style="margin:0">Sin gastos ' + nombre + '.</p>';
  // Las cuentas, por razón social.
  document.getElementById("ctaCuentas").innerHTML = SUCURSALES.filter(x => !suc || x.id === suc).map(x => {
    const cs = d.cuentas.filter(c => c.sucursal === x.id);
    return '<div class="cta-grupo">' + txt(x.n) + '</div>' + (cs.length ? cs.map(c =>
      '<div class="cta-fila"><div><b>' + txt(c.nombre) + '</b>' + (c.activa ? '' : ' <span class="pill p-n">dada de baja</span>') +
        '<small>' + txt(TIPO_CTA[c.tipo] || c.tipo) + (c.tipo === "banco" ? ' · ' + txt(c.banco) + (c.clase === "cc" ? ' · cuenta corriente' : ' · caja de ahorro') : '') +
        ' · desde el ' + fechaCorta(c.desde) + '</small></div>' +
        '<span class="saldo" style="color:' + (c.saldo < 0 ? 'var(--bad)' : 'var(--ink)') + '">' + plataTxt(c.saldo) + '</span>' +
        '<button class="b3" type="button" data-cta="' + atrib(c.id) + '" style="padding:3px 10px;font-size:12px">Editar</button></div>').join("")
      : '<p class="nota" style="padding:4px 14px 10px;margin:0">Sin cuentas cargadas.</p>');
  }).join("");
  // Los movimientos del período.
  const nAnul = todosMovs.filter(m => m.anulado && !m.eliminado).length;
  document.getElementById("ctaMovSub").textContent = vivos.length + " " + nombre + (nAnul ? " (y " + nAnul + " anulados)" : "") +
    (nElim ? " · " + nElim + (nElim === 1 ? " eliminado" : " eliminados") + (PLATA.verElim ? "" : " (no se ven)") : "") +
    (d.truncado ? " · se ven los últimos 5.000 (los totales de arriba son de todos)" : "");
  document.getElementById("tbCtaMov").innerHTML = movs.length ? movs.map(filaMov).join("")
    : '<tr><td colspan="7" style="text-align:center;color:var(--ink-3);padding:18px">No hay movimientos ' + nombre + '.</td></tr>';
  document.getElementById("ctaRubrosLista").textContent = d.rubros.join(" · ");
  document.getElementById("btnNuevaCuenta").hidden = document.getElementById("btnRubros").hidden = !d.puedeTodo;
}
document.getElementById("ctaPeriodo").addEventListener("click", e => {
  const b = e.target.closest("[data-per]"); if(!b) return;
  CTA.per = b.dataset.per;
  if(CTA.per === "entre"){
    const h = hoyLocal();
    if(!document.getElementById("ctaDesde").value) document.getElementById("ctaDesde").value = h.slice(0, 8) + "01";
    if(!document.getElementById("ctaHasta").value) document.getElementById("ctaHasta").value = h;
  }
  pintarCuentas();
});
for(const id of ["ctaDesde", "ctaHasta"]) document.getElementById(id).addEventListener("change", () => pintarCuentas());
document.getElementById("ctaSucs").addEventListener("click", e => {
  const b = e.target.closest("[data-cs]"); if(!b) return;
  CTA.suc = b.dataset.cs; pintarCuentas();
});
document.getElementById("btnAnotarMovG").addEventListener("click", () => {
  if(!PLATA.d){ toast(PLATA.error || "Esperá un segundo: estoy leyendo las cuentas."); return; }
  abrirMovimiento({ sucursal: CTA.suc || S.suc, soloEfectivo: false, luego: pintarCuentas });
});
document.getElementById("tbCtaMov").addEventListener("click", e => clicMov(e, pintarCuentas));
document.getElementById("ctaCuentas").addEventListener("click", e => {
  const b = e.target.closest("[data-cta]"); if(b) abrirCuenta(cuentaPlata(b.dataset.cta));
});
document.getElementById("btnNuevaCuenta").addEventListener("click", () => abrirCuenta(null));
/** Cargar o cambiar una cuenta. */
function abrirCuenta(c){
  if(document.getElementById("ctaFondo") || !PLATA.d) return;
  const hoy = PLATA.d.hoy, suc = c ? c.sucursal : (CTA.suc || S.suc || "tsl");
  document.body.insertAdjacentHTML("beforeend",
    '<div id="ctaFondo" style="position:fixed;inset:0;background:rgba(20,20,20,.38);z-index:2000;display:flex;align-items:center;justify-content:center;padding:16px">' +
    '<div class="card" role="dialog" aria-modal="true" aria-labelledby="ctaTit" style="position:relative;max-width:520px;width:100%;padding:18px">' +
    '<button type="button" id="ctaX" class="cerrar-pop" aria-label="Cerrar" title="Cerrar" style="top:10px;right:10px">&times;</button>' +
    '<h3 id="ctaTit" style="margin:0 40px 12px 0">' + (c ? 'Cambiar la cuenta' : 'Nueva cuenta') + '</h3>' +
    '<div class="mov-form">' +
      '<label>Razón social<select id="ctaSuc"' + (c ? ' disabled' : '') + '>' + SUCURSALES.map(x => '<option value="' + x.id + '"' + (x.id === suc ? ' selected' : '') + '>' + txt(x.n) + '</option>').join("") + '</select></label>' +
      '<label>Qué es<select id="ctaTipo">' + Object.keys(TIPO_CTA).map(t => '<option value="' + t + '"' + (c && c.tipo === t ? ' selected' : '') + '>' + TIPO_CTA[t] + '</option>').join("") + '</select></label>' +
      '<label class="ancho">Nombre<input id="ctaNombre" type="text" maxlength="60" autocomplete="off" placeholder="Ej.: Caja del mostrador, Mercado Pago, Galicia CA" value="' + atrib(c ? c.nombre : "") + '"></label>' +
      '<label id="ctaBancoEt">Banco<input id="ctaBanco" type="text" maxlength="60" autocomplete="off" value="' + atrib(c ? c.banco : "") + '"></label>' +
      '<label id="ctaClaseEt">Tipo de cuenta<select id="ctaClase"><option value="ca"' + (c && c.clase === "ca" ? " selected" : "") + '>Caja de ahorro</option><option value="cc"' + (c && c.clase === "cc" ? " selected" : "") + '>Cuenta corriente</option></select></label>' +
      '<label>Saldo con el que arranca<input id="ctaSaldo" type="text" inputmode="decimal" autocomplete="off" value="' + (c ? NF_DOS.format(c.saldoInicial) : "0,00") + '"></label>' +
      '<label>Desde qué día<input id="ctaDesdeDia" type="date" max="' + hoy + '" value="' + (c ? c.desde : hoy) + '"></label>' +
      (c ? '<label class="ancho"><span style="display:flex;align-items:center;gap:8px;text-transform:none;letter-spacing:0;font-size:13.5px"><input type="checkbox" id="ctaActiva" style="width:auto"' + (c.activa ? ' checked' : '') + '> Activa (destildala para darla de baja; sus movimientos quedan)</span></label>' : '') +
    '</div>' +
    '<p class="nota" style="margin:10px 0 0">El saldo de cada día se calcula solo: lo que tenía al arrancar más lo que entró y menos lo que salió.</p>' +
    '<p class="nota" id="ctaMsg" style="margin:8px 0 0;min-height:1.2em"></p>' +
    '<div style="display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap;margin-top:8px">' +
      '<button class="b3" type="button" id="ctaNo">Cancelar</button><button class="b1" type="button" id="ctaOk">Guardar</button></div>' +
    '</div></div>');
  const g = id => document.getElementById(id);
  const pintar = () => { const b = g("ctaTipo").value === "banco"; g("ctaBancoEt").hidden = !b; g("ctaClaseEt").hidden = !b; };
  pintar(); g("ctaTipo").addEventListener("change", pintar);
  setTimeout(() => g("ctaNombre").focus(), 30);
  const cerrar = () => { g("ctaFondo").remove(); document.removeEventListener("keydown", tecla, true); };
  const tecla = e => { if(e.key === "Escape"){ e.stopPropagation(); cerrar(); } };
  document.addEventListener("keydown", tecla, true);
  g("ctaNo").addEventListener("click", cerrar); g("ctaX").addEventListener("click", cerrar);
  g("ctaOk").addEventListener("click", async () => {
    const p = { accion:"cuenta", sucursal:g("ctaSuc").value, tipo:g("ctaTipo").value, nombre:g("ctaNombre").value,
      banco:g("ctaBanco").value, clase:g("ctaClase").value, saldoInicial:aNum(g("ctaSaldo").value) || 0, desde:g("ctaDesdeDia").value };
    if(c){ p.id = c.id; p.activa = g("ctaActiva").checked; }
    g("ctaOk").disabled = true; g("ctaMsg").textContent = "Guardando…";
    const { d } = await pedirSrv(CTA_URL, p);
    g("ctaOk").disabled = false;
    if(!d || d.error){ g("ctaMsg").textContent = "No se guardó: " + ((d && d.error) || "probá de nuevo."); return; }
    cerrar(); toast("Cuenta " + (c ? "cambiada" : "cargada") + ": " + d.cuenta.nombre + ".");
    pintarCuentas();
  });
}
document.getElementById("btnRubros").addEventListener("click", async () => {
  if(!PLATA.d) return;
  const t = prompt("Los rubros de gasto, separados por coma (los que se saquen siguen leyéndose en los gastos viejos):", PLATA.d.rubros.join(", "));
  if(t == null) return;
  const { d } = await pedirSrv(CTA_URL, { accion:"rubros", rubros: t.split(",").map(x => x.trim()).filter(Boolean) });
  if(!d || d.error){ toast("No se guardó: " + ((d && d.error) || "probá de nuevo.")); return; }
  toast("Rubros guardados."); pintarCuentas();
});

/* =================================================== GERENCIA */
function pintarGerencia(){
  S.objetivo = +document.getElementById("fObj").value || 35;
  // V.0.11.254: con su sucursal, como Caja ("lo mismo gerencia").
  solapas("gerSucs", "ger");
  pintarCierresGer();
  const vs = filtrar(S_FIL.ger);
  const base = vs.reduce((a,v)=>a+ventaBase(v),0);
  const cobrado = vs.reduce((a,v)=>a+ventaCobrado(v),0);
  const marg = vs.reduce((a,v)=>a+ventaMargen(v),0);
  const fact = vs.filter(v=>v.facturada).reduce((a,v)=>a+ventaCobrado(v),0);
  const bajo = PRODUCTOS.filter(p=>margen(p)<0);
  const flojos = PRODUCTOS.filter(p=>{const m=margen(p); return m>=0 && m<S.objetivo;});
  const expuesto = bajo.reduce((a,p)=>a+(p.costo-p.contado)*p.stock,0);

  document.getElementById("gerTiles").innerHTML =
    tile("Vendido hoy", fmt(cobrado), vs.length+" ventas"+(S_FIL.ger ? " en "+sucDe(S_FIL.ger).n : ", mostrador y web")) +
    tile("Margen bruto", fmt(marg), pct(div0(marg, base-marg)*100)+" sobre el costo", "bien") +
    tile("Salió con factura", (div0(fact, cobrado)*100).toFixed(0)+"%", fmt(fact)+" de "+fmt(cobrado)) +
    tile("Se venden bajo costo", fmt0(bajo.length), "artículos del catálogo", bajo.length?"alerta":"") +
    tile("Plata en riesgo", fmt(expuesto), "si se vende todo ese stock", expuesto>0?"alerta":"");

  /* Los hallazgos son cuentas sobre los datos de arriba, no opiniones. */
  const hz = [];
  if(bajo.length){
    const peor = bajo.slice().sort((a,b)=>margen(a)-margen(b))[0];
    hz.push(["r","1","<b>"+bajo.length+" artículos se venden por debajo de lo que cuestan.</b> El peor es "+
      peor.cod.split("+")[0]+", "+peor.tit.slice(0,46)+"…: cuesta "+fmt(peor.costo)+" y se vende a "+fmt(peor.contado)+
      ", "+fmt(peor.costo-peor.contado)+" de pérdida por unidad, y hay "+peor.stock+" en depósito.",
      "Nadie lo ve porque el precio de venta se copia de la lista del proveedor."]);
  }
  const porProv = {};
  for(const p of PRODUCTOS){ (porProv[p.prov] = porProv[p.prov]||[]).push(margen(p)); }
  const peorProv = Object.entries(porProv).filter(([,a])=>a.length>=4)
    .map(([k,a])=>[k, a.reduce((x,y)=>x+y,0)/a.length, a.length]).sort((a,b)=>a[1]-b[1])[0];
  if(peorProv) hz.push(["a","2","<b>"+peorProv[0]+" es el proveedor que menos deja:</b> "+pct(peorProv[1])+
    " promedio en "+peorProv[2]+" artículos.","Con ese proveedor hay que negociar el descuento o subir el precio, no vender más."]);

  const recargo = cobrado - base;
  hz.push(["a","3","<b>"+fmt(recargo)+" de lo que entró hoy es recargo de tarjeta, no ganancia.</b> Se lo lleva la tarjeta.",
    "Por eso el margen se mide contra el precio de contado y no contra lo que entró a la caja."]);

  const pm = {};
  for(const v of vs){ const k=v.vend||"—"; pm[k]=pm[k]||{v:0,m:0}; pm[k].v+=ventaBase(v); pm[k].m+=ventaMargen(v); }
  const ord = Object.entries(pm).map(([k,o])=>[k, div0(o.m, o.v-o.m)*100]).sort((a,b)=>b[1]-a[1]);
  if(ord.length>1) hz.push(["v","4","<b>"+ord[0][0]+" vende con "+pct(ord[0][1])+" de margen y "+
    ord[ord.length-1][0]+" con "+pct(ord[ord.length-1][1])+".</b> No venden distinto: venden cosas distintas.",
    "Sirve para saber qué mercadería mueve cada uno, no para retar a nadie."]);

  const sinFact = vs.filter(v=>!v.facturada).reduce((a,v)=>a+ventaCobrado(v),0);
  hz.push(["v","5","<b>"+fmt(sinFact)+" salió sin factura hoy</b>, el "+(100-div0(fact, cobrado)*100).toFixed(0)+"% del día.",
    "Está en el mismo registro que el resto: un solo libro, con el dato adentro. Si no, la gerencia no sabe cuánto vendió de verdad."]);

  document.getElementById("hallazgos").innerHTML = hz.map(([c,n,t,e])=>
    '<div class="hz '+c+'"><span class="ic">'+n+'</span><p>'+t+'<em>'+e+'</em></p></div>').join("");

  const al = bajo.concat(flojos.sort((a,b)=>margen(a)-margen(b))).slice(0,16);
  document.getElementById("gerAlertCount").textContent = (bajo.length+flojos.length)+" artículos";
  document.getElementById("tbAlert").innerHTML = al.map(p=>{
    const m = margen(p);
    return '<tr><td class="num" style="font-size:12.5px">'+p.cod.split("+")[0]+'</td>'+
      '<td class="nom">'+p.tit.slice(0,58)+(p.tit.length>58?"…":"")+'</td><td>'+p.prov+'</td>'+
      '<td class="r">'+fmt(p.costo)+'</td><td class="r">'+fmt(p.contado)+'</td>'+
      '<td class="r" style="font-weight:600;color:'+(m<0?"var(--bad)":"var(--warn)")+'">'+pct(m)+'</td>'+
      '<td class="r">'+p.stock+'</td></tr>';
  }).join("");

  const mxm = Math.max(0, ...Object.values(pm).map(o=>o.m));
  document.getElementById("gerPuesto").innerHTML = Object.keys(pm).sort()
    .map(k=>barra(k, pm[k].m, mxm)).join("");

  document.getElementById("gerFact").innerHTML =
    barra("Con factura", fact, cobrado) + barra("Sin factura", cobrado-fact, cobrado, true);

  const top = {};
  for(const v of vs) for(const l of v.linea){ const p=pdl(l); top[p.cod]=(top[p.cod]||0)+(p.contado-p.costo)*l.cant; }
  const t5 = Object.entries(top).sort((a,b)=>b[1]-a[1]).slice(0,6);
  const mxt = t5.length?t5[0][1]:1;
  document.getElementById("gerTop").innerHTML = t5.map(([c,v])=>
    barra(((prod(c) || {tit:c}).tit || c).split(/[·(]/)[0].slice(0,26), v, mxt)).join("");
}

/* ========================================================= PEDIDOS
   Tomado de como lo resuelven los sistemas de distribuidores: grilla
   densa con el teclado, el problema de entrega EN EL RENGLON (no al
   final), y plantillas de lo que el cliente pide siempre. */
// Los clientes de verdad llegan de GBP (etapa siguiente). Hasta entonces,
// los que se dan de alta en el mostrador. Antes había seis inventados.
const CLIENTES = [];

/** Lo que hay en el otro deposito. Inventado, pero fijo para cada articulo. */
function stockOtro(p){ return p.dep[otroDep()]; }

/** El stock pintado: verde si sobra, amarillo si se está por acabar,
    rojo si no hay. Abajo, lo que queda en el otro depósito. */
function stockPill(p){
  if(p.aMano) return '<span class="stk" title="cargado a mano: no mueve stock">a mano</span>';
  const aca = p.stock, alla = p.dep[otroDep()];
  const cls = aca > 10 ? "stk-ok" : (aca > 0 ? "stk-poco" : "stk-no");
  const porque = aca > 10 ? "hay de sobra" : (aca > 0 ? "quedan pocos" : "no hay en este depósito");
  return '<span class="stk '+cls+'" title="'+porque+'">'+aca+'</span>'+
    '<span class="stk-otro">'+alla+' en '+DEPOSITOS[otroDep()]+'</span>';
}

// Los pedidos tomados (antes había cuatro inventados).
const PEDIDOS_ABIERTOS = [];

// El pedido abre vacío, como la venta.
const PED = { cliente:"", linea:[], entrega:"retira", senia:0 };
// El numero de pedido es uno solo para todo el sistema: sale de S.nroPed.
// Antes PED tenia el suyo, arrancaban los dos en 2842 y daban el mismo
// numero a dos pedidos distintos.
Object.defineProperty(PED, "nro", {
  get(){ return S.nroPed; },
  set(v){ S.nroPed = v; },
  enumerable:true, configurable:true
});

// Sin cliente elegido (o uno que ya no está), consumidor final.
const CONSUMIDOR_FINAL = { id:"", n:"Consumidor final", t:"Consumidor Final", doc:"—", saldo:0, lim:0, siempre:[] };
function clienteDe(id){ return CLIENTES.find(c=>c.id===id) || CONSUMIDOR_FINAL; }

/** Si el renglon se puede entregar, y de donde. */
function entregaDe(p, cant){
  if(cant <= p.stock) return {cls:"p-ok", txt:"hay", falta:0};
  const falta = cant - p.stock;
  const otro = stockOtro(p);
  if(otro >= falta)
    return {cls:"p-warn", txt:"faltan "+falta+", vienen del otro depósito", falta:0};
  return {cls:"p-bad", txt:"faltan "+falta+", hay que pedirlos", falta:falta - otro};
}

/** Las opciones de cliente del pedido, con Consumidor final primero. */
function opcionesClientePedido(){
  return '<option value=""'+(PED.cliente ? '' : ' selected')+'>Consumidor final</option>' +
    CLIENTES.map(c=>'<option value="'+atrib(c.id)+'"'+(c.id===PED.cliente?" selected":"")+'>'+txt(c.n)+'</option>').join("");
}
document.getElementById("selCliente").innerHTML = opcionesClientePedido();

function pintarCliente(){
  const c = clienteDe(PED.cliente);
  const pasado = c.lim > 0 && c.saldo > c.lim;
  document.getElementById("cliDatos").innerHTML =
    '<div><span>Condición</span><b style="font-size:12.5px;font-family:var(--font-b)">'+txt(c.t)+'</b></div>'+
    '<div><span>'+(soloNum(c.doc).length === 11 || !soloNum(c.doc).length ? 'CUIT' : 'DNI')+'</span><b>'+txt(c.doc)+'</b></div>'+
    (c.lim > 0
      ? '<div><span>Cuenta corriente</span><b style="color:'+(pasado?"var(--bad)":"var(--ink)")+'">'+
        fmt(c.saldo)+' de '+fmt(c.lim)+'</b></div>'+
        (pasado?'<div><span>&nbsp;</span><span class="pill p-bad">pasó el límite</span></div>':'')
      : '<div><span>Cuenta corriente</span><b style="font-size:12.5px;font-family:var(--font-b)">no tiene</b></div>');

  const siempre = c.siempre.map(prod).filter(Boolean);
  document.getElementById("siempre").innerHTML =
    '<span class="et">Siempre pide</span>' +
    // Hasta 44: cortar antes dejaba dos tanques distintos con el mismo
    // nombre, porque lo que los diferencia (los litros) va al final.
    siempre.map(p=>'<button data-c="'+p.cod+'">'+p.tit.split("·")[0].slice(0,44).trim()+'</button>').join("") +
    '<button data-c="__todos" style="background:var(--surface-3);border-color:var(--line-2)">Cargar todo</button>';
}

function pintarPedido(){
  guardarLocalPronto();
  pintarCliente();
  pintarCamposPedido();
  document.getElementById("pedNro").textContent = "Pedido P-" + PED.nro;

  const filas = PED.linea.map(l=>{
    const p = prod(l.cod);
    const e = entregaDe(p, l.cant);
    return {l, p, e, sub: p.contado * l.cant};
  });

  document.getElementById("tbPed").innerHTML = filas.length
    ? filas.map(({l,p,e,sub})=>
        '<tr data-cod="'+p.cod+'"><td class="num" style="font-size:12px">'+p.cod.split("+")[0]+'</td>'+
        '<td class="nom" style="min-width:210px">'+p.tit.slice(0,58)+(p.tit.length>58?"…":"")+'</td>'+
        '<td class="r"><input class="cant" type="number" min="1" step="1" value="'+l.cant+'" data-c="'+l.cod+'" aria-label="cantidad"></td>'+
        '<td class="r">'+fmt(p.contado)+'</td>'+
        '<td class="r" style="font-weight:600">'+fmt(sub)+'</td>'+
        '<td>'+pillFaltaPed(l, p, e)+'</td>'+
        '<td><button class="quitar-fila" data-x="'+l.cod+'" aria-label="quitar">×</button></td></tr>').join("")
    : '<tr><td colspan="7" class="vacio">Todavía no hay renglones. Buscá arriba y apretá Enter.</td></tr>';

  document.getElementById("pedCuenta").textContent =
    filas.length ? filas.reduce((a,f)=>a+f.l.cant,0)+" unidades en "+filas.length+" renglones" : "";

  // Lo que de verdad no se puede entregar: ni acá ni en el otro depósito.
  const faltan = filas.filter(f=>f.e.falta > 0);
  document.getElementById("pedFaltan").innerHTML = faltan.length
    ? '<div class="aviso" style="margin:12px 14px;border-left-color:var(--bad)"><span>⚠</span><div>'+
      '<b>'+faltan.length+(faltan.length===1?' renglón no se puede entregar':' renglones no se pueden entregar')+
      ' con lo que hay.</b> Faltan '+faltan.reduce((a,f)=>a+f.e.falta,0)+' unidades entre todos. '+
      'Decile al cliente ahora, no cuando venga a buscarlo.'+
      '<div style="margin-top:8px">'+botonAlProveedor(faltan)+'</div>'+
      '</div></div>'
    : "";

  // Los mismos renglones que GBP pone abajo de la grilla, pero diciendo lo
  // que son. El IVA va incluido en el precio, no se suma aparte: en el
  // mostrador el precio que se dice es el precio final.
  const bruto = filas.reduce((a,f)=>a+f.sub,0);
  const dto = cent(bruto * PEDCFG.desc / 100);
  const total = bruto - dto;
  const iva = cent(total - total / 1.21);
  const senia = Math.max(0, Math.min(PED.senia, total));
  document.getElementById("pedTot").innerHTML =
    '<div class="tr"><span>Mercadería</span><b>'+fmt(bruto)+'</b></div>'+
    (dto>0 ? '<div class="tr"><span>Descuento '+PEDCFG.desc+'%</span><b>−'+fmt(dto)+'</b></div>' : '')+
    '<div class="tr"><span>Interés</span><b>'+fmt(0)+'</b></div>'+
    '<div class="tr"><span style="color:var(--ink-3)">IVA 21%, ya incluido arriba</span>'+
      '<b style="color:var(--ink-3)">'+fmt(iva)+'</b></div>'+
    (senia>0 ? '<div class="tr"><span>Seña</span><b>−'+fmt(senia)+'</b></div>' : '')+
    '<div class="tr big"><span>'+(senia>0?"Queda a pagar":"Importe")+'</span><b>'+fmt(total-senia)+'</b></div>';

  const vacio = filas.length === 0;
  document.getElementById("btnGuardarPed").disabled = vacio;
  document.getElementById("btnWhatsPed").disabled = vacio;

  // Los pedidos ya tomados.
  document.getElementById("pedAbiertos").textContent = PEDIDOS_ABIERTOS.length + " pedidos";
  document.getElementById("tbPedidos").innerHTML = PEDIDOS_ABIERTOS.map(o=>{
    const c = clienteDe(o.cli);
    const tot = o.lin.reduce((a,[cod,n])=>a+prod(cod).contado*n,0);
    const cls = o.est==="listo para retirar" ? "p-ok"
      : o.est==="esperando mercadería" ? "p-bad" : "p-n";
    return '<tr><td class="num" style="font-size:12.5px">'+o.nro+'</td>'+
      '<td style="font-weight:500">'+txt(c && c.id ? c.n : (o.cliN || (c ? c.n : "—")))+'</td>'+
      '<td class="nom" style="min-width:220px">'+o.lin.reduce((a,[,n])=>a+n,0)+' un. '+
        '<small>'+o.lin.map(([cod])=>prod(cod).tit.split("·")[0].slice(0,26)).join(" + ")+'</small></td>'+
      '<td style="font-size:12.5px">'+(o.ent==="retira"?"retira":"envío")+', '+o.cuando+'</td>'+
      '<td class="r">'+fmt(tot)+'</td>'+
      '<td class="r" style="color:var(--ink-3)">'+(o.senia?fmt(o.senia):"—")+'</td>'+
      '<td><span class="pill '+cls+'">'+o.est+'</span></td></tr>';
  }).join("");
}

document.getElementById("selCliente").addEventListener("change",e=>{
  PED.cliente = e.target.value; pintarPedido();
});
document.getElementById("siempre").addEventListener("click",e=>{
  const b = e.target.closest("button[data-c]"); if(!b) return;
  const c = clienteDe(PED.cliente);
  const cods = b.dataset.c === "__todos" ? c.siempre : [b.dataset.c];
  for(const cod of cods){
    const l = PED.linea.find(x=>x.cod===cod);
    if(l) l.cant++; else PED.linea.push({cod, cant:1});
  }
  pintarPedido();
});


/** El buscador de renglones. Entra marca, rubro, nombre o codigo, en
    cualquier orden y sin tener que escribir la palabra entera. Enter mete
    el primero que aparece, con la cantidad que diga al lado. */
function buscarPed(){
  const crudo = document.getElementById("qPed").value.trim();
  const q = plano(crudo);
  const caja = document.getElementById("resPed");
  if(!q){ caja.innerHTML = ""; return []; }
  const toks = q.split(/\\s+/).filter(Boolean);
  const rr = encontrar(toks);
  const hits = rr.hits
    .slice(0,8);

  if(!hits.length){
    caja.innerHTML = '<div class="vacio">Nada con <b>“'+crudo+'”</b>. Probá con menos palabras, o tocá una marca de arriba.</div>';
    return [];
  }
  // El mismo listado que el mostrador, para no leer dos formatos.
  caja.innerHTML =
    '<div class="tabla-wrap"><table class="densa res-t"><thead><tr>'+
      '<th>Código</th><th>Artículo</th><th>Marca</th><th class="r">Stock</th>'+
      '<th class="r">Contado</th><th class="r">Cant.</th><th></th>'+
    '</tr></thead><tbody>'+
    hits.map(({p})=>{
      const st = stockPill(p);
      return '<tr data-cod="'+p.cod+'" style="cursor:pointer">'+
        '<td class="num" style="font-size:12px">'+p.cod.split("+")[0]+'</td>'+
        '<td class="nom" style="min-width:230px">'+p.tit+'<small>'+p.rub.toLowerCase()+'</small></td>'+
        '<td style="font-size:12px;color:var(--ink-2)">'+p.prov+'</td>'+
        '<td class="r">'+st+'</td>'+
        '<td class="r" style="font-weight:600">'+fmt(p.contado)+'</td>'+
        '<td class="r"><input class="cant" type="number" min="1" step="1" value="1" data-q="'+p.cod+'" aria-label="cantidad"></td>'+
        '<td><button class="sumar" data-add="'+p.cod+'">Sumar</button></td>'+
      '</tr>';
    }).join("")+
    '</tbody></table></div>';
  const pri = caja.querySelector("tr[data-cod]");
  if(pri) pri.classList.add("marcado");
  return hits.map(h=>h.p);
}
function agregarPed(cod, cuantos){
  const cant = Math.max(1, Math.floor(+cuantos || 1));
  const l = PED.linea.find(x=>x.cod===cod);
  if(l) l.cant += cant; else PED.linea.push({cod, cant});
  marcarNuevo(cod);
  toast(cant+" × "+prod(cod).tit.slice(0,46)+" al pedido.");
  document.getElementById("qPed").value = "";
  document.getElementById("resPed").innerHTML = "";
  pintarPedido();
  // Como en la venta: el cursor vuelve al buscador para seguir agregando.
  document.getElementById("qPed").focus();
}
document.getElementById("qPed").addEventListener("input", buscarPed);
document.getElementById("qPed").addEventListener("keydown",e=>{
  if(e.key !== "Enter") return;
  const hits = buscarPed();
  const t = document.querySelector("#resPed tr.marcado");
  if(t) agregarPed(t.dataset.cod, 1);
  else if(hits.length) agregarPed(hits[0].cod, 1);
});
document.getElementById("resPed").addEventListener("click",e=>{
  // Sirve el botón Sumar y también tocar el renglón en cualquier lado,
  // menos adentro del casillero de la cantidad.
  if(e.target.closest("input")) return;
  const b = e.target.closest("[data-add]") || e.target.closest("tr[data-cod]");
  if(!b) return;
  const cod = b.dataset.add || b.dataset.cod;
  const campo = document.querySelector('#resPed input[data-q="'+cod+'"]');
  agregarPed(cod, campo ? +campo.value : 1);
});
document.getElementById("resPed").addEventListener("keydown",e=>{
  if(e.key!=="Enter") return;
  const i = e.target.closest("input[data-q]"); if(!i) return;
  e.preventDefault();
  agregarPed(i.dataset.q, +i.value);
});
document.getElementById("tbPed").addEventListener("input",e=>{
  const i = e.target.closest("input[data-c]"); if(!i) return;
  const l = PED.linea.find(x=>x.cod===i.dataset.c); if(!l) return;
  l.cant = Math.max(1, Math.floor(+i.value || 1));
  pintarPedido();
});
document.getElementById("tbPed").addEventListener("click",e=>{
  const b = e.target.closest("button[data-x]"); if(!b) return;
  PED.linea = PED.linea.filter(x=>x.cod !== b.dataset.x);
  pintarPedido();
});
document.getElementById("pedFaltan").addEventListener("click",e=>{
  if(!e.target.closest("#btnAlProveedor")) return;
  // Ahora van de verdad al pedido del proveedor (ver faltantesAlProveedor).
  faltantesAlProveedor();
});
document.getElementById("formaEntrega").addEventListener("click",e=>{
  const b = e.target.closest("button[data-e]"); if(!b) return;
  PED.entrega = b.dataset.e;
  for(const x of document.querySelectorAll("#formaEntrega button")) x.setAttribute("aria-pressed", String(x===b));
  document.getElementById("dirEnvio").hidden = PED.entrega !== "envio";
});
document.getElementById("senia").addEventListener("input",e=>{
  PED.senia = Math.max(0, +e.target.value || 0); pintarPedido();
});
// V.0.99.82: el pedido se guarda en el servidor y el número lo da él (la
// misma serie que los comprobantes): dos puestos nunca sacan el mismo, y lo
// ve cualquier compu.
let GUARDANDO_PED = false;
/** Lo que es el pedido de la pantalla: su marca vale mientras esto no cambie. */
function firmaPedido(){
  return JSON.stringify([PED.cliente, PED.linea.map(l => [l.cod, l.cant]), PED.entrega, valor("fecha"),
    valor("dir"), valor("obsPed"), valor("intPed"), PED.senia]);
}
/** Guarda en el servidor el pedido de la pantalla y la deja lista para el
    siguiente. Devuelve el pedido guardado (como los de la lista), o null
    (y lo dice). Lo usa también "pedir los faltantes al proveedor": el
    pedido al proveedor dice para qué pedido es, con su número de verdad. */
async function guardarPedidoActual(){
  if(GUARDANDO_PED || !PED.linea.length) return null;
  const c = clienteDe(PED.cliente);
  const total = PED.linea.reduce((a,l)=>a+prod(l.cod).contado*l.cant,0);
  const hayFalta = PED.linea.some(l=>entregaDe(prod(l.cod), l.cant).falta > 0);
  const cods = new Set(PED.linea.map(l=>l.cod));
  // La marca: si se corta la respuesta y se vuelve a tocar Guardar (o se
  // recarga), el servidor devuelve el mismo pedido y no saca otro número.
  // Si el pedido cambió desde entonces, es otro: otra marca (si no, volvía
  // el viejo y lo nuevo se perdía).
  const firma = firmaPedido();
  if(!PED.marca || PED.marcaFirma !== firma){
    PED.marca = "pm" + Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
    PED.marcaFirma = firma;
    guardarLocal();               // al toque: si se recarga ahora, la marca sobrevive
  }
  GUARDANDO_PED = true;
  const b = document.getElementById("btnGuardarPed"); b.disabled = true;
  let d;
  try{
    d = (await pedirSrv(VTA_URL, { accion:"pedido", venta:{
      datos:{ linea: PED.linea.map(l => Object.assign({}, l)), manuales: manualesDe(cods),
              cliente: PED.cliente || "", clienteDatos: clienteDatosDe(c),
              ped:{ entrega:PED.entrega, cuando: document.getElementById("fecha").value || "a confirmar",
                    dir: valor("dir"), obs: valor("obsPed"), int: valor("intPed"),
                    senia: Math.min(PED.senia, total), est: hayFalta ? "esperando mercadería" : "preparando", cfg: PEDCFG,
                    marca: PED.marca } },
      cliente: c.n, total, sucursal: S.suc, vendedor: VENDEDOR_LOGIN || S.usuario || "" } })).d;
  } finally { GUARDANDO_PED = false; b.disabled = !PED.linea.length; }
  if(!d.ok || !d.venta){ toast("No se guardó el pedido: " + (d.error || "probá de nuevo.") + " Queda en pantalla."); return null; }
  PED.marca = null; PED.marcaFirma = null;
  const p = pedidoDeServidor(d.venta);
  if(!PEDIDOS_ABIERTOS.some(x => x.id === p.id)) PEDIDOS_ABIERTOS.unshift(p);
  const nro = +((d.venta.datos || {}).ped || {}).nro || 0;
  if(nro && S.nroPed < nro + 1) S.nroPed = nro + 1;
  toast("Pedido "+p.nro+" guardado para "+c.n+" por "+fmt(total)+
    (hayFalta ? ". Queda esperando mercadería." : ". Ya se puede preparar."));
  PED.linea = []; PED.senia = 0;
  document.getElementById("senia").value = 0;
  pintarPedido();
  return p;
}
document.getElementById("btnGuardarPed").addEventListener("click", () => { guardarPedidoActual(); });
document.getElementById("btnWhatsPed").addEventListener("click",()=>{
  const c = clienteDe(PED.cliente);
  const doc = PEDCFG.doc || docDe(c)[0];
  const nro = letraDe(doc)+" "+sucAct().pv+"-"+String(PED.nro).padStart(8,"0");
  const lineas = PED.linea.map(l=>({p:prod(l.cod), cant:l.cant}));
  const bruto = lineas.reduce((a,x)=>a+x.p.contado*x.cant,0);
  const total = bruto - Math.round(bruto*PEDCFG.desc/100);
  abrirEnvio({
    quien: c && c.id ? c.n : "",
    tit: doc.replace(/^\\d+\\./,""), nro, lineas,
    total: total - (PED.senia||0), senia: PED.senia||0
  });
});
document.getElementById("btnVaciarPed").addEventListener("click",()=>{
  PED.linea = []; PED.senia = 0;
  document.getElementById("senia").value = 0; pintarPedido();
});
(function fechaPorDefecto(){
  const d = new Date(); d.setDate(d.getDate() + 2);
  document.getElementById("fecha").value = d.toISOString().slice(0,10);
})();

/* ============================================ LISTAS QUE LLEGARON
   El corazón del producto: la lista entra como la mandó el proveedor y
   el sistema la cruza solo. Nadie la carga a mano. */
// Las listas que llegan por WhatsApp o mail todavía no entran solas: se
// cargan a mano en "Cargar una lista". Antes había tres inventadas.
const SOBRES = [];
document.getElementById("bandeja").innerHTML = SOBRES.map((s,i)=>
  '<button class="sobre" data-s="'+i+'" aria-pressed="false">'+
    '<span class="via"><span class="pill p-n">'+s.icono+'</span>'+s.via+'</span>'+
    '<span class="de">'+s.prov+'</span>'+
    '<span class="ar">'+s.archivo+'</span>'+
    '<span class="cuando">'+s.cuando+'</span>'+
  '</button>').join("");

document.getElementById("bandeja").addEventListener("click",e=>{
  const b = e.target.closest("button[data-s]"); if(!b) return;
  for(const x of document.querySelectorAll("#bandeja .sobre")) x.setAttribute("aria-pressed", String(x===b));
  const s = SOBRES[+b.dataset.s];

  document.getElementById("lectura").hidden = false;
  document.getElementById("lecturaDe").textContent = s.archivo;
  // Los que enganchan son los que de verdad están en el catálogo cargado.
  // Inventar un número más lindo haría que la pantalla se contradiga sola.
  const enganchados = PRODUCTOS.filter(p=>p.prov===s.prov).length;
  const sinCruzar = Math.max(0, s.renglones - enganchados);
  document.getElementById("lecturaCuerpo").innerHTML =
    '<div class="lect-fila">'+
      '<div class="lect-dato"><div class="k">Renglones en la lista</div><div class="v">'+s.renglones+'</div></div>'+
      '<div class="lect-dato"><div class="k">Los tenés cargados</div><div class="v" style="color:var(--ok)">'+enganchados+'</div></div>'+
      '<div class="lect-dato"><div class="k">No los trabajás</div><div class="v" style="color:var(--ink-3)">'+sinCruzar+'</div></div>'+
      '<div class="lect-dato"><div class="k">'+(s.modo==="sube"?"Sube":"Descuento")+'</div><div class="v">'+
        (s.modo==="sube"? "+"+String(s.valor).replace(".",",")+"%" : s.d1+"→"+s.d2+"%")+'</div></div>'+
    '</div>'+
    '<div class="lect-raw">'+s.muestra.map(([crudo,cod,tit])=>
      'venía así  '+crudo+'\\n'+
      'lo leí como  <b>'+(cod==="—"?tit:cod+"  "+tit)+'</b>').join("\\n\\n")+'</div>'+
    '<p class="nota" style="padding:0">Así escribe el proveedor y así lo entiende el sistema. '+
    'Hay '+PRODUCTOS.length+' artículos cargados, y de la lista engancha '+enganchados+
    '. Lo que no reconoce queda marcado para que lo mires vos: nunca lo adivina.</p>';

  // Carga el simulador de abajo con lo que dice la lista y lo corre.
  document.querySelector('#sQuien button[data-q="prov"]').click();
  document.getElementById("sProv").value = s.prov;
  if(s.modo === "sube"){
    document.querySelector('#sModo button[data-m="sube"]').click();
    document.getElementById("sPct").value = s.valor;
  } else {
    // La lista avisa que baja el descuento: se carga la cadena que rige y
    // se le cambia el primero, que es el que el proveedor mueve.
    document.querySelector('#sModo button[data-m="desc"]').click();
    PF.seis = (S.cadenas[s.prov] || DESC_PROV[s.prov] ? cadenaDe(s.prov) : CADENA_BASE).slice(0,N_DTOS);
    while(PF.seis.length < N_DTOS) PF.seis.push(0);
    PF.seis[0] = limD(s.d2);
    pintarSeis();
  }
  document.getElementById("btnSim").click();
  document.getElementById("lectura").scrollIntoView({behavior:"smooth", block:"start"});
});

/* ================================================= EL ASISTENTE
   Cada respuesta se calcula sobre los datos de arriba en el momento. */
const PREGUNTAS = [
  {b:"¿Qué pierde plata?", k:["pierde","perdiendo","perdida","bajo costo","debajo","rojo","mal"], f(){
    const mal = PRODUCTOS.filter(p=>margen(p)<0).sort((a,b)=>margen(a)-margen(b));
    if(!mal.length) return "Ahora mismo <b>no hay ninguno</b> vendiéndose por debajo del costo. Con los precios y costos que están cargados en esta pantalla, todos dejan algo.";
    const plata = mal.reduce((a,p)=>a+(p.costo-p.contado)*p.stock,0);
    const uno = mal.length === 1;
    return "Hay <b>"+mal.length+"</b> "+(uno?"artículo que se vende":"artículos que se venden")+
      " por menos de lo que "+(uno?"cuesta":"cuestan")+". Si se vende todo el stock que hay, "+
      (uno?"es":"son")+" <b class='cifra'>"+fmt(plata)+"</b> de pérdida.<ul>"+
      mal.slice(0,5).map(p=>"<li>"+p.cod.split("+")[0]+" · "+p.tit.slice(0,46)+" — cuesta <span class='cifra'>"+fmt(p.costo)+"</span>, se vende a <span class='cifra'>"+fmt(p.contado)+"</span>, hay "+p.stock+"</li>").join("")+
      "</ul>"+(mal.length>5?"Y "+(mal.length-5)+" más. Están todos en Gerencia.":"");
  }},
  {b:"¿Cuánto vendimos hoy?", k:["vendimos","venta","vendi","hoy","caja","cuanto entro","facturado"], f(){
    const vs = S.ventas;
    const cob = vs.reduce((a,v)=>a+ventaCobrado(v),0);
    const base = vs.reduce((a,v)=>a+ventaBase(v),0);
    const mg = vs.reduce((a,v)=>a+ventaMargen(v),0);
    const fa = vs.filter(v=>v.facturada).reduce((a,v)=>a+ventaCobrado(v),0);
    if(!vs.length) return "Todavía no hubo ventas hoy.";
    return "Entraron <b class='cifra'>"+fmt(cob)+"</b> en "+vs.length+" ventas.<ul>"+
      "<li>De eso, <span class='cifra'>"+fmt(cob-base)+"</span> es recargo de tarjeta: se lo lleva la tarjeta, no es tuyo.</li>"+
      "<li>Margen bruto: <span class='cifra'>"+fmt(mg)+"</span>, el "+pct(div0(mg, base-mg)*100)+" sobre el costo.</li>"+
      "<li>Con factura salió el "+(div0(fa, cob)*100).toFixed(0)+"%.</li>"+
      "<li>Ticket promedio: <span class='cifra'>"+fmt(div0(cob, vs.length))+"</span>.</li></ul>";
  }},
  {b:"¿Qué compro esta semana?", k:["compro","comprar","reponer","reposicion","pedido","falta","stock"], f(){
    const bajo = PRODUCTOS.filter(p=>p.stock<=3).sort((a,b)=>a.stock-b.stock);
    if(!bajo.length) return "No hay artículos con 3 o menos en depósito.";
    const porProv = {};
    for(const p of bajo){ (porProv[p.prov]=porProv[p.prov]||[]).push(p); }
    const lineas = Object.entries(porProv).sort((a,b)=>b[1].length-a[1].length).slice(0,4);
    const costo = bajo.reduce((a,p)=>a+p.costo*(6-p.stock),0);
    return "Hay <b>"+bajo.length+"</b> artículos con 3 o menos en depósito. Reponiendo hasta 6 de cada uno, el pedido sale <b class='cifra'>"+fmt(costo)+"</b>.<ul>"+
      lineas.map(([pr,arr])=>"<li><b>"+pr+"</b>: "+arr.length+" artículos — "+arr.slice(0,3).map(p=>p.tit.split("·")[0].slice(0,30)).join(", ")+(arr.length>3?"…":"")+"</li>").join("")+
      "</ul>Antes de mandar el pedido a "+lineas[0][0]+", fijate en Listas que tengas su lista nueva cargada.";
  }},
  {b:"¿Quién vende mejor?", k:["mostrador","puesto","vendedor","empleado","quien vende","mejor"], f(){
    const pm = {};
    if(!S.ventas.length) return "Todavía no hubo ventas hoy.";
    for(const v of S.ventas){ const k=v.vend||"—"; pm[k]=pm[k]||{v:0,m:0,n:0}; pm[k].v+=ventaBase(v); pm[k].m+=ventaMargen(v); pm[k].n++; }
    const o = Object.entries(pm).map(([k,x])=>({k, mg:x.m, pc:div0(x.m, x.v-x.m)*100, n:x.n})).sort((a,b)=>b.mg-a.mg);
    return "Por margen dejado hoy:<ul>"+o.map(x=>"<li><b>"+x.k+"</b> — <span class='cifra'>"+fmt(x.mg)+
      "</span> en "+x.n+" ventas, "+pct(x.pc)+"</li>").join("")+
      "</ul>Ojo con leer esto como quién trabaja más: el de arriba puede estar vendiendo termotanques y el de abajo tornillos. Sirve para saber qué mercadería mueve cada uno.";
  }}
];

let chatArrancado = false;
function burbuja(quien, html){
  const c = document.getElementById("chat");
  const d = document.createElement("div");
  d.className = "bur " + quien;
  d.innerHTML = html;
  c.appendChild(d);
  c.scrollTop = c.scrollHeight;
}
function responder(txt){
  burbuja("yo", txt);
  const t = plano(txt);
  const hit = PREGUNTAS.find(p=>p.k.some(k=>t.includes(k)));
  setTimeout(()=>{
    if(hit) burbuja("el", hit.f());
    else burbuja("el","Esa todavía no la sé contestar. Lo que sí puedo: qué artículos pierden plata, cuánto se vendió hoy y cuánto dejó, qué hay que reponer y cómo viene cada vendedor.");
  }, 260);
}
function pintarAsistente(){
  if(!chatArrancado){
    chatArrancado = true;
    burbuja("el","Hola. Veo tus ventas de hoy, tu catálogo con costos y las listas de tus proveedores. Preguntame lo que quieras, o tocá una de abajo.");
    document.getElementById("sugeridas").innerHTML = PREGUNTAS.map((p,i)=>'<button data-p="'+i+'">'+p.b+'</button>').join("");
    document.getElementById("sabeHacer").innerHTML = [
      ["v","A","<b>Leer la lista del proveedor como llega.</b> PDF, Excel, o la foto del papel que mandaron por WhatsApp.","Es la parte que ningún sistema hace y la que más horas come hoy."],
      ["v","B","<b>Escribir las descripciones para la web</b> a partir de como está cargado el artículo en el sistema viejo.","“MUEBLE COLG 1 PTA LAVAT 1 AG TRAFUL” no se puede publicar. Pasarlo a mano son 10.000 artículos."],
      ["v","C","<b>Contestar preguntas sobre tus números</b> sin que nadie aprenda a sacar un reporte.","La queja número uno de los sistemas que hay es justo esa."],
      ["a","D","<b>Avisarte antes, no después.</b> Que te diga que un precio te va a dejar en rojo el día que llega la lista, no tres meses más tarde.","Es la diferencia entre un sistema que registra y uno que te cuida."]
    ].map(([c,n,t,e])=>'<div class="hz '+c+'"><span class="ic">'+n+'</span><p>'+t+'<em>'+e+'</em></p></div>').join("");
  }
}
document.getElementById("sugeridas").addEventListener("click",e=>{
  const b = e.target.closest("button[data-p]"); if(!b) return;
  responder(PREGUNTAS[+b.dataset.p].b);
});
document.getElementById("preg").addEventListener("keydown",e=>{
  if(e.key!=="Enter") return;
  const v = e.target.value.trim(); if(!v) return;
  e.target.value = ""; responder(v);
});

/* ------------------------------------------- preguntarle hablando ----
   El navegador escucha y escribe lo que oye; cuando la frase termina,
   la pregunta sale sola. Sirve con las manos ocupadas, que es como
   trabaja el del mostrador. Chrome y Edge lo tienen; otros no. */
(function microfono(){
  const Rec = window.SpeechRecognition || window.webkitSpeechRecognition;
  const bot = document.getElementById("mic");
  const caja = document.getElementById("preg");
  let rec = null, escuchando = false;

  bot.addEventListener("click",()=>{
    if(!Rec){
      toast("Este navegador no deja dictar. En Chrome o Edge sí anda.");
      return;
    }
    if(escuchando){ rec.stop(); return; }
    rec = new Rec();
    rec.lang = "es-AR";
    rec.interimResults = true;
    rec.continuous = false;
    rec.onstart = ()=>{
      escuchando = true; bot.classList.add("on");
      caja.placeholder = "Te escucho… hablá tranquilo";
    };
    rec.onresult = e=>{
      let t = "";
      for(const r of e.results) t += r[0].transcript;
      caja.value = t.trim();
      if(e.results[e.results.length-1].isFinal){
        const v = caja.value.trim();
        if(v){ caja.value = ""; responder(v); }
      }
    };
    rec.onerror = ev=>{
      toast(ev.error==="not-allowed" || ev.error==="service-not-allowed"
        ? "Hay que darle permiso al micrófono: está en el candado de la barra de direcciones."
        : (ev.error==="no-speech" ? "No se escuchó nada. Probá de nuevo." : "No se entendió. Probá de nuevo."));
    };
    rec.onend = ()=>{
      escuchando = false; bot.classList.remove("on");
      caja.placeholder = "Preguntá lo que quieras, o tocá el micrófono y hablá";
    };
    rec.start();
  });
})();

/* ============================== los campos del pedido, los mismos de GBP */
/* La pantalla de GBP (Pedidos - Generar y Emitir) te hace bajar a mano, en
   cada pedido: documento a emitir, condicion de venta, vendedor, descuento,
   entregar por, lista de precios y deposito. Son los mismos campos que hay
   aca. La diferencia es que aca vienen elegidos, abajo dice por que, y si
   no te gusta lo cambias. */
const VENDEDORES = ["Mauro","Horacio","Agustín","Freddy","Daniel","Carlos","Miguel","Damián","Mariano"];
// El puesto no se elige: es donde esta sentado cada uno. Nadie se cambia de
// mostrador en el medio de una venta; si cambia, es porque cambio el usuario.
const PUESTO_DE = {
  "Mauro":"Mostrador 1", "Horacio":"Mostrador 2", "Agustín":"Mostrador 3",
  "Freddy":"Mostrador 4", "Daniel":"Mostrador 5", "Carlos":"Mostrador 1",
  "Miguel":"Mostrador 2", "Damián":"Mostrador 3",
};
const puestoDe = u => PUESTO_DE[u] || "Mostrador 1";
/* Con quién se entró al sistema: lo pone el servidor en PUNTO_YO (ver
   src/app/sistema/route.ts). Damián, 22/11/2026: "podes ponerle login
   al sistema punto". El que entra vende a su nombre; si no estaba en la
   lista de vendedores, se suma. "admin" no es una persona: con ese se sigue
   eligiendo a mano. var: lo mira pintarUsuarios() en el arranque. */
var VENDEDOR_LOGIN = (function(){
  const yo = (typeof PUNTO_YO === "object" && PUNTO_YO) ? PUNTO_YO : null;
  if(!yo || !yo.usuario || yo.usuario === "admin") return null;
  const nombre = String(yo.nombre || yo.usuario).replace(/[<>&"']/g, "").trim();
  const pila = plano(nombre).split(/\\s+/)[0], usu = plano(String(yo.usuario));
  const ya = VENDEDORES.find(v => { const p = plano(v); return p === pila || p === usu; });
  if(ya) return ya;
  const primero = nombre.split(/\\s+/)[0];
  if(!primero) return null;
  const lindo = primero.charAt(0).toUpperCase() + primero.slice(1);
  VENDEDORES.push(lindo);
  return lindo;
})();
const DOCUMENTOS = ["01.Factura A","02.Factura B","03.Presupuesto","04.Remito","05.Pedido interno"];
const ENTREGAS = ["00-Retira en Local","01-Reparto propio CABA/GBA","02-Transporte a cargo del cliente"];
// V.0.11.249 (Damián: "las listas son LISTA MAYORISTA, LISTA 1 Y LISTA 2").
const LISTAS = ["00.Lista Mayorista","01.Lista 1","02.Lista 2"];
/* Los mismos dos depositos, escritos como los pide el pedido. */
const DEP_OPC = ["01-Dep "+DEPOSITOS.BA, "02-Dep "+DEPOSITOS.TS];
/** El que le toca a la sucursal en la que estas parado. */
const depOpcDe = () => depAct()==="BA" ? DEP_OPC[0] : DEP_OPC[1];

const PEDCFG = { doc:null, cond:null, entrega:null, lista:null, dep:null, desc:0 };

/** Que comprobante corresponde, mirando la condicion fiscal del cliente. */
function docDe(c){
  if(!c) return ["02.Factura B","no hay cliente elegido"];
  if(c.t==="Responsable Inscripto") return ["01.Factura A","es responsable inscripto"];
  if(c.t==="IVA Exento") return ["02.Factura B","está exento de IVA"];
  return ["02.Factura B","es consumidor final"];
}
/** Si puede comprar en cuenta corriente o tiene que pagar ahora. */
function condDe(c){
  if(!c || c.lim<=0) return ["02-Transferencia","no tiene cuenta corriente abierta"];
  if(c.saldo>c.lim) return ["02-Transferencia","ya se pasó del límite de su cuenta"];
  return ["08-Cuenta corriente 30 días","tiene cuenta y le queda "+fmt(c.lim-c.saldo)];
}
function listaDe(c){
  return (c && c.lim>0)
    ? ["03.Lista 3 corralón","compra en cuenta: le toca la de corralón"]
    : ["02.Lista 2","venta al público"];
}
function entregaPorDe(c){
  return (c && c.lim>0)
    ? ["01-Reparto propio CABA/GBA","los pedidos de cuenta se mandan"]
    : ["00-Retira en Local","lo más común en mostrador"];
}

function campo(id, et, opciones, valor, porque, auto){
  return '<div class="campo'+(auto?" auto":"")+'">'+
    '<label for="'+id+'">'+et+'</label>'+
    '<select id="'+id+'" data-k="'+id+'">'+
      opciones.map(function(o){ return '<option'+(o===valor?' selected':'')+'>'+o+'</option>'; }).join("")+
    '</select>'+
    (porque ? '<span class="por">'+porque+'</span>' : '')+
  '</div>';
}

function pintarCamposPedido(){
  const c = clienteDe(PED.cliente);
  const sDoc = docDe(c), sCond = condDe(c), sLis = listaDe(c), sEnt = entregaPorDe(c);
  // Lo que eligieron a mano manda; si no, va la sugerencia.
  const vDoc  = PEDCFG.doc     || sDoc[0];
  const vCond = PEDCFG.cond    || sCond[0];
  const vLis  = PEDCFG.lista   || sLis[0];
  const vEnt  = PEDCFG.entrega || sEnt[0];
  const hoy = new Date().toLocaleDateString("es-AR");

  document.getElementById("camposPed").innerHTML =
    campo("fDoc","Documento a emitir",DOCUMENTOS,vDoc,sDoc[1],!PEDCFG.doc)+
    campo("fCond","Condición de venta",Object.keys(MULT).concat(["09-Cheque a 30 días"]),vCond,sCond[1],!PEDCFG.cond)+
    campo("fLista","Lista de precios",LISTAS,vLis,sLis[1],!PEDCFG.lista)+
    campo("fEnt","Entregar por",ENTREGAS,vEnt,sEnt[1],!PEDCFG.entrega)+
    '<div class="campo"><label for="fVend">Vendedor</label>'+
      '<input id="fVend" type="text" readonly value="'+S.usuario+'" style="background:var(--surface-2);color:var(--ink-2)">'+
      '<span class="por">sale de tu usuario</span></div>'+
    campo("fDep","Depósito",DEP_OPC,PEDCFG.dep||depOpcDe(),"el de "+sucAct().n,!PEDCFG.dep)+
    '<div class="campo"><label for="fDesc">Descuento</label>'+
      '<input id="fDesc" data-k="fDesc" type="number" min="0" max="40" step="1" value="'+PEDCFG.desc+'">'+
      '<span class="por">'+(PEDCFG.desc>0?"en por ciento, sobre toda la mercadería":"sin descuento")+'</span></div>'+
    '<div class="campo"><label for="fNro">Número y fecha</label>'+
      '<input id="fNro" type="text" value="P-'+PED.nro+' · '+hoy+'" readonly style="background:var(--surface-2);color:var(--ink-2)">'+
      '<span class="por">sale solo, no hay que pedirlo</span></div>';
}

document.getElementById("camposPed").addEventListener("change",function(e){
  const k = e.target.dataset.k; if(!k) return;
  const v = e.target.value;
  if(k==="fDoc")   PEDCFG.doc = v;
  if(k==="fCond")  PEDCFG.cond = v;
  if(k==="fLista") PEDCFG.lista = v;
  if(k==="fEnt")   PEDCFG.entrega = v;
  if(k==="fDep")   PEDCFG.dep = v;
  if(k==="fDesc")  PEDCFG.desc = Math.max(0, Math.min(40, +v||0));
  pintarPedido();
});

