setTimeout(() => { for(const id of ["fSubir", "cxSubirPrv"]){ const b = document.getElementById(id); if(b) b.hidden = !puede("importar"); } }, 0);

/* ============================== LO QUE PIDEN LOS CLIENTES (V.0.11.260)
   Daniel, 25/11/2026: "en la parte de vender o presupuestar ... un botón que
   diga notas donde yo pueda ingresar una nota de texto o voz donde sugiera
   algún producto que me piden los clientes, eso debería después mandarse al
   panel artículos como una notificación arriba o gerencia ... o agruparlos a
   todos que aparezcan en algún lado donde la gerencia hace los pedidos".
   - "Notas" en Venta y en Pedidos: se escribe o se dicta (como el Asistente).
   - En Proveedores (donde se arman los pedidos), agrupado: lo que piden igual
     va junto (src/lib/punto-notas-reglas.ts), lo más pedido arriba. Se marca
     "Ya lo pedí" o "Descartar"; nada se borra.
   - Arriba de todo, para el que arma los pedidos, el aviso de cuántas hay sin
     resolver. Servidor: /sistema/notas. */
const NC_URL = "/sistema/notas";
const NC = { d:null, error:"", ver:"pend", abiertos:{} };
const ncVe = () => (puede("proveedores") || puede("gerencia")) && vistaPermitida("proveedores");
function abrirNotaCliente(desde){
  const viejo = document.getElementById("ncForm"); if(viejo) viejo.remove();
  const idLocal = "nc" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  let cli = "";
  if(desde === "venta"){ try{ const c = clienteVta(); if(c && c.n && !/consumidor\\s*final/i.test(c.n)) cli = c.n; }catch(e){} }
  const Rec = window.SpeechRecognition || window.webkitSpeechRecognition;
  const fondo = document.createElement("div");
  fondo.className = "envio"; fondo.id = "ncForm";
  fondo.innerHTML = '<div class="envio-caja" style="width:min(560px,100%)" role="dialog" aria-label="Lo que pidió el cliente">' +
    '<div class="envio-h"><h3>Lo que pidió el cliente</h3><button class="x" type="button" data-nc-no aria-label="cerrar">×</button></div>' +
    '<p class="envio-n">Algo que el cliente buscaba y no tenemos (o no alcanzó). Lo ve Gerencia en Proveedores, junto con lo que piden los demás, para pedirlo.</p>' +
    '<div class="campos">' +
      '<div class="campo ancho"><label for="ncTexto">¿Qué pidió? *</label>' +
        '<textarea id="ncTexto" rows="3" maxlength="500" placeholder="Ej.: grifería FV Allegro de cocina; tanque de 1000 litros negro; flexible de 60 cm"></textarea></div>' +
      (Rec ? '<div class="campo ancho"><button class="b2 nc-mic" type="button" id="ncMic">Dictar con el micrófono</button></div>' : '') +
      '<div class="campo"><label for="ncCant">¿Cuántos? (opcional)</label><input id="ncCant" type="number" min="1" step="1" inputmode="numeric"></div>' +
      '<div class="campo"><label for="ncCli">Cliente (opcional)</label><input id="ncCli" type="text" maxlength="120" autocomplete="off" value="' + atrib(cli) + '"></div>' +
    '</div>' +
    '<div class="envio-acc"><button class="b3" type="button" data-nc-no>Cancelar</button><button class="b1" type="button" id="ncOk">Guardar la nota</button></div></div>';
  document.body.appendChild(fondo);
  const $ = id => fondo.querySelector("#" + id);
  let porVoz = false, rec = null, escuchando = false;
  const fin = () => { try{ if(rec && escuchando) rec.stop(); }catch(e){} fondo.remove(); };
  fondo.addEventListener("keydown", e => { if(e.key === "Escape"){ e.preventDefault(); e.stopPropagation(); fin(); } });
  if(Rec) $("ncMic").addEventListener("click", () => {
    const b = $("ncMic"), caja = $("ncTexto");
    if(escuchando){ rec.stop(); return; }
    rec = new Rec(); rec.lang = "es-AR"; rec.interimResults = true; rec.continuous = false;
    const antes = caja.value.trim();
    rec.onstart = () => { escuchando = true; b.classList.add("on"); b.textContent = "Te escucho… (tocá para cortar)"; };
    rec.onresult = e => {
      let t = ""; for(const r of e.results) t += r[0].transcript;
      caja.value = (antes ? antes + " " : "") + t.trim(); porVoz = true;
    };
    rec.onerror = ev => toast(ev.error === "not-allowed" || ev.error === "service-not-allowed"
      ? "Hay que darle permiso al micrófono: está en el candado de la barra de direcciones."
      : ev.error === "no-speech" ? "No se escuchó nada. Probá de nuevo." : "No se entendió. Probá de nuevo.");
    rec.onend = () => { escuchando = false; b.classList.remove("on"); b.textContent = "Dictar con el micrófono"; };
    rec.start();
  });
  fondo.addEventListener("click", async ev => {
    if(ev.target.closest("[data-nc-no]")){ fin(); return; }
    if(!ev.target.closest("#ncOk")) return;
    const texto = $("ncTexto").value.trim();
    if(texto.length < 3){ toast("Escribí (o dictá) qué pidió el cliente."); $("ncTexto").focus(); return; }
    const cant = $("ncCant").value.trim();
    const ok = $("ncOk"); ok.disabled = true; ok.textContent = "Guardando…";
    const r = await pedirJson("POST", NC_URL, { accion:"anotar", yo: soyYo(), idLocal, texto, porVoz, cantidad: cant ? +cant : null,
      cliente: $("ncCli").value.trim(), sucursal: sucDeTrabajo() || S.suc });
    if(r.error){ ok.disabled = false; ok.textContent = "Guardar la nota"; toast("No se guardó: " + r.error); return; }
    fin();
    toast("Nota guardada: la ve Gerencia en Proveedores.");
    traerAvisoNotas().catch(() => {});
  });
  setTimeout(() => $("ncTexto").focus(), 30);
}
document.getElementById("btnNotaVta").addEventListener("click", () => abrirNotaCliente("venta"));
document.getElementById("btnNotaPed").addEventListener("click", () => abrirNotaCliente("pedido"));

async function pintarNotasCli(){
  const card = document.getElementById("ncCard"); if(!card) return;
  card.hidden = !(puede("proveedores") || puede("gerencia"));
  if(card.hidden) return;
  if(!NC.d) document.getElementById("ncLista").innerHTML = '<p class="cx-nota">Cargando…</p>';
  const d = await pedirJson("GET", NC_URL + "?dias=60");
  if(d.error){ NC.error = d.error; } else { NC.d = d; NC.error = ""; }
  pintarListaNc();
  traerAvisoNotas().catch(() => {});
  // V.0.11.262: el botón de arriba (con los demás de Proveedores), con cuántas hay.
  document.getElementById("ncAct").hidden = false;
  const n = NC.d ? (NC.d.grupos || []).reduce((s, g) => s + g.veces, 0) : 0;
  const acc = document.querySelector('#accPrv [data-prv="ncAct"]');
  if(acc) acc.innerHTML = '<span class="ic">' + icoSvg("message") + '</span>Lo que piden los clientes' + (n ? ' (' + n + ')' : '');
  try{ pintarAccPrv(); }catch(e){}
}
document.getElementById("ncAct").addEventListener("click", () => pintarNotasCli());
function pintarListaNc(){
  const box = document.getElementById("ncLista"), cnt = document.getElementById("ncCount"); if(!box) return;
  if(NC.error && !NC.d){ box.innerHTML = '<p class="cx-av mal">' + txt(NC.error) + '</p>'; cnt.textContent = ""; return; }
  if(!NC.d) return;
  const gs = NC.d.grupos || [], res = NC.d.resueltos || [];
  const sinRes = gs.reduce((s, g) => s + g.veces, 0);
  cnt.textContent = sinRes ? sinRes + (sinRes === 1 ? " nota sin resolver" : " notas sin resolver") + " · " + gs.length + (gs.length === 1 ? " cosa distinta" : " cosas distintas") : "nada sin resolver";
  const quien = n => txt(n.usuario) + " · " + txt(sucDe(n.sucursal).n) + " · " + fechaHoraAR(n.creadoEn) +
    (n.cantidad ? " · " + n.cantidad + " u." : "") + (n.cliente ? " · " + txt(n.cliente) : "") + (n.porVoz ? " · dictado" : "");
  if(NC.ver === "res"){
    box.innerHTML = res.length ? res.map(n => '<div class="nc-grupo"><div class="nc-tx">' + txt(n.texto) +
        '<small>' + (n.estado === "pedida" ? "Pedido" : "Descartado") + ' por ' + txt(n.resueltoPor || "") + ' el ' + fechaHoraAR(n.resueltoEn) +
        (n.motivo ? ' · ' + txt(n.motivo) : '') + '<br>Lo anotó ' + quien(n) + '</small></div>' +
        '<div class="nc-acc"><button class="b3" type="button" data-nc-volver="' + atrib(n.id) + '">Volver a pendiente</button></div></div>').join("")
      : '<p class="cx-nota">Nada resuelto en los últimos 60 días.</p>';
    return;
  }
  if(!gs.length){ box.innerHTML = '<p class="cx-nota">No hay nada sin resolver. Cuando un vendedor anote lo que pidió un cliente, aparece acá.</p>'; return; }
  box.innerHTML = gs.map((g, i) => {
    const abierto = !!NC.abiertos[g.clave];
    return '<div class="nc-grupo"><div class="nc-tx"><span class="nc-veces" title="veces que lo pidieron">' + g.veces + '</span>' + txt(g.texto) +
        '<small>' + (g.veces === 1 ? "Lo pidieron 1 vez" : "Lo pidieron " + g.veces + " veces") + (g.unidades ? " · " + g.unidades + " u." : "") +
        ' · ' + g.sucursales.map(s => txt(sucDe(s).n)).join(", ") + ' · lo anotó ' + g.usuarios.map(txt).join(", ") + ' · último ' + fechaHoraAR(g.ultima) + '</small></div>' +
      '<div class="nc-acc"><button class="b1" type="button" data-nc-g="' + i + '" data-nc-acc="pedida">Ya lo pedí</button>' +
        '<button class="b3" type="button" data-nc-g="' + i + '" data-nc-acc="descartada">Descartar</button>' +
        '<button class="b3" type="button" data-nc-g="' + i + '" data-nc-acc="ver">' + (abierto ? "Ocultar" : "Ver " + (g.veces === 1 ? "la nota" : "las " + g.veces)) + '</button></div>' +
      (abierto ? '<div class="nc-det">' + g.notas.map(n => '<div>«' + txt(n.texto) + '» · ' + quien(n) + '</div>').join("") + '</div>' : '') +
    '</div>';
  }).join("");
}
async function resolverNc(ids, estado, motivo){
  const r = await pedirJson("POST", NC_URL, { accion:"resolver", yo: soyYo(), ids, estado, motivo: motivo || "" });
  if(r.error){ toast("No se guardó: " + r.error); return; }
  toast(estado === "pedida" ? "Anotado como pedido." : estado === "descartada" ? "Descartado." : "Volvió a pendiente.");
  pintarNotasCli();
}
document.getElementById("ncLista").addEventListener("click", e => {
  const v = e.target.closest("[data-nc-volver]");
  if(v){ resolverNc([v.dataset.ncVolver], "nueva", ""); return; }
  const b = e.target.closest("[data-nc-g]"); if(!b || !NC.d) return;
  const g = (NC.d.grupos || [])[+b.dataset.ncG]; if(!g) return;
  const acc = b.dataset.ncAcc;
  if(acc === "ver"){ NC.abiertos[g.clave] = !NC.abiertos[g.clave]; pintarListaNc(); return; }
  const ids = g.notas.map(n => n.id);
  if(acc === "pedida"){
    const m = prompt("¿A quién se lo pediste o en qué pedido? (opcional)\\n\\n" + g.texto);
    if(m === null) return;
    resolverNc(ids, "pedida", m.trim());
  } else {
    const m = prompt("¿Por qué se descarta? (por ejemplo: lo tenemos, no se consigue, no lo vamos a trabajar)\\n\\n" + g.texto);
    if(m === null) return;
    resolverNc(ids, "descartada", m.trim());
  }
});
document.getElementById("ncVer").addEventListener("change", e => { NC.ver = e.target.value; pintarListaNc(); });

/* El aviso de arriba, para el que arma los pedidos. Se oculta con la X hasta
   que llegue una nota nueva. */
const NC_AVISO_KEY = "punto.notas.avisoCerrado";
function pintarAvisoNotas(a){
  const b = document.getElementById("ncAviso"); if(!b) return;
  if(!a || !a.nuevas || !ncVe()){ b.hidden = true; return; }
  const clave = a.nuevas + ":" + (a.ultima || "");
  let cerrado = ""; try{ cerrado = sessionStorage.getItem(NC_AVISO_KEY) || ""; }catch(e){}
  if(cerrado === clave){ b.hidden = true; return; }
  b.dataset.clave = clave;
  b.innerHTML = '<span><b>Lo que piden los clientes:</b> hay ' + a.nuevas + (a.nuevas === 1 ? ' nota sin resolver' : ' notas sin resolver') +
    (a.ultima ? ' (la última, ' + fechaHoraAR(a.ultima) + ')' : '') + '.</span>' +
    '<button class="b1 pg-ir" type="button" data-nc-ir>Ver</button>' +
    '<button class="pg-x" type="button" data-nc-cerrar aria-label="Ocultar el aviso" title="Ocultar hasta que llegue otra">×</button>';
  b.hidden = false;
}
async function traerAvisoNotas(){
  if(!ncVe()) return;
  const d = await pedirJson("GET", NC_URL + "?aviso=1");
  if(d.error) return;
  pintarAvisoNotas(d.aviso);
}
document.getElementById("ncAviso").addEventListener("click", e => {
  const b = document.getElementById("ncAviso");
  if(e.target.closest("[data-nc-cerrar]")){ try{ sessionStorage.setItem(NC_AVISO_KEY, b.dataset.clave || ""); }catch(e2){} b.hidden = true; return; }
  if(!e.target.closest("[data-nc-ir]")) return;
  NC.ver = "pend"; document.getElementById("ncVer").value = "pend";
  abrirVista("proveedores");
  setTimeout(() => { const c = document.getElementById("ncCard"); if(c && !c.hidden) c.scrollIntoView({ behavior:"smooth", block:"start" }); }, 80);
});
setTimeout(() => { traerAvisoNotas().catch(() => {}); }, 3000);
setInterval(() => { traerAvisoNotas().catch(() => {}); }, 10 * 60e3);

/* ============================== CIERRE POR INACTIVIDAD (V.0.11.259)
   Damián, 24/11/2026: "si pasa más de 2 horas sin actividad un usuario, se
   le cierra la sesión". Cuenta lo que hace la persona (mouse, teclado,
   toques, ruedita), no lo que la página consulta sola. La última vez queda
   en el navegador (localStorage "conesa.actividad"), compartida por las
   pestañas de Punto y por el panel /admin (src/app/admin/cierre-
   inactividad.tsx): lo que se hace en una cuenta para todas. 5 minutos antes
   avisa arriba. Lo anotado antes de entrar con esta sesión (PUNTO_YO.
   sesionDesde) es de otra y no cuenta. Al cerrarse, lo que se estaba armando
   queda guardado en esta compu (como con Salir). Si la compu estuvo apagada o
   el navegador cerrado más de 2 horas, al abrir Punto se cierra de una. */
const INACTIVO_MS = 2 * 60 * 60 * 1000, INACTIVO_AVISO_MS = 5 * 60 * 1000, INACTIVO_KEY = "conesa.actividad";
const INACT = { ultima: Date.now(), marcada: 0, cerrando: false, movio: 0 };
function inactGuardada(){
  let t = 0; try{ t = +localStorage.getItem(INACTIVO_KEY) || 0; }catch(e){}
  const desde = (typeof PUNTO_YO === "object" && PUNTO_YO && +PUNTO_YO.sesionDesde) || 0;
  return t && desde && t < desde ? 0 : t;
}
function inactMarcar(){
  const ahora = Date.now(); INACT.ultima = ahora;
  if(ahora - INACT.marcada > 15000){ INACT.marcada = ahora; try{ localStorage.setItem(INACTIVO_KEY, String(ahora)); }catch(e){} }
  const b = document.getElementById("inactAviso"); if(b && !b.hidden) b.hidden = true;
}
async function inactCerrar(alAbrir){
  if(INACT.cerrando) return;
  // Mientras se guarda un comprobante no se corta: se prueba en la próxima vuelta.
  try{ if(EMITIENDO) return; }catch(e){}
  INACT.cerrando = true;
  if(!alAbrir) try{ guardarLocal(); }catch(e){}
  try{ localStorage.removeItem(INACTIVO_KEY); }catch(e){}
  try{ await fetch("/api/admin/logout", { method:"POST", credentials:"same-origin" }); }catch(e){}
  location.href = "/sistema/entrar?volver=/sistema&motivo=inactividad";
}
function inactRevisar(){
  if(INACT.cerrando) return;
  const quieto = Date.now() - Math.max(INACT.ultima, inactGuardada());
  if(quieto >= INACTIVO_MS){ inactCerrar(false); return; }
  const b = document.getElementById("inactAviso"); if(!b) return;
  if(quieto >= INACTIVO_MS - INACTIVO_AVISO_MS){
    const min = Math.max(1, Math.ceil((INACTIVO_MS - quieto) / 60000));
    b.innerHTML = '<span><b>Hace casi 2 horas que no se usa Punto en esta compu.</b> En ' + min + (min === 1 ? ' minuto' : ' minutos') +
      ' se cierra la sesión: mové el mouse o tocá una tecla para seguir.</span>';
    b.hidden = false;
  } else if(!b.hidden) b.hidden = true;
}
/** Lo que se hace adentro de la Web (/admin) y del Simulador también cuenta. */
function inactEnMarco(f){
  if(!f || f.dataset.inact) return;
  f.dataset.inact = "1";
  f.addEventListener("load", () => {
    try{
      const d = f.contentDocument; if(!d) return;
      for(const ev of ["mousedown", "keydown", "wheel", "touchstart"]) d.addEventListener(ev, inactMarcar, { capture:true, passive:true });
    }catch(e){}
  });
}
(function(){
  const t = inactGuardada();
  if(t && Date.now() - t >= INACTIVO_MS){ setTimeout(() => inactCerrar(true), 0); return; }
  inactMarcar();
  for(const ev of ["mousedown", "keydown", "wheel", "touchstart"]) addEventListener(ev, inactMarcar, { capture:true, passive:true });
  addEventListener("mousemove", () => { const t2 = Date.now(); if(t2 - INACT.movio > 5000){ INACT.movio = t2; inactMarcar(); } }, { capture:true, passive:true });
  document.addEventListener("visibilitychange", () => { if(!document.hidden) inactRevisar(); });
  for(const f of document.querySelectorAll("iframe")) inactEnMarco(f);
  setInterval(inactRevisar, 30000);
})();

/* ============================== CAMBIO MASIVO DE PRECIOS (V.0.11.259)
   Damián, 24/11/2026: "agregame acá para modificar también masivamente, si
   quiero hacer cambio de margen en los artículos filtrados que me lo haga
   ... por ejemplo cambiar el margen de ganancia". Sobre todo lo que se ve con
   los filtros de Artículos (no solo las filas que entran en la pantalla).
   Va por el mismo camino que los cambios por Excel (/sistema/articulos/
   cambios): revisión antes, solo artículos que ya están, en Actividad y se
   puede deshacer. Las cuentas, con productoDeGbp() (las de la lista):
   - Margen: lo que deja la venta de contado sobre el costo (la columna
     Margen). Lista 2 = costo × (1 + %) × recargo de 1 pago; la Lista 1
     guarda la misma distancia con la 2 que tenía.
   - Lista 1: % sobre el costo; la 2 guarda su % sobre la 1.
   - Lista 2: % sobre la Lista 1 (la 1 no se toca).
   - Subir o bajar: las dos listas un % (negativo = bajar). */
const MS_MODOS = [
  { k:"margen", t:"Margen: lo que deja la venta de contado sobre el costo", costo:true,
    ayuda:"La columna Margen de la lista. La Lista 2 se arma para que el contado deje ese % sobre el costo (con flete); la Lista 1 queda a la misma distancia de la 2 que tenía." },
  { k:"l1", t:"Lista 1: % sobre el costo", costo:true,
    ayuda:"La Lista 1 = costo × (1 + %). La Lista 2 queda con el mismo % sobre la Lista 1 que tenía cada artículo." },
  { k:"l2", t:"Lista 2: % sobre la Lista 1", costo:false,
    ayuda:"La Lista 2 = Lista 1 × (1 + %). La Lista 1 no se toca." },
  { k:"subir", t:"Subir o bajar los precios (Lista 1 y Lista 2)", costo:false,
    ayuda:"Las dos listas suben ese %. Con un número negativo (−5) bajan." }
];
let MS = null;
const msPctTxt = n => (n > 0 ? "" : n < 0 ? "−" : "") + pTxt(Math.round(Math.abs(n) * 10) / 10) + " %";
function msFiltroTxt(){
  const sel = id => { const s = document.getElementById(id); if(!s || !s.value) return ""; const o = s.options[s.selectedIndex]; return o ? cxT(o.text).replace(/\\s*·\\s*[\\d.]+$/, "") : s.value; };
  const b = cxT((document.getElementById("fBusca") || {}).value || "");
  return [sel("fCat"), sel("fProv"), sel("fRub"), b ? "«" + b + "»" : ""].filter(Boolean).join(" · ") || "todos los artículos";
}
function msCalcular(){
  const pct = cxN(MS.pct), modo = MS_MODOS.find(x => x.k === MS.modo);
  MS.renglones = [];
  for(const p0 of (PROD_VER.todos || [])){
    const a = GBP_CRUDO[p0.cod];
    const r = { cod: p0.cod, tit: p0.tit, estado:"igual", avisos:[] };
    MS.renglones.push(r);
    if(!a || !p0.gbp){ r.estado = "no"; r.avisos.push("no es un artículo guardado en el servidor"); continue; }
    r.a = a;
    if(a.mon === "USD"){ r.estado = "no"; r.avisos.push("tiene el costo en dólares: cambialo en la ficha"); continue; }
    if(a.combo && Array.isArray(a.combo.piezas) && a.combo.piezas.length){ r.estado = "no"; r.avisos.push("es un combo: el precio sale de sus piezas"); continue; }
    const p = productoDeGbp(a); r.p = p;
    if(modo.costo && !p.dtoGbp){ r.estado = "no"; r.avisos.push("no tiene la lista y los descuentos del proveedor (el costo sale de la Lista 1): no se puede calcular sobre el costo"); continue; }
    if(pct == null) continue;
    const L1 = +a.lista1, L2 = +a.lista2, rel = L1 > 0 && L2 > 0 ? L2 / L1 : 1.25;
    let n1, n2;
    if(MS.modo === "margen"){ n2 = cent(p.costoProducto * (1 + pct / 100) * RECARGO_1PAGO); n1 = cent(n2 / rel); }
    else if(MS.modo === "l1"){ n1 = cent(p.costoProducto * (1 + pct / 100)); n2 = cent(n1 * rel); }
    else if(MS.modo === "l2"){ n1 = L1; n2 = cent(L1 * (1 + pct / 100)); }
    else { n1 = cent(L1 * (1 + pct / 100)); n2 = cent(L2 * (1 + pct / 100)); }
    if(!(n1 > 0) || !(n2 > 0)){ r.estado = "no"; r.avisos.push("el precio quedaría en cero o negativo"); continue; }
    r.d = {};
    if(!cxIgual(n1, L1, 0.005)) r.d.lista1 = n1;
    if(!cxIgual(n2, L2, 0.005)) r.d.lista2 = n2;
    if(!Object.keys(r.d).length) continue;
    r.p2 = productoDeGbp(cxAplicar(a, r.d));
    r.estado = "cambia";
    if(margen(r.p2) < 0) r.avisos.push("pierde plata: el contado queda debajo del costo");
    if(r.d.lista2 !== undefined && (r.d.lista1 !== undefined ? r.d.lista1 : L1) > (r.d.lista2 !== undefined ? r.d.lista2 : L2))
      r.avisos.push("la Lista 2 queda más barata que la Lista 1");
    if(!(r.cod in MS.tilde)) MS.tilde[r.cod] = !(margen(r.p2) < 0);
  }
}
function msCuenta(){
  const n = { cambia:0, no:0, igual:0, tildados:0 };
  for(const r of MS.renglones){ n[r.estado]++; if(r.estado === "cambia" && MS.tilde[r.cod]) n.tildados++; }
  return n;
}
function abrirMasivo(){
  if(!puede("importar")){ toast("Tu usuario no puede cambiar precios en masa (hace falta el permiso Importar)."); return; }
  const total = (PROD_VER.todos || []).length;
  if(!total){ toast("No hay artículos con esos filtros."); return; }
  const viejo = document.getElementById("msModal"); if(viejo) viejo.remove();
  MS = { modo:"margen", pct:"", tilde:{}, renglones:[], filtro:"cambia", aplicando:false, resultado:"", filtros: msFiltroTxt(), total };
  const fondo = document.createElement("div");
  fondo.className = "envio"; fondo.id = "msModal";
  fondo.innerHTML = '<div class="envio-caja cx-caja" role="dialog" aria-label="Cambiar precios de los artículos filtrados">' +
    '<div class="envio-h"><h3>Cambiar precios · ' + total.toLocaleString("es-AR") + (total === 1 ? ' artículo' : ' artículos') + '</h3>' +
      '<button class="x" type="button" data-ms-no aria-label="cerrar">×</button></div>' +
    '<div class="cx-cuerpo" id="msCuerpo"></div><div class="cx-pie" id="msPie"></div></div>';
  document.body.appendChild(fondo);
  fondo.addEventListener("keydown", e => { if(e.key === "Escape"){ e.preventDefault(); e.stopPropagation(); fondo.remove(); } });
  fondo.addEventListener("click", msClic);
  fondo.addEventListener("change", msCambio);
  fondo.addEventListener("input", e => { if(e.target.id === "msPct"){ MS.pct = e.target.value; msCalcular(); msPintarTabla(); } });
  msCalcular(); msPintar();
  cxTraerHist().then(() => { const h = document.getElementById("msHist"); if(h) h.innerHTML = cxHistHtml(); });
  setTimeout(() => { const i = document.getElementById("msPct"); if(i) i.focus(); }, 30);
}
function msPintar(){
  const c = document.getElementById("msCuerpo"); if(!c || !MS) return;
  const modo = MS_MODOS.find(x => x.k === MS.modo);
  c.innerHTML = '<p class="cx-nota" style="margin-top:12px">Los <b>' + MS.total.toLocaleString("es-AR") + '</b> artículos que ves con estos filtros: <b>' + txt(MS.filtros) + '</b>.' +
      ' Solo cambian la Lista 1 y la Lista 2; el costo no se toca.</p>' +
    '<div class="ms-opc"><div><label for="msModo">Qué cambiar</label><select id="msModo">' +
      MS_MODOS.map(m => '<option value="' + m.k + '"' + (m.k === MS.modo ? ' selected' : '') + '>' + txt(m.t) + '</option>').join("") + '</select></div>' +
    '<div><label for="msPct">' + (MS.modo === "subir" ? "Cuánto (%)" : "Porcentaje") + '</label><input id="msPct" type="text" inputmode="decimal" autocomplete="off" placeholder="' +
      (MS.modo === "margen" ? "objetivo: " + (S.objetivo || 35) : MS.modo === "subir" ? "5 o −5" : "25") + '" value="' + atrib(MS.pct) + '"></div></div>' +
    '<p class="cx-nota" id="msAyuda">' + txt(modo.ayuda) + '</p>' +
    '<div id="msRes">' + (MS.resultado || '') + '</div>' +
    '<div id="msTabla"></div>' +
    '<div class="cx-hist" id="msHist" style="margin:12px 0 10px">' + cxHistHtml() + '</div>';
  msPintarTabla();
}
function msPintarTabla(){
  const t = document.getElementById("msTabla"); if(!t || !MS) return;
  const n = msCuenta(), f = MS.filtro;
  const pct = cxN(MS.pct);
  let html = '<div class="cx-tabs">' + [["cambia", "Cambian", n.cambia], ["no", "No se pueden", n.no, true], ["igual", "Sin cambios", n.igual]]
    .map(([k, tt, c, mal]) => '<button type="button" data-ms-f="' + k + '" aria-pressed="' + (f === k) + '"' + (mal && c ? ' class="mal"' : '') + '>' + tt + ' (' + c.toLocaleString("es-AR") + ')</button>').join("") + '</div>';
  const lista = MS.renglones.filter(r => r.estado === f);
  if(pct == null && f === "cambia") html += '<p class="cx-nota">Escribí el porcentaje y te muestro cómo quedan los precios antes de aplicar.</p>';
  else if(!lista.length) html += '<p class="cx-nota">' + (f === "cambia" ? "Con ese porcentaje no cambia ninguno." : "Ninguno.") + '</p>';
  else {
    const tope = 600, flecha = (h, x, fmt) => cxIgual(h, x, 0.005) ? fmt(h) : '<span style="color:var(--ink-3)">' + fmt(h) + '</span> → <b>' + fmt(x) + '</b>';
    html += (f === "cambia" ? '<div class="cx-opc"><button class="b3" type="button" data-ms-todos="1" style="padding:3px 10px">Tildar todos</button>' +
        '<button class="b3" type="button" data-ms-todos="0" style="padding:3px 10px">Destildar todos</button></div>' : '') +
      '<div class="tabla-wrap" style="max-height:46vh;overflow:auto"><table class="densa cx-t"><thead><tr><th></th><th>Código / artículo</th>' +
      '<th class="r">Costo c/IVA</th><th class="r">Lista 1</th><th class="r">Lista 2</th><th class="r">Margen</th><th>Aviso</th></tr></thead><tbody>' +
      lista.slice(0, tope).map(r => {
        if(r.estado !== "cambia")
          return '<tr><td></td><td class="nom">' + txt(r.cod) + '<small>' + txt(r.tit || "") + '</small></td><td class="r">' + (r.p ? fmt2(cent(r.p.costo)) : '') +
            '</td><td class="r">' + (r.p ? fmt2(lista1De(r.p)) : '') + '</td><td class="r">' + (r.p ? fmt2(cent(r.p.unPago)) : '') + '</td><td class="r">' +
            (r.p ? msPctTxt(margen(r.p)) : '') + '</td><td>' + r.avisos.map(x => '<span class="cx-av">' + txt(x) + '</span>').join("") + '</td></tr>';
        const p = r.p, p2 = r.p2, m1 = margen(p), m2 = margen(p2);
        return '<tr><td><input type="checkbox" data-ms-t="' + atrib(r.cod) + '"' + (MS.tilde[r.cod] ? ' checked' : '') + ' aria-label="aplicar ' + atrib(r.cod) + '"></td>' +
          '<td class="nom">' + txt(r.cod) + '<small>' + txt(r.tit || "") + '</small></td>' +
          '<td class="r">' + fmt2(cent(p.costo)) + '</td>' +
          '<td class="r">' + flecha(lista1De(p), lista1De(p2), fmt2) + '</td>' +
          '<td class="r">' + flecha(cent(p.unPago), cent(p2.unPago), fmt2) + '</td>' +
          '<td class="r">' + flecha(m1, m2, msPctTxt) + '</td>' +
          '<td>' + r.avisos.map(x => '<span class="cx-av mal">' + txt(x) + '</span>').join("") + '</td></tr>';
      }).join("") +
      (lista.length > tope ? '<tr><td colspan="7" class="vacio">Se ven los primeros ' + tope + ' de ' + lista.length.toLocaleString("es-AR") + ' (se aplican todos los tildados)</td></tr>' : '') +
      '</tbody></table></div>';
  }
  t.innerHTML = html;
  const pie = document.getElementById("msPie");
  pie.innerHTML = '<button class="b3" type="button" data-ms-no>Cerrar</button>' +
    (n.cambia ? '<span class="cx-nota" style="margin:0 0 0 auto">' + n.tildados + ' de ' + n.cambia + ' tildados</span>' +
      '<button class="b1" type="button" data-ms-aplicar' + (n.tildados && !MS.aplicando ? '' : ' disabled') + '>' +
      (MS.aplicando ? 'Aplicando…' : 'Aplicar a ' + n.tildados + (n.tildados === 1 ? ' artículo' : ' artículos')) + '</button>' : '');
}
function msCambio(e){
  const t = e.target; if(!MS) return;
  if(t.id === "msModo"){ MS.modo = t.value; MS.tilde = {}; MS.resultado = ""; msCalcular(); msPintar(); return; }
  if(t.dataset.msT){ MS.tilde[t.dataset.msT] = t.checked; msPintarTabla(); }
}
async function msClic(e){
  const t = e.target; if(!MS) return;
  if(t.closest("[data-ms-no]")){ document.getElementById("msModal").remove(); return; }
  const fb = t.closest("[data-ms-f]"); if(fb){ MS.filtro = fb.dataset.msF; msPintarTabla(); return; }
  const td = t.closest("[data-ms-todos]");
  if(td){ const si = td.dataset.msTodos === "1"; for(const r of MS.renglones) if(r.estado === "cambia") MS.tilde[r.cod] = si; msPintarTabla(); return; }
  const dh = t.closest("[data-cx-desh]");
  if(dh){ await cxDeshacer(dh.dataset.cxDesh); if(MS && document.getElementById("msModal")){ MS.tilde = {}; MS.resultado = ""; msCalcular(); msPintar(); } return; }
  if(t.closest("[data-ms-aplicar]")) msAplicar();
}
async function msAplicar(){
  if(!MS || MS.aplicando) return;
  const van = MS.renglones.filter(r => r.estado === "cambia" && MS.tilde[r.cod]);
  if(!van.length) return;
  const modo = MS_MODOS.find(x => x.k === MS.modo), pct = cxN(MS.pct);
  const que = (MS.modo === "margen" ? "Margen al " : MS.modo === "l1" ? "Lista 1 al " : MS.modo === "l2" ? "Lista 2 al " : (pct >= 0 ? "Subir " : "Bajar ")) +
    pTxt(Math.abs(pct)) + " %" + (MS.modo === "l1" ? " sobre el costo" : MS.modo === "l2" ? " sobre la Lista 1" : MS.modo === "margen" ? " sobre el costo" : " las dos listas");
  const pierden = van.filter(r => margen(r.p2) < 0).length;
  if(!confirm(que + ": se cambian la Lista 1 y la 2 de " + van.length + " artículos (" + MS.filtros + ")." +
      (pierden ? "\\n\\nOJO: " + pierden + " quedan perdiendo plata." : "") + "\\n\\nSe puede deshacer después. ¿Aplico?")) return;
  MS.aplicando = true; msPintarTabla();
  const cambios = van.map(r => ({ cod: r.a.cod, antes: { lista: +r.a.lista || 0, lista1: +r.a.lista1 || 0, lista2: +r.a.lista2 || 0 }, despues: r.d }));
  const r = await pedirJson("POST", CX_URL, { accion:"aplicar", yo: soyYo(), origen:"masivo", marca: MS.filtros.slice(0, 60), archivo: que.slice(0, 120), cambios });
  MS.aplicando = false;
  if(r.error){ MS.resultado = '<p class="cx-res mal">No se aplicó: ' + txt(r.error) + '</p>'; msPintar(); return; }
  const partes = ["<b>Listo: " + r.actualizados + (r.actualizados === 1 ? " artículo cambiado" : " artículos cambiados") + "</b> (" + txt(que) + ")."];
  if(r.cambiados.length) partes.push(r.cambiados.length + " no se pisaron porque alguien los cambió mientras tanto.");
  if(r.malos.length) partes.push("No se pudieron: " + txt(r.malos.slice(0, 8).map(x => x.cod + " (" + x.motivo + ")").join(", ")) + ".");
  partes.push("Abajo, en Últimas subidas, lo podés deshacer.");
  toast("Listo: " + r.actualizados + " artículos con precio nuevo.");
  await traerDeGbp();
  try{ pintarProd(); }catch(e){}
  await cxTraerHist();
  MS.tilde = {}; msCalcular();
  MS.resultado = '<p class="cx-res' + (r.cambiados.length || r.malos.length ? ' mal' : '') + '">' + partes.join("<br>") + '</p>';
  msPintar();
}
document.getElementById("fMasivo").addEventListener("click", abrirMasivo);
setTimeout(() => { const b = document.getElementById("fMasivo"); if(b) b.hidden = !puede("importar"); }, 0);

/* ============================== AGENDA DE PAGOS (V.0.11.257)
   Damián, 24/11/2026: "NECESITO EN PROVEEDORES AGENDAS DE PAGO Y SETEARLAS
   CON FECHAS Y QUE ME AVISE EL SISTEMA QUE TENGO QUE REALIZAR PAGOS". Se
   cargan a mano: a quién, cuánto, cuándo vence (y si va en cuotas, cada
   cuántos días). Al pagarlo se anota en la cuenta de donde sale la plata.
   La franja de arriba avisa lo vencido, lo que vence hoy y lo que entra en
   los días de aviso de cada pago. Las reglas y la base:
   src/lib/punto-pagos-reglas.ts y src/app/sistema/pagos/route.ts. */
const PG_URL = "/sistema/pagos";
const PG = { d:null, error:"", ver:"pend", suc:"", sit:"", busca:"" };
const PG_FORMAS = { "":"Sin decir", transferencia:"Transferencia", efectivo:"Efectivo", cheque:"Cheque", echeq:"eCheq", otro:"Otro" };
const PG_SIT = { vencido:"Vencidos", hoy:"Vencen hoy", pronto:"Por vencer", despues:"Más adelante" };
const PG_TIPO_CTA = { efectivo:"efectivo", mercadopago:"Mercado Pago", banco:"banco" };
/** La agenda vive en Proveedores: hace falta el área y la solapa. */
const pgPuede = () => puede("pagos") && vistaPermitida("proveedores");
const pgDia = d => d ? String(d).split("-").reverse().join("/") : "";
const pgDiasEntre = (a, b) => Math.round((Date.parse(b + "T12:00:00Z") - Date.parse(a + "T12:00:00Z")) / 864e5);
const pgSumarDias = (d, n) => new Date(Date.parse(d + "T12:00:00Z") + n * 864e5).toISOString().slice(0, 10);
const pgHoy = () => new Date(Date.now() - 3 * 3600e3).toISOString().slice(0, 10);
const pgMarca = () => "pg" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const pgQue = p => txt(p.proveedor) + (p.concepto ? " · " + txt(p.concepto) : "") + (p.cuotas > 1 ? " · cuota " + p.cuota + "/" + p.cuotas : "");
function pgSituacion(p, hoy){
  if(p.estado !== "pendiente") return p.estado;
  const f = pgDiasEntre(hoy, p.vence);
  return f < 0 ? "vencido" : f === 0 ? "hoy" : f <= p.avisar ? "pronto" : "despues";
}
function pgSitTxt(p, hoy){
  if(p.estado === "pagado") return '<span class="pill p-ok">Pagado el ' + pgDia(p.pagadoDia) + '</span>';
  if(p.estado === "anulado") return '<span class="pill p-n">Anulado</span>';
  const f = pgDiasEntre(hoy, p.vence);
  if(f < 0) return '<span class="pill p-bad">Vencido hace ' + (-f) + (f === -1 ? ' día' : ' días') + '</span>';
  if(f === 0) return '<span class="pill p-warn">Vence hoy</span>';
  return '<span class="pill ' + (f <= p.avisar ? 'p-warn' : 'p-n') + '">En ' + f + (f === 1 ? ' día' : ' días') + '</span>';
}
/** Puede deshacer: gerencia (Cuentas y gastos), o el que lo pagó hoy. */
const pgPuedeDeshacer = (p, hoy) => puede("cuentas") || (p.pagadoPor === soyYo() && p.pagadoDia === hoy);

async function pintarPagos(){
  const card = document.getElementById("pgCard"); if(!card) return;
  card.hidden = !puede("pagos");
  document.getElementById("pgNuevo").hidden = card.hidden;
  if(card.hidden) return;
  const sel = document.getElementById("pgSuc");
  if(!sel.options.length){
    sel.innerHTML = '<option value="">Todas las razones sociales</option>' +
      SUCURSALES.filter(s => puedeSuc(s.id)).map(s => '<option value="' + s.id + '">' + txt(s.n) + '</option>').join("");
    sel.value = PG.suc;
  }
  if(!PG.d) pintarListaPg();
  const d = await pedirJson("GET", PG_URL + "?dias=120");
  if(d.error) PG.error = d.error; else { PG.d = d; PG.error = ""; }
  pintarListaPg();
  if(PG.d) pintarAvisoPagos(PG.d.resumen, PG.d.hoy);
}
function pintarListaPg(){
  const tb = document.getElementById("tbPg"), cnt = document.getElementById("pgCount"), tiles = document.getElementById("pgTiles");
  if(!tb) return;
  if(PG.error && !PG.d){ tb.innerHTML = '<tr><td colspan="8" class="vacio">' + txt(PG.error) + '</td></tr>'; cnt.textContent = ""; tiles.innerHTML = ""; return; }
  if(!PG.d){ tb.innerHTML = '<tr><td colspan="8" class="vacio">Cargando la agenda…</td></tr>'; cnt.textContent = ""; return; }
  const hoy = PG.d.hoy || pgHoy();
  const todos = (PG.d.pagos || []).filter(p => !PG.suc || p.sucursal === PG.suc);
  const r = { vencido:{ n:0, c:0 }, hoy:{ n:0, c:0 }, pronto:{ n:0, c:0 }, despues:{ n:0, c:0 } };
  for(const p of todos) if(p.estado === "pendiente"){ const s = pgSituacion(p, hoy); r[s].n++; r[s].c += Math.round(p.monto * 100); }
  tiles.innerHTML = ["vencido", "hoy", "pronto", "despues"].map(k =>
    '<div class="tile' + ((k === "vencido" || k === "hoy") && r[k].n ? " alerta" : "") + (PG.ver === "pend" && PG.sit === k ? " sel" : "") +
      '" data-pg-sit="' + k + '" role="button" tabindex="0" title="Tocá para ver solo estos (otra vez, todos)">' +
      '<div class="k">' + PG_SIT[k] + '</div><div class="v">' + fmt2(r[k].c / 100) + '</div>' +
      '<div class="d">' + (r[k].n ? r[k].n + (r[k].n === 1 ? " pago" : " pagos") : "ninguno") +
        (k === "pronto" ? " · dentro de los días de aviso" : k === "despues" ? " · todavía no avisa" : "") + '</div></div>').join("");
  const toks = plano(PG.busca).split(/\\s+/).filter(Boolean);
  const quiere = PG.ver === "pagados" ? "pagado" : PG.ver === "anulados" ? "anulado" : "pendiente";
  let lista = todos.filter(p => p.estado === quiere);
  if(quiere === "pendiente" && PG.sit) lista = lista.filter(p => pgSituacion(p, hoy) === PG.sit);
  if(toks.length) lista = lista.filter(p => {
    const h = plano(p.proveedor + " " + p.concepto + " " + p.nota + " " + (PG_FORMAS[p.forma] || ""));
    return toks.every(t => h.indexOf(t) >= 0);
  });
  if(quiere === "pendiente") lista.sort((a, b) => a.vence < b.vence ? -1 : a.vence > b.vence ? 1 : 0);
  else if(quiere === "pagado") lista.sort((a, b) => String(b.pagadoDia).localeCompare(String(a.pagadoDia)));
  const montoDe = p => p.estado === "pagado" && p.montoPagado != null ? p.montoPagado : p.monto;
  const total = lista.reduce((s, p) => s + Math.round(montoDe(p) * 100), 0) / 100;
  cnt.textContent = lista.length + (lista.length === 1 ? " pago" : " pagos") + " · " + fmt2(total) +
    (quiere === "pendiente" && PG.sit ? " · " + PG_SIT[PG.sit].toLowerCase() : "") + (PG.d.truncado ? " · hay más, no entran todos" : "");
  if(!lista.length){
    const hay = todos.some(p => p.estado === "pendiente");
    tb.innerHTML = '<tr><td colspan="8" class="vacio">' + (quiere !== "pendiente" ? "Nada en los últimos 120 días." :
      hay ? "Ninguno con ese filtro." : "No hay pagos agendados. Tocá <b>Nuevo pago</b> para cargar el primero.") + '</td></tr>';
    return;
  }
  const cuentaN = id => { const c = (PG.d.cuentas || []).find(x => x.id === id); return c ? c.nombre : ""; };
  tb.innerHTML = lista.map(p => {
    const s = pgSituacion(p, hoy), id = atrib(p.id);
    const acc = p.estado === "pendiente"
      ? '<button class="b1" type="button" data-pg-pagar="' + id + '">Pagar</button> <button class="b3" type="button" data-pg-ed="' + id + '">Editar</button> ' +
        '<button class="b3" type="button" data-pg-anu="' + id + '" title="No se va a pagar">Anular</button>'
      : p.estado === "pagado" && pgPuedeDeshacer(p, hoy) ? '<button class="b3" type="button" data-pg-desh="' + id + '" title="Vuelve a pendiente y anula el movimiento en la cuenta">Deshacer</button>' : '';
    const pagoDistinto = p.estado === "pagado" && p.montoPagado != null && Math.round(p.montoPagado * 100) !== Math.round(p.monto * 100);
    const det = p.estado === "pagado" ? "Pagó " + txt(p.pagadoPor || "") + (p.cuentaId ? " · de " + txt(cuentaN(p.cuentaId) || "una cuenta") : " · sin anotar en una cuenta")
      : p.estado === "anulado" ? "Anuló " + txt(p.anuladoPor || "") + (p.motivo ? ": " + txt(p.motivo) : "")
      : p.nota ? txt(p.nota) : "Lo agendó " + txt(p.creadoPor);
    return '<tr' + (p.estado === "pendiente" && (s === "vencido" || s === "hoy") ? ' class="pg-' + s + '"' : '') + '>' +
      '<td>' + pgDia(p.vence) + '</td>' +
      '<td class="nom">' + txt(p.proveedor) + '<small>' + det + '</small></td>' +
      '<td>' + txt(p.concepto || "—") + (p.cuotas > 1 ? ' <span class="pill p-n">cuota ' + p.cuota + '/' + p.cuotas + '</span>' : '') + '</td>' +
      '<td>' + txt(sucDe(p.sucursal).n) + '</td>' +
      '<td>' + txt(PG_FORMAS[p.forma] || "—") + '</td>' +
      '<td class="r">' + fmt2(montoDe(p)) + (pagoDistinto ? '<small style="display:block;color:var(--ink-3)">de ' + fmt2(p.monto) + '</small>' : '') + '</td>' +
      '<td>' + pgSitTxt(p, hoy) + '</td>' +
      '<td class="pg-acc">' + acc + '</td></tr>';
  }).join("");
}

/** Cargar uno nuevo (p = null) o cambiar uno pendiente. */
async function abrirFormPg(p){
  if(!puede("pagos")){ toast("Tu usuario no tiene la agenda de pagos."); return; }
  const viejo = document.getElementById("pgForm"); if(viejo) viejo.remove();
  try{ await cargarPrvSiFalta(); }catch(e){}
  const nuevo = !p, idLocal = pgMarca();
  const sucs = SUCURSALES.filter(s => puedeSuc(s.id));
  if(!sucs.length){ toast("Tu usuario no tiene ninguna razón social."); return; }
  const sucIni = p ? p.sucursal : (PG.suc || sucursalFija() || (puedeSuc(S.suc) ? S.suc : sucs[0].id));
  const prvs = (PRV.lista || []).filter(x => x && !x.inactivo);
  const fondo = document.createElement("div");
  fondo.className = "envio"; fondo.id = "pgForm";
  fondo.innerHTML = '<div class="envio-caja" style="width:min(680px,100%)" role="dialog" aria-label="Pago a proveedor">' +
    '<div class="envio-h"><h3>' + (nuevo ? "Agendar un pago" : "Cambiar el pago") + '</h3>' +
      '<button class="x" type="button" data-pgf-no aria-label="cerrar">×</button></div>' +
    '<p class="envio-n">' + (nuevo ? "A quién, cuánto y cuándo vence. Si va en cuotas (por ejemplo cheques a 30, 60 y 90 días), poné cuántas y cada cuántos días: el total se reparte." :
      "Cambiá la fecha, el monto o lo que haga falta." + (p.cuotas > 1 ? " Es la cuota " + p.cuota + " de " + p.cuotas + ": las otras no se tocan." : "")) + '</p>' +
    '<div class="campos">' +
      '<div class="campo ancho"><label for="pgfPrv">Proveedor *</label><input id="pgfPrv" type="text" list="pgfPrvOpc" maxlength="120" autocomplete="off" placeholder="Escribí y elegilo de la lista (o uno que no esté)">' +
        '<datalist id="pgfPrvOpc">' + prvs.map(x => '<option value="' + atrib(x.razonSocial) + '"></option>').join("") + '</datalist></div>' +
      '<div class="campo"><label for="pgfSuc">Paga *</label><select id="pgfSuc">' +
        sucs.map(s => '<option value="' + s.id + '"' + (s.id === sucIni ? ' selected' : '') + '>' + txt(s.n) + '</option>').join("") + '</select></div>' +
      '<div class="campo"><label for="pgfForma">Cómo se paga</label><select id="pgfForma">' +
        Object.keys(PG_FORMAS).map(k => '<option value="' + k + '">' + PG_FORMAS[k] + '</option>').join("") + '</select></div>' +
      '<div class="campo ancho"><label for="pgfConc">Concepto</label><input id="pgfConc" type="text" maxlength="120" autocomplete="off" placeholder="Factura A 0001-00001234, saldo de la cuenta, cheque n° …"></div>' +
      '<div class="campo"><label for="pgfMonto">' + (nuevo ? "Monto total *" : "Monto *") + '</label><input id="pgfMonto" type="text" inputmode="decimal" autocomplete="off" placeholder="0,00"></div>' +
      '<div class="campo"><label for="pgfVence">' + (nuevo ? "Vence (la primera) *" : "Vence *") + '</label><input id="pgfVence" type="date"></div>' +
      (nuevo ? '<div class="campo"><label for="pgfCuotas">Cuotas</label><input id="pgfCuotas" type="number" min="1" max="36" step="1" value="1"></div>' +
        '<div class="campo"><label for="pgfCada">Cada cuántos días</label><input id="pgfCada" type="number" min="1" max="366" step="1" value="30"></div>' : '') +
      '<div class="campo"><label for="pgfAvisar">Avisar (días antes)</label><input id="pgfAvisar" type="number" min="0" max="60" step="1" value="3"></div>' +
      '<div class="campo ancho"><label for="pgfNota">Nota</label><input id="pgfNota" type="text" maxlength="300" autocomplete="off" placeholder="opcional"></div>' +
    '</div>' +
    '<div class="pg-cuotas" id="pgfVer"></div>' +
    '<div class="envio-acc"><button class="b3" type="button" data-pgf-no>Cancelar</button>' +
      '<button class="b1" type="button" id="pgfOk">' + (nuevo ? "Agendar" : "Guardar") + '</button></div></div>';
  document.body.appendChild(fondo);
  const $ = id => fondo.querySelector("#" + id);
  if(p){
    $("pgfPrv").value = p.proveedor; $("pgfForma").value = p.forma || ""; $("pgfConc").value = p.concepto || "";
    $("pgfMonto").value = plata2(p.monto); $("pgfVence").value = p.vence; $("pgfAvisar").value = p.avisar; $("pgfNota").value = p.nota || "";
  }
  const ver = () => {
    if(!nuevo) return;
    const n = Math.max(1, Math.floor(+$("pgfCuotas").value || 1)), cada = Math.max(1, Math.floor(+$("pgfCada").value || 30));
    const m = aNum($("pgfMonto").value) || 0, v = $("pgfVence").value;
    $("pgfCada").closest(".campo").style.opacity = n > 1 ? "" : ".45";
    if(n < 2 || !(m > 0) || !v){ $("pgfVer").textContent = ""; return; }
    const tot = Math.round(m * 100), base = Math.floor(tot / n);
    $("pgfVer").textContent = n + " cuotas: " + Array.from({ length:n }, (_, i) =>
      pgDia(pgSumarDias(v, i * cada)) + " " + fmt2((i === n - 1 ? tot - base * (n - 1) : base) / 100)).join(" · ");
  };
  const fin = () => fondo.remove();
  fondo.addEventListener("input", ver);
  fondo.addEventListener("keydown", e => { if(e.key === "Escape"){ e.preventDefault(); e.stopPropagation(); fin(); } });
  fondo.addEventListener("click", async ev => {
    if(ev.target.closest("[data-pgf-no]")){ fin(); return; }
    if(!ev.target.closest("#pgfOk")) return;
    const nombre = $("pgfPrv").value.replace(/\\s+/g, " ").trim();
    const elegido = prvs.find(x => clavePrv(x.razonSocial) === clavePrv(nombre));
    const cuerpo = { yo: soyYo(), proveedor: elegido ? elegido.razonSocial : nombre, proveedorId: elegido ? elegido.id : null,
      sucursal: $("pgfSuc").value, forma: $("pgfForma").value, concepto: $("pgfConc").value, monto: aNum($("pgfMonto").value) || 0,
      vence: $("pgfVence").value, avisar: $("pgfAvisar").value === "" ? 3 : +$("pgfAvisar").value, nota: $("pgfNota").value };
    if(!cuerpo.proveedor){ toast("Decí a qué proveedor hay que pagarle."); $("pgfPrv").focus(); return; }
    if(!(cuerpo.monto > 0)){ toast("Poné el monto."); $("pgfMonto").focus(); return; }
    if(!cuerpo.vence){ toast("Poné la fecha en que vence."); $("pgfVence").focus(); return; }
    if(nuevo){ cuerpo.accion = "cargar"; cuerpo.idLocal = idLocal; cuerpo.cuotas = +$("pgfCuotas").value || 1; cuerpo.cada = +$("pgfCada").value || 30; }
    else { cuerpo.accion = "cambiar"; cuerpo.id = p.id; cuerpo.version = p.version; }
    const ok = $("pgfOk"); ok.disabled = true; ok.textContent = "Guardando…";
    const r = await pedirJson("POST", PG_URL, cuerpo);
    if(r.error){ ok.disabled = false; ok.textContent = nuevo ? "Agendar" : "Guardar"; toast("No se guardó: " + r.error); return; }
    fin();
    toast(nuevo ? (r.pagos.length > 1 ? "Agendadas " + r.pagos.length + " cuotas: la primera vence el " + pgDia(r.pagos[0].vence) + "." :
      "Pago agendado: vence el " + pgDia(r.pagos[0].vence) + ".") : "Pago cambiado.");
    pintarPagos();
  });
  ver();
  setTimeout(() => $(p ? "pgfVence" : "pgfPrv").focus(), 30);
}

/** Marcarlo pagado: de qué cuenta sale, cuánto y qué día. */
function abrirPagarPg(p){
  const viejo = document.getElementById("pgPagar"); if(viejo) viejo.remove();
  const idLocal = pgMarca(), hoy = (PG.d && PG.d.hoy) || pgHoy();
  const cuentas = ((PG.d && PG.d.cuentas) || []).slice().sort((a, b) =>
    (a.sucursal === p.sucursal ? 0 : 1) - (b.sucursal === p.sucursal ? 0 : 1) || COLL_ES.compare(a.nombre, b.nombre));
  // La que va con la forma de pago, de la razón social que paga.
  const quiere = p.forma === "efectivo" ? "efectivo" : (p.forma === "transferencia" || p.forma === "cheque" || p.forma === "echeq") ? "banco" : "";
  const prefer = quiere ? cuentas.find(c => c.sucursal === p.sucursal && c.tipo === quiere) : null;
  const fondo = document.createElement("div");
  fondo.className = "envio"; fondo.id = "pgPagar";
  fondo.innerHTML = '<div class="envio-caja" style="width:min(580px,100%)" role="dialog" aria-label="Marcar pagado">' +
    '<div class="envio-h"><h3>Marcar pagado</h3><button class="x" type="button" data-pgp-no aria-label="cerrar">×</button></div>' +
    '<p class="envio-n"><b>' + pgQue(p) + '</b><br>' + txt(sucDe(p.sucursal).n) + ' · agendado ' + fmt2(p.monto) + ' · vence el ' + pgDia(p.vence) + '</p>' +
    '<div class="campos">' +
      '<div class="campo ancho"><label for="pgpCuenta">¿De dónde sale la plata?</label><select id="pgpCuenta">' +
        cuentas.map(c => '<option value="' + atrib(c.id) + '"' + (prefer && prefer.id === c.id ? ' selected' : '') + '>' + txt(c.nombre) + ' · ' +
          txt(sucDe(c.sucursal).n) + ' (' + (PG_TIPO_CTA[c.tipo] || txt(c.tipo)) + ')</option>').join("") +
        '<option value=""' + (prefer ? '' : ' selected') + '>No anotarlo en una cuenta</option></select>' +
        '<span class="por">' + (cuentas.length ? 'Se anota como «pago a proveedor» en esa cuenta (Gerencia → Cuentas y gastos). Si sale del efectivo, la caja lo descuenta.' :
          'Tu usuario no anota en las cuentas: queda marcado pagado y nada más.') + '</span></div>' +
      '<div class="campo"><label for="pgpMonto">Monto pagado *</label><input id="pgpMonto" type="text" inputmode="decimal" autocomplete="off"></div>' +
      '<div class="campo"><label for="pgpDia">Fecha del pago</label><input id="pgpDia" type="date" max="' + hoy + '"></div>' +
      '<div class="campo ancho"><label for="pgpDet">Detalle</label><input id="pgpDet" type="text" maxlength="200" autocomplete="off" placeholder="N° de transferencia o de cheque (opcional)"></div>' +
    '</div>' +
    '<div class="pg-cuotas" id="pgpResto"></div>' +
    '<div class="envio-acc"><button class="b3" type="button" data-pgp-no>Cancelar</button><button class="b1" type="button" id="pgpOk">Marcar pagado</button></div></div>';
  document.body.appendChild(fondo);
  const $ = id => fondo.querySelector("#" + id);
  $("pgpMonto").value = plata2(p.monto); $("pgpDia").value = hoy;
  const resto = () => {
    const m = aNum($("pgpMonto").value) || 0, r = Math.round(p.monto * 100) - Math.round(m * 100);
    $("pgpResto").innerHTML = m > 0 && r > 0 ? "Pagás menos de lo agendado: quedan <b>" + fmt2(r / 100) + "</b> pendientes, con el mismo vencimiento." :
      m > 0 && r < 0 ? "Pagás " + fmt2(-r / 100) + " más de lo agendado (un recargo o intereses)." : "";
  };
  const fin = () => fondo.remove();
  fondo.addEventListener("input", resto);
  fondo.addEventListener("keydown", e => { if(e.key === "Escape"){ e.preventDefault(); e.stopPropagation(); fin(); } });
  fondo.addEventListener("click", async ev => {
    if(ev.target.closest("[data-pgp-no]")){ fin(); return; }
    if(!ev.target.closest("#pgpOk")) return;
    const monto = aNum($("pgpMonto").value) || 0;
    if(!(monto > 0)){ toast("Poné cuánto se pagó."); $("pgpMonto").focus(); return; }
    const dia = $("pgpDia").value || hoy;
    if(dia > hoy){ toast("La fecha del pago no puede ser de más adelante."); return; }
    const ok = $("pgpOk"); ok.disabled = true; ok.textContent = "Guardando…";
    const r = await pedirJson("POST", PG_URL, { accion:"pagar", yo: soyYo(), id: p.id, version: p.version, idLocal,
      cuentaId: $("pgpCuenta").value || null, monto, dia, detalle: $("pgpDet").value });
    if(r.error){ ok.disabled = false; ok.textContent = "Marcar pagado"; toast("No se guardó: " + r.error); return; }
    fin();
    // La caja de efectivo se vuelve a leer la próxima vez (pudo salir de ahí).
    try{ EFE.en = 0; }catch(e){}
    toast("Pago marcado: " + fmt2(monto) + " a " + p.proveedor + (r.resto ? ". Quedan " + fmt2(r.resto.monto) + " pendientes." : "."));
    pintarPagos();
  });
  resto();
  setTimeout(() => $("pgpMonto").focus(), 30);
}

async function anularPg(p){
  const motivo = (prompt("¿Por qué se anula este pago? (queda en la agenda como anulado, no se paga)\\n\\n" + p.proveedor + " · " + fmt2(p.monto)) || "").trim();
  if(!motivo) return;
  const r = await pedirJson("POST", PG_URL, { accion:"anular", yo: soyYo(), id: p.id, version: p.version, motivo });
  if(r.error){ toast("No se anuló: " + r.error); return; }
  toast("Pago anulado.");
  pintarPagos();
}
async function deshacerPg(p){
  const motivo = (prompt("¿Por qué se deshace el pago? Vuelve a pendiente y, si se anotó en una cuenta, ese movimiento se anula.\\n\\n" +
    p.proveedor + " · " + fmt2(p.montoPagado != null ? p.montoPagado : p.monto)) || "").trim();
  if(!motivo) return;
  const r = await pedirJson("POST", PG_URL, { accion:"deshacer", yo: soyYo(), id: p.id, version: p.version, motivo });
  if(r.error){ toast("No se deshizo: " + r.error); return; }
  try{ EFE.en = 0; }catch(e){}
  toast("Listo: el pago volvió a pendiente.");
  pintarPagos();
}

/* El aviso de arriba: lo vencido, lo de hoy y lo que entró en los días de
   aviso. Se puede ocultar con la X: vuelve si cambia algo o al otro día. */
const PG_AVISO_KEY = "punto.pagos.avisoCerrado";
function marcarNavPg(n){
  const a = document.querySelector('#nav [data-v="proveedores"]'); if(!a) return;
  let s = a.querySelector(".pg-nav");
  if(!n){ if(s) s.remove(); return; }
  if(!s){ s = document.createElement("span"); s.className = "pg-nav"; a.appendChild(s); }
  s.textContent = n > 99 ? "99+" : String(n);
  s.title = n + (n === 1 ? " pago vencido o que vence hoy" : " pagos vencidos o que vencen hoy");
}
function pintarAvisoPagos(res, hoy){
  const b = document.getElementById("pgAviso"); if(!b) return;
  if(!res || !pgPuede()){ b.hidden = true; marcarNavPg(0); return; }
  const cero = { n:0, total:0 };
  const v = res.vencido || cero, h = res.hoy || cero, pr = res.pronto || cero;
  marcarNavPg(v.n + h.n);
  const clave = (hoy || pgHoy()) + ":" + v.n + ":" + h.n + ":" + pr.n;
  let cerrado = ""; try{ cerrado = sessionStorage.getItem(PG_AVISO_KEY) || ""; }catch(e){}
  if(!(v.n + h.n + pr.n) || cerrado === clave){ b.hidden = true; return; }
  const partes = [];
  if(v.n) partes.push("<b>" + v.n + (v.n === 1 ? " vencido" : " vencidos") + "</b> (" + fmt2(v.total) + ")");
  if(h.n) partes.push("<b>" + h.n + (h.n === 1 ? " vence hoy" : " vencen hoy") + "</b> (" + fmt2(h.total) + ")");
  if(pr.n) partes.push(pr.n + (pr.n === 1 ? " vence en los próximos días" : " vencen en los próximos días") + " (" + fmt2(pr.total) + ")");
  b.className = "pg-aviso" + (v.n ? " mal" : "");
  b.dataset.clave = clave;
  b.innerHTML = '<span><b>Pagos a proveedores:</b> ' + partes.join(" · ") + '</span>' +
    '<button class="b1 pg-ir" type="button" data-pg-ir>Ver la agenda</button>' +
    '<button class="pg-x" type="button" data-pg-cerrar aria-label="Ocultar el aviso" title="Ocultar hasta que cambie algo">×</button>';
  b.hidden = false;
}
async function traerAvisoPagos(){
  if(!pgPuede()) return;
  const d = await pedirJson("GET", PG_URL + "?aviso=1");
  if(d.error || !d.aviso) return;
  pintarAvisoPagos(d.aviso, d.hoy);
}
document.getElementById("pgAviso").addEventListener("click", e => {
  const b = document.getElementById("pgAviso");
  if(e.target.closest("[data-pg-cerrar]")){
    try{ sessionStorage.setItem(PG_AVISO_KEY, b.dataset.clave || ""); }catch(e2){}
    b.hidden = true; return;
  }
  if(!e.target.closest("[data-pg-ir]")) return;
  PG.ver = "pend"; PG.sit = ""; document.getElementById("pgVer").value = "pend";
  abrirVista("proveedores");
  setTimeout(() => { const c = document.getElementById("pgCard"); if(c && !c.hidden) c.scrollIntoView({ behavior:"smooth", block:"start" }); }, 80);
});
document.getElementById("pgNuevo").addEventListener("click", () => abrirFormPg(null));
document.getElementById("pgVer").addEventListener("change", e => { PG.ver = e.target.value; if(PG.ver !== "pend") PG.sit = ""; pintarListaPg(); });
document.getElementById("pgSuc").addEventListener("change", e => { PG.suc = e.target.value; pintarListaPg(); });
document.getElementById("pgBusca").addEventListener("input", e => { PG.busca = e.target.value; pintarListaPg(); });
function elegirSitPg(t){
  const k = t.dataset.pgSit;
  PG.sit = PG.ver === "pend" && PG.sit === k ? "" : k;
  PG.ver = "pend"; document.getElementById("pgVer").value = "pend";
  pintarListaPg();
}
document.getElementById("pgTiles").addEventListener("click", e => { const t = e.target.closest("[data-pg-sit]"); if(t) elegirSitPg(t); });
document.getElementById("pgTiles").addEventListener("keydown", e => {
  const t = e.target.closest("[data-pg-sit]"); if(t && (e.key === "Enter" || e.key === " ")){ e.preventDefault(); elegirSitPg(t); }
});
document.getElementById("tbPg").addEventListener("click", e => {
  const b = e.target.closest("[data-pg-pagar],[data-pg-ed],[data-pg-anu],[data-pg-desh]"); if(!b || !PG.d) return;
  const id = b.dataset.pgPagar || b.dataset.pgEd || b.dataset.pgAnu || b.dataset.pgDesh;
  const p = (PG.d.pagos || []).find(x => x.id === id); if(!p) return;
  if(b.dataset.pgPagar) abrirPagarPg(p);
  else if(b.dataset.pgEd) abrirFormPg(p);
  else if(b.dataset.pgAnu) anularPg(p);
  else deshacerPg(p);
});
